CREATE OR REPLACE FUNCTION public.accept_helios_handoff_v1(p_prep_id uuid, p_verifications jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_role public.app_role; v_status public.prep_status; v_item record; v_verify jsonb; v_actual int; v_required int;
  v_it_photos int; v_service_photos int; v_parts_total int; v_parts_confirmed boolean; v_name text;
begin
  v_role:=public.current_app_role();
  if v_role not in ('service'::public.app_role,'owner'::public.app_role) then raise exception 'Service or Owner access required'; end if;
  select status,(solar_panel_qty+battery_replacement_qty+camera_replacement_qty+sim_replacement_qty+micro_sd_qty),service_parts_confirmed
  into v_status,v_parts_total,v_parts_confirmed from public.prep_tickets where id=p_prep_id;
  if not found or v_status<>'released' then raise exception 'Service handoff not found or no longer waiting for Service'; end if;
  if not exists(select 1 from public.prep_items where prep_ticket_id=p_prep_id and equipment_type='Helios' and purpose in ('DELIVERY','SWAP')) then raise exception 'This handoff does not require the Helios field workflow'; end if;
  if coalesce(v_parts_total,0)>0 and not coalesce(v_parts_confirmed,false) then raise exception 'Verify the listed parts from IT before accepting this equipment'; end if;
  if jsonb_typeof(p_verifications)<>'array' then raise exception 'Equipment checkout verifications are required'; end if;
  for v_item in select * from public.prep_items where prep_ticket_id=p_prep_id order by item_order loop
    select value into v_verify from jsonb_array_elements(p_verifications) where value->>'item_id'=v_item.id::text limit 1;
    if v_verify is null then raise exception 'Missing equipment checkout verification for item %',v_item.item_order; end if;
    if trim(v_verify->>'unit_tag') is distinct from v_item.unit_tag then raise exception 'Unit tag does not match IT-prepared item %',v_item.item_order; end if;
    v_required:=coalesce(v_item.required_battery_count,0);
    if v_required>0 then
      v_actual:=coalesce((v_verify->>'battery_count')::int,-1);
      if v_actual<>v_item.battery_count or v_actual<v_required then raise exception 'Battery count does not match the IT-prepared item %',v_item.item_order; end if;
      if coalesce((v_verify->>'battery_verified')::boolean,false) is not true then raise exception 'Battery verification is required for item %',v_item.item_order; end if;
    else v_actual:=null; end if;
    if coalesce((v_verify->>'unit_confirmed')::boolean,false) is not true then raise exception 'Exact item confirmation is required for item %',v_item.item_order; end if;
    update public.prep_items set service_battery_count=v_actual,service_unit_confirmed=true,service_verified_by=auth.uid(),service_verified_at=now() where id=v_item.id;
  end loop;
  select count(*) into v_it_photos from public.handoff_evidence where prep_ticket_id=p_prep_id and stage='it' and kind='photo';
  if v_it_photos<1 then raise exception 'IT handoff photo proof is required before Service can accept the equipment'; end if;
  if not exists(select 1 from public.handoff_evidence where prep_ticket_id=p_prep_id and stage='service' and kind='signature') then raise exception 'Service receipt signature is required'; end if;
  if not exists(select 1 from public.service_solar_checks where prep_ticket_id=p_prep_id and completed_at is not null) then raise exception 'Complete the Helios yard solar test before accepting the handoff'; end if;
  if not exists(select 1 from public.service_solar_evidence where prep_ticket_id=p_prep_id and category='helios_yard' and kind='photo') then raise exception 'Helios yard-test photo proof is required'; end if;
  if not exists(select 1 from public.service_solar_evidence where prep_ticket_id=p_prep_id and category='helios_yard' and kind='signature') then raise exception 'Helios yard-test signature is required'; end if;
  v_name:=public.actor_display_name();
  update public.service_solar_checks set handoff_accepted_at=now(),handoff_accepted_by=auth.uid(),handoff_accepted_by_name=v_name,updated_at=now() where prep_ticket_id=p_prep_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.add_it_prep_item(p_prep_id uuid, p_equipment_type text, p_purpose text, p_recon_battery_count integer DEFAULT NULL::integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_status public.prep_status;
  v_expected integer;
  v_count integer;
  v_order integer;
  v_required integer;
  v_purpose public.prep_purpose;
  v_id uuid;
begin
  perform public.require_role(array['it'::public.app_role,'owner'::public.app_role]);

  select status,expected_unit_count into v_status,v_expected
  from public.prep_tickets where id=p_prep_id for update;
  if not found then raise exception 'Equipment prep not found'; end if;
  if v_status<>'draft'::public.prep_status then raise exception 'Only draft equipment prep can be changed'; end if;
  if v_expected is null then raise exception 'This prep was not created with the unit-by-unit workflow'; end if;

  select count(*),coalesce(max(item_order),0)+1
  into v_count,v_order
  from public.prep_items where prep_ticket_id=p_prep_id;
  if v_count>=v_expected then raise exception 'All equipment items for this ticket have already been created'; end if;

  if p_equipment_type not in ('Sniper','Ranger','Helios','Solar Spotter','Spotter','Recon 2','110V Stand','Solar Stand','Pole') then
    raise exception 'Invalid equipment type';
  end if;
  if p_purpose not in ('BACKUP','SWAP','DELIVERY') then raise exception 'Invalid purpose'; end if;
  v_purpose:=p_purpose::public.prep_purpose;
  if p_equipment_type='110V Stand' and v_purpose<>'SWAP'::public.prep_purpose then raise exception '110V Stand is available for SWAP only'; end if;
  if p_equipment_type='Solar Stand' and v_purpose not in ('SWAP'::public.prep_purpose,'DELIVERY'::public.prep_purpose) then raise exception 'Solar Stand is available for SWAP or DELIVERY only'; end if;

  v_required:=case p_equipment_type
    when 'Sniper' then 2
    when 'Ranger' then 1
    when 'Solar Spotter' then 0
    when 'Helios' then 1
    when 'Recon 2' then greatest(1,coalesce(p_recon_battery_count,1))
    when 'Solar Stand' then 0
    else 0 end;

  insert into public.prep_items(prep_ticket_id,item_order,equipment_type,purpose,required_battery_count)
  values(p_prep_id,v_order,p_equipment_type,v_purpose,v_required)
  returning id into v_id;

  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.add_it_prep_item_v2(p_prep_id uuid, p_item_order integer, p_equipment_type text, p_purpose text, p_recon_battery_count integer DEFAULT NULL::integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_status public.prep_status;
  v_expected integer;
  v_existing uuid;
  v_before integer;
  v_id uuid;
begin
  perform public.require_role(array['it'::public.app_role,'owner'::public.app_role]);

  select status,expected_unit_count
  into v_status,v_expected
  from public.prep_tickets
  where id=p_prep_id
  for update;

  if not found then raise exception 'Equipment prep not found'; end if;
  if v_status<>'draft'::public.prep_status then raise exception 'Only draft equipment prep can be changed'; end if;
  if v_expected is null then raise exception 'This prep was not created with the unit-by-unit workflow'; end if;
  if p_item_order<1 or p_item_order>v_expected then
    raise exception 'Unit position % is outside this ticket''s required % equipment items',p_item_order,v_expected;
  end if;

  select id into v_existing
  from public.prep_items
  where prep_ticket_id=p_prep_id and item_order=p_item_order
  for update;

  if found then
    return v_existing;
  end if;

  select count(*)::integer
  into v_before
  from public.prep_items
  where prep_ticket_id=p_prep_id and item_order<p_item_order;

  if v_before<>p_item_order-1 then
    raise exception 'Complete the earlier equipment items before creating Unit %',p_item_order;
  end if;

  v_id:=public.add_it_prep_item(
    p_prep_id,
    p_equipment_type,
    p_purpose,
    p_recon_battery_count
  );

  if not exists (
    select 1 from public.prep_items
    where id=v_id and prep_ticket_id=p_prep_id and item_order=p_item_order
  ) then
    raise exception 'Equipment item order changed while saving. Reopen this ticket and try again.';
  end if;

  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.add_it_truck_spare_unit(p_prep_id uuid, p_equipment_type text, p_recon_battery_count integer DEFAULT NULL::integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_status public.prep_status;
  v_order integer;
  v_required integer;
  v_id uuid;
begin
  perform public.require_role(array['it'::public.app_role,'owner'::public.app_role]);

  select status into v_status
  from public.prep_tickets where id=p_prep_id for update;
  if not found then raise exception 'Equipment prep not found'; end if;
  if v_status<>'draft'::public.prep_status then raise exception 'Truck spares can only be added before the Service handoff'; end if;

  if p_equipment_type not in ('Sniper','Ranger','Helios','Solar Spotter','Spotter','Recon 2') then
    raise exception 'Choose a camera/unit type for the truck spare';
  end if;

  v_required:=case p_equipment_type
    when 'Sniper' then 2
    when 'Ranger' then 1
    when 'Solar Spotter' then 0
    when 'Helios' then 1
    when 'Recon 2' then greatest(1,coalesce(p_recon_battery_count,1))
    else 0 end;

  select coalesce(max(item_order),0)+1 into v_order
  from public.prep_items where prep_ticket_id=p_prep_id;

  insert into public.prep_items(
    prep_ticket_id,item_order,equipment_type,purpose,required_battery_count
  )
  values(
    p_prep_id,v_order,p_equipment_type,'BACKUP'::public.prep_purpose,v_required
  )
  returning id into v_id;

  update public.prep_tickets
  set expected_unit_count=coalesce(expected_unit_count,0)+1
  where id=p_prep_id;

  insert into public.reports(kind,actor_id,actor_name,ticket_no,text)
  select 'TRUCK SPARE ADDED',auth.uid(),public.actor_display_name(),ticket_no,
    'IT added a fully checked '||p_equipment_type||' BACKUP unit for the Service truck.'
  from public.prep_tickets where id=p_prep_id;

  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_my_department_assignment(p_assignment_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_profile public.profiles%rowtype;
  v_assignment public.job_assignments%rowtype;
  v_name text;
  v_is_owner boolean;
  v_departure jsonb;
begin
  select * into v_profile from public.profiles where user_id=auth.uid() and active=true;
  if not found then raise exception 'Active account required.'; end if;
  v_is_owner := v_profile.role='owner';

  select * into v_assignment from public.job_assignments where id=p_assignment_id for update;
  if not found then raise exception 'Assignment not found.'; end if;
  if v_assignment.assignment_scope<>'department' or v_assignment.assignee_user_id is not null or v_assignment.status<>'assigned' then
    raise exception 'This department task has already been claimed or is no longer available.';
  end if;
  if not v_is_owner and v_assignment.assigned_role<>v_profile.role::text then
    raise exception 'This task belongs to a different technician department.';
  end if;

  if not v_is_owner
     and v_assignment.assigned_role='it'
     and lower(coalesce(v_assignment.work_type,''))='pickup'
     and not exists(
       select 1 from public.unit_returns r
       where trim(r.ticket_no)=trim(v_assignment.ticket_no)
         and r.status='waiting_it'
     ) then
    raise exception 'WAITING FOR SERVICE RETURN. This IT task is not available to claim yet.';
  end if;

  if not v_is_owner
     and v_assignment.assigned_role='service'
     and coalesce(v_assignment.requires_it_handoff,false)
     and not exists(
       select 1 from public.prep_tickets p
       where trim(p.ticket_no)=trim(v_assignment.ticket_no)
         and p.status in ('released','closed')
     ) then
    raise exception 'WAITING FOR IT HANDOFF. This Service task is not available to claim yet.';
  end if;

  if not v_is_owner and v_assignment.assigned_role='service' then
    v_departure:=public.service_departure_readiness_v1(auth.uid());
    if coalesce((v_departure->>'departure_ready')::boolean,false) is not true then
      raise exception 'NOT READY TO LEAVE SHOP. Complete the daily Truck / Trailer Inspection and required permanent truck inventory check/restock before claiming a new Service job.';
    end if;
  end if;

  v_name := coalesce(v_profile.full_name,v_profile.username,case when v_is_owner then 'Owner/Admin' else 'Technician' end);

  update public.job_assignments
  set assignee_user_id=auth.uid(),
      assignee_name=v_name,
      status='started',
      started_at=coalesce(started_at,now()),
      claimed_at=now(),
      updated_at=now()
  where id=p_assignment_id;

  update public.app_notifications
  set read_at=coalesce(read_at,now())
  where assignment_id=p_assignment_id and recipient_user_id<>auth.uid();

  insert into public.reports(kind,actor_id,actor_name,ticket_no,text)
  values(
    'DEPARTMENT TASK CLAIMED',auth.uid(),v_name,v_assignment.ticket_no,
    (case when v_assignment.assigned_role='it' then 'IT ' else 'Service ' end)||
    case when v_is_owner then 'Owner preview ' else 'Tech ' end||
    v_name||' claimed the department task and started the process.'
  );

  return p_assignment_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.close_prep_ticket(p_prep_id uuid, p_verifications jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_item record;
  v_verify jsonb;
  v_actual int;
  v_tag text;
  v_required int;
  v_no text;
  v_test boolean;
  v_name text;
  v_photos int;
  v_it_photos int;
  v_signed_at timestamptz;
  v_expected int;
  v_items int;
  v_parts_total int;
  v_parts_confirmed boolean;
  v_actor_id uuid;
  v_role public.app_role;
begin
  perform public.require_role(array['service'::public.app_role,'owner'::public.app_role]);
  v_role:=public.current_app_role();

  select ticket_no,is_test,expected_unit_count,
         (solar_panel_qty+battery_replacement_qty+camera_replacement_qty+sim_replacement_qty+micro_sd_qty),
         service_parts_confirmed
  into v_no,v_test,v_expected,v_parts_total,v_parts_confirmed
  from public.prep_tickets
  where id=p_prep_id and status='released';

  if not found then raise exception 'Service handoff not found or no longer waiting for Service'; end if;
  if coalesce(v_parts_total,0)>0 and not coalesce(v_parts_confirmed,false) then
    raise exception 'Verify the listed parts from IT before accepting this equipment.';
  end if;
  if jsonb_typeof(p_verifications)<>'array' then raise exception 'Equipment checkout verifications are required'; end if;

  v_actor_id:=auth.uid();
  v_name:=public.actor_display_name();

  if coalesce(v_test,false) and v_role='owner'::public.app_role then
    select a.assignee_user_id,coalesce(a.assignee_name,p.full_name,p.username,'Test Service')
      into v_actor_id,v_name
    from public.job_assignments a
    left join public.profiles p on p.user_id=a.assignee_user_id
    where trim(a.ticket_no)=trim(v_no)
      and a.assigned_role='service'
      and a.created_from='owner_test_center'
      and a.assignee_user_id is not null
    order by a.assigned_at desc
    limit 1;

    if v_actor_id is null then
      v_actor_id:=auth.uid();
      v_name:=public.actor_display_name();
    end if;
  end if;

  select count(*) into v_items from public.prep_items where prep_ticket_id=p_prep_id;

  for v_item in
    select * from public.prep_items where prep_ticket_id=p_prep_id order by item_order
  loop
    select value into v_verify
    from jsonb_array_elements(p_verifications)
    where value->>'item_id'=v_item.id::text
    limit 1;

    if v_verify is null then raise exception 'Missing equipment checkout verification for item %',v_item.item_order; end if;

    v_tag:=trim(v_verify->>'unit_tag');
    if v_tag is distinct from v_item.unit_tag then
      raise exception 'Unit tag does not match IT-prepared item %',v_item.item_order;
    end if;

    v_required:=coalesce(v_item.required_battery_count,0);
    if v_required>0 then
      v_actual:=coalesce((v_verify->>'battery_count')::int,-1);
      if v_actual<>v_item.battery_count then
        raise exception 'Battery count does not match IT-prepared count for item %',v_item.item_order;
      end if;
      if v_actual<v_required then
        raise exception 'Battery count is below the required count for item %',v_item.item_order;
      end if;
      if coalesce((v_verify->>'battery_verified')::boolean,false) is not true then
        raise exception 'Battery verification is required for item %',v_item.item_order;
      end if;
    else
      v_actual:=null;
    end if;

    if coalesce((v_verify->>'unit_confirmed')::boolean,false) is not true then
      raise exception 'Exact item confirmation is required for item %',v_item.item_order;
    end if;

    update public.prep_items
    set service_battery_count=v_actual,
        service_unit_confirmed=true,
        service_verified_by=v_actor_id,
        service_verified_at=now()
    where id=v_item.id;
  end loop;

  select count(*) into v_it_photos
  from public.handoff_evidence
  where prep_ticket_id=p_prep_id and stage='it' and kind='photo';

  if v_expected is not null then
    if v_it_photos<>v_items then raise exception 'IT photo count does not match the % prepared items',v_items; end if;
  elsif v_it_photos<1 then
    raise exception 'IT handoff photo proof is required before Service can accept the equipment';
  end if;

  select max(created_at) into v_signed_at
  from public.handoff_evidence
  where prep_ticket_id=p_prep_id and stage='service' and kind='signature';

  if v_signed_at is null then
    raise exception 'Service signature is required before marking equipment deployed to field';
  end if;

  update public.prep_tickets
  set status='closed',closed_by=v_actor_id,closed_by_name=v_name,closed_at=now()
  where id=p_prep_id;

  update public.job_assignments
  set prep_ticket_id=p_prep_id,
      status='completed',
      completed_at=now(),
      updated_at=now()
  where assigned_role='service'
    and ticket_no=v_no
    and assignee_user_id=v_actor_id
    and status in ('assigned','started');

  insert into public.reports(kind,actor_id,actor_name,ticket_no,text,is_test)
  values(
    case when v_test then 'TEST EQUIPMENT DEPLOYED TO FIELD' else 'EQUIPMENT DEPLOYED TO FIELD' end,
    v_actor_id,
    v_name,
    v_no,
    'Service Tech '||v_name||' verified the exact IT-prepared equipment'||
      case when coalesce(v_parts_total,0)>0 then ' and all listed parts' else '' end||
      ', reviewed the IT handoff photo/signature evidence, signed the Service receipt, and equipment was marked deployed to field.',
    coalesce(v_test,false)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.configure_it_prep_item(p_item_id uuid, p_equipment_type text, p_purpose text, p_required_battery_count integer DEFAULT NULL::integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_status public.prep_status;
  v_ticket text;
  v_type text;
  v_purpose public.prep_purpose;
  v_required int;
  v_old record;
begin
  perform public.require_role(array['it'::public.app_role,'owner'::public.app_role]);

  select i.*,t.status,t.ticket_no into v_old
  from public.prep_items i
  join public.prep_tickets t on t.id=i.prep_ticket_id
  where i.id=p_item_id
  for update of i,t;
  if not found then raise exception 'Prep item not found'; end if;

  v_status:=v_old.status;
  v_ticket:=v_old.ticket_no;
  if v_status<>'draft'::public.prep_status then raise exception 'Only draft IT equipment can be configured'; end if;

  v_type:=trim(coalesce(p_equipment_type,''));
  if v_type not in ('Sniper','Ranger','Helios','Solar Spotter','Spotter','Recon 2','110V Stand','Solar Stand','Pole') then
    raise exception 'Invalid equipment type';
  end if;
  if p_purpose not in ('BACKUP','SWAP','DELIVERY') then raise exception 'Invalid purpose'; end if;
  v_purpose:=p_purpose::public.prep_purpose;
  if v_type='110V Stand' and v_purpose<>'SWAP'::public.prep_purpose then raise exception '110V Stand is available for SWAP only'; end if;
  if v_type='Solar Stand' and v_purpose not in ('SWAP'::public.prep_purpose,'DELIVERY'::public.prep_purpose) then raise exception 'Solar Stand is available for SWAP or DELIVERY only'; end if;

  v_required:=case v_type
    when 'Sniper' then 2
    when 'Ranger' then 1
    when 'Solar Spotter' then 0
    when 'Helios' then 1
    when 'Recon 2' then greatest(1,coalesce(p_required_battery_count,1))
    when 'Solar Stand' then 0
    else 0 end;

  update public.prep_items
  set equipment_type=v_type,purpose=v_purpose,required_battery_count=v_required,
      unit_tag=null,battery_count=null,power_ok=null,functions_ok=null,safe_ok=null,
      verified_by=null,verified_at=null,
      service_battery_count=null,service_unit_confirmed=null,service_verified_by=null,service_verified_at=null,
      delivery_sim_ok=false,delivery_camera_app_ok=false,delivery_customer_email_app_ok=false,
      delivery_batteries_charged_ok=false,delivery_monitoring_ok=false,delivery_ticket_count_ok=false,
      delivery_sd_formatted_ok=false,delivery_recording_ok=false,
      solar_mppt_updated_ok=false,solar_mppt_tested_ok=false,solar_pv_charging_ok=false,
      solar_panels_match_ok=false,ticket_item_match_ok=false
  where id=p_item_id;

  insert into public.reports(kind,actor_id,actor_name,ticket_no,text)
  values('IT UNIT CONFIGURED',auth.uid(),public.actor_display_name(),v_ticket,
    'IT configured item #'||v_old.item_order||' as '||v_type||' for '||v_purpose::text||'.');
end;
$function$

CREATE OR REPLACE FUNCTION public.confirm_it_unit_photo_tag(p_item_id uuid, p_matches boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_prep_id uuid;
  v_status public.prep_status;
  v_tag text;
  v_ai_status text;
begin
  perform public.require_role(array['it'::public.app_role,'owner'::public.app_role]);

  select i.prep_ticket_id,t.status,i.unit_tag,i.ai_tag_scan_status
  into v_prep_id,v_status,v_tag,v_ai_status
  from public.prep_items i
  join public.prep_tickets t on t.id=i.prep_ticket_id
  where i.id=p_item_id
  for update of i,t;

  if not found then raise exception 'Prep item not found'; end if;
  if v_status<>'draft'::public.prep_status then
    raise exception 'Photo tag verification can only be changed while IT prep is still pending';
  end if;

  if coalesce(p_matches,false) then
    if nullif(trim(v_tag),'') is null then
      raise exception 'Enter the exact unit tag before confirming the photo';
    end if;
    if not exists(
      select 1 from public.handoff_evidence
      where prep_ticket_id=v_prep_id
        and prep_item_id=p_item_id
        and stage='it'
        and kind='photo'
    ) then
      raise exception 'Save the unit photo before confirming the visible tag';
    end if;
    if v_ai_status='mismatch' then
      raise exception 'OnSite Vision read a different unit tag. Retake a clear tag photo before approving this unit.';
    end if;
  end if;

  update public.prep_items
  set photo_tag_match_ok=coalesce(p_matches,false)
  where id=p_item_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.confirm_service_parts(p_prep_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_name text;
