CREATE OR REPLACE FUNCTION public.create_it_prep_shell_v2(p_ticket_no text, p_site text, p_expected_unit_count integer, p_solar_panel_qty integer DEFAULT 0, p_battery_replacement_qty integer DEFAULT 0, p_camera_replacement_qty integer DEFAULT 0, p_sim_replacement_qty integer DEFAULT 0, p_micro_sd_qty integer DEFAULT 0)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
    declare
      v_prep uuid;
    begin
      perform public.require_role(array['it'::public.app_role,'owner'::public.app_role]);
      if nullif(trim(p_ticket_no),'') is null then raise exception 'Ticket number is required'; end if;
      if nullif(trim(p_site),'') is null then raise exception 'Ticket name / customer / site is required'; end if;
      if coalesce(p_expected_unit_count,0) < 1 then raise exception 'Total unit count must be at least 1'; end if;
      if least(
        coalesce(p_solar_panel_qty,0),
