    $function$

CREATE OR REPLACE FUNCTION public.create_it_prep_shell_v3(p_ticket_no text, p_site text, p_requested_unit_count integer, p_equipment_manifest jsonb DEFAULT '[]'::jsonb, p_solar_panel_qty integer DEFAULT 0, p_battery_replacement_qty integer DEFAULT 0, p_camera_replacement_qty integer DEFAULT 0, p_sim_replacement_qty integer DEFAULT 0, p_micro_sd_qty integer DEFAULT 0)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_prep uuid;
  v_item jsonb;
  v_device_count integer := 0;
  v_stand_count integer := 0;
  v_total_items integer := 0;
  v_parts_total integer := 0;
  v_manifest_text text := '';
begin
  perform public.require_role(array['it'::public.app_role,'owner'::public.app_role]);

  if nullif(trim(p_ticket_no),'') is null then
    raise exception 'MHelpDesk ticket number is required';
  end if;
  if nullif(trim(p_site),'') is null then
    raise exception 'Ticket name / customer / site is required';
  end if;
  if p_requested_unit_count is null or p_requested_unit_count < 0 then
    raise exception 'Enter the number of units / devices for this ticket';
  end if;
  if jsonb_typeof(coalesce(p_equipment_manifest,'[]'::jsonb)) <> 'array' then
    raise exception 'Equipment selection must be a list';
  end if;

  if least(
    coalesce(p_solar_panel_qty,0),
    coalesce(p_battery_replacement_qty,0),
    coalesce(p_camera_replacement_qty,0),
    coalesce(p_sim_replacement_qty,0),
    coalesce(p_micro_sd_qty,0)
  ) < 0 then
    raise exception 'Part quantities cannot be negative';
  end if;

  v_parts_total :=
    coalesce(p_solar_panel_qty,0) +
    coalesce(p_battery_replacement_qty,0) +
    coalesce(p_camera_replacement_qty,0) +
    coalesce(p_sim_replacement_qty,0) +
    coalesce(p_micro_sd_qty,0);

  for v_item in
    select value from jsonb_array_elements(coalesce(p_equipment_manifest,'[]'::jsonb))
  loop
    if coalesce(v_item->>'category','') not in ('device','stand','other') then
      raise exception 'Invalid equipment category';
    end if;
    if nullif(trim(coalesce(v_item->>'label','')),'') is null then
      raise exception 'Equipment item label is required';
    end if;
    if coalesce((v_item->>'qty')::integer,0) < 1 then
      raise exception 'Equipment quantity must be at least 1';
    end if;

    if v_item->>'category'='device' then
      v_device_count := v_device_count + (v_item->>'qty')::integer;
    elsif v_item->>'category'='stand' then
      v_stand_count := v_stand_count + (v_item->>'qty')::integer;
    end if;

    v_manifest_text := v_manifest_text ||
      case when v_manifest_text='' then '' else ', ' end ||
      (v_item->>'qty') || ' x ' || (v_item->>'label');
  end loop;

  if v_device_count <> p_requested_unit_count then
    raise exception 'The Unit / Device area totals %, but Total Units for This Ticket is %. Make them match.',
      v_device_count, p_requested_unit_count;
  end if;

  v_total_items := v_device_count + v_stand_count;

  if v_total_items < 1 and v_parts_total < 1 then
    raise exception 'Choose at least one unit/device, stand, or loose part to hand off';
  end if;

  insert into public.prep_tickets(
    ticket_no,site,created_by,requested_unit_count,expected_unit_count,equipment_manifest,
    solar_panel_qty,battery_replacement_qty,camera_replacement_qty,
    sim_replacement_qty,micro_sd_qty
  )
  values(
    trim(p_ticket_no),trim(p_site),auth.uid(),p_requested_unit_count,
    case when v_total_items > 0 then v_total_items else null end,
    coalesce(p_equipment_manifest,'[]'::jsonb),
    coalesce(p_solar_panel_qty,0),coalesce(p_battery_replacement_qty,0),
    coalesce(p_camera_replacement_qty,0),coalesce(p_sim_replacement_qty,0),
    coalesce(p_micro_sd_qty,0)
  )
  returning id into v_prep;

  insert into public.reports(kind,actor_id,actor_name,ticket_no,text)
  values(
    case when v_total_items=0 then 'IT PARTS HANDOFF STARTED' else 'IT EQUIPMENT PREP STARTED' end,
    auth.uid(),
    public.actor_display_name(),
    trim(p_ticket_no),
    case when v_total_items=0 then 'IT started a parts-only handoff. ' else 'IT started equipment prep. ' end ||
    'Units / devices: '||p_requested_unit_count||
    '. Stands: '||v_stand_count||
    '. Equipment: '||coalesce(nullif(v_manifest_text,''),'None selected')||
    '. Ticket parts: solar panels '||coalesce(p_solar_panel_qty,0)||
    ', replacement batteries '||coalesce(p_battery_replacement_qty,0)||
    ', replacement cameras '||coalesce(p_camera_replacement_qty,0)||
    ', replacement SIM cards '||coalesce(p_sim_replacement_qty,0)||
    ', SD / micro SD cards '||coalesce(p_micro_sd_qty,0)||'.'
  );

  return v_prep;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_it_prep_shell_v4(p_ticket_no text, p_site text, p_requested_unit_count integer, p_equipment_manifest jsonb DEFAULT '[]'::jsonb, p_solar_panel_qty integer DEFAULT 0, p_battery_replacement_qty integer DEFAULT 0, p_camera_replacement_qty integer DEFAULT 0, p_sim_replacement_qty integer DEFAULT 0, p_micro_sd_qty integer DEFAULT 0, p_work_type text DEFAULT 'service'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_id uuid; v_work_type text:=lower(trim(coalesce(p_work_type,'service')));
begin
 perform public.require_role(array['it'::public.app_role,'owner'::public.app_role]);
 if v_work_type not in ('delivery','swap','pickup','service') then raise exception 'Job type must be Delivery, Swap, Pickup, or Service.'; end if;
 v_id:=public.create_it_prep_shell_v3(p_ticket_no,p_site,p_requested_unit_count,p_equipment_manifest,p_solar_panel_qty,p_battery_replacement_qty,p_camera_replacement_qty,p_sim_replacement_qty,p_micro_sd_qty);
 update public.prep_tickets set work_type=v_work_type where id=v_id;
 return v_id;
end;$function$

CREATE OR REPLACE FUNCTION public.delete_it_prep(p_prep_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_status public.prep_status;
  v_no text;
begin
  perform public.require_role(array['it'::public.app_role,'owner'::public.app_role]);
  select status,ticket_no into v_status,v_no from public.prep_tickets where id=p_prep_id for update;
  if not found then raise exception 'Equipment prep not found'; end if;
  if v_status='closed'::public.prep_status then raise exception 'Completed Service verification is locked. Owner can use Reset All Workflow Data if a full reset is needed.'; end if;
  delete from public.prep_tickets where id=p_prep_id;
  insert into public.reports(kind,actor_id,actor_name,ticket_no,text)
  values('IT EQUIPMENT PREP REMOVED',auth.uid(),public.actor_display_name(),v_no,'IT removed an active equipment prep that was entered in error.');
end;
$function$

CREATE OR REPLACE FUNCTION public.delete_it_prep_with_reason(p_prep_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_status public.prep_status;
  v_no text;
  v_test boolean;
  v_reason text := nullif(trim(p_reason),'');
begin
  perform public.require_role(array['it'::public.app_role,'owner'::public.app_role]);
  if v_reason is null then raise exception 'A short reason is required'; end if;

  select status,ticket_no,is_test
  into v_status,v_no,v_test
  from public.prep_tickets
  where id=p_prep_id
  for update;

  if not found then raise exception 'Equipment prep not found'; end if;
  if v_status='closed'::public.prep_status then
    raise exception 'Completed Service verification is locked. Owner can clear the workspace if needed.';
  end if;

  if coalesce(v_test,false) then
    delete from public.job_assignments
    where trim(ticket_no)=trim(v_no)
      and created_from='owner_test_center';
  end if;

  delete from public.prep_tickets where id=p_prep_id;

  insert into public.reports(kind,actor_id,actor_name,ticket_no,text,reason,is_test)
  values(
    'IT EQUIPMENT PREP DELETED',
    auth.uid(),
    public.actor_display_name(),
    v_no,
    'IT deleted an active equipment prep.',
    v_reason,
    coalesce(v_test,false)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.finalize_service_solar_progress_v1(p_prep_id uuid)
 RETURNS service_solar_checks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_role public.app_role;
  v_prep public.prep_tickets%rowtype;
  v_row public.service_solar_checks%rowtype;
  v_spotters int:=0;
  v_rangers int:=0;
  v_helios int:=0;
  v_expected_panels int:=0;
  v_owner_panels int:=0;
  v_battery_count int:=0;
  v_description text:='';
begin
  v_role:=public.current_app_role();
  if v_role not in ('service'::public.app_role,'owner'::public.app_role) then
    raise exception 'Service or Owner access required';
  end if;

  select * into v_prep
  from public.prep_tickets
  where id=p_prep_id and status='released';
  if not found then raise exception 'Equipment must be waiting for Service'; end if;

  select * into v_row
  from public.service_solar_checks
  where prep_ticket_id=p_prep_id
  for update;
  if not found then raise exception 'Start the Service pre-trip first'; end if;

  select
    count(*) filter(where equipment_type='Solar Spotter' and purpose='DELIVERY'::public.prep_purpose),
    count(*) filter(where equipment_type='Ranger' and purpose='DELIVERY'::public.prep_purpose),
    count(*) filter(where equipment_type='Helios' and purpose in ('DELIVERY'::public.prep_purpose,'SWAP'::public.prep_purpose,'BACKUP'::public.prep_purpose))
  into v_spotters,v_rangers,v_helios
  from public.prep_items
  where prep_ticket_id=p_prep_id;

  select coalesce(max(a.solar_panel_qty),0)
  into v_owner_panels
  from public.job_assignments a
  where a.assigned_role='service'
    and (a.prep_ticket_id=p_prep_id or trim(a.ticket_no)=trim(v_prep.ticket_no));

  v_expected_panels:=greatest(v_rangers,v_owner_panels,coalesce(v_prep.solar_panel_qty,0));

  if v_spotters>0 then
    if nullif(trim(coalesce(v_row.stand_tag,'')),'') is null or not v_row.stand_verified then
      raise exception 'Verify the exact Solar Stand tag before continuing';
    end if;
    if v_row.battery_configuration='agm_4x_12v_110ah' then
      v_battery_count:=v_battery_count+(v_spotters*4);
      v_description:=v_spotters||' Solar Stand(s): 4 x AGM 12V 110Ah each';
    elsif v_row.battery_configuration='single_12v_350ah' then
      v_battery_count:=v_battery_count+v_spotters;
      v_description:=v_spotters||' Solar Stand(s): 1 x 12V 350Ah each';
    else
      raise exception 'Choose the Solar Spotter battery setup';
    end if;
  end if;

  if not v_row.mppt_updated_ok then raise exception 'Verify the MPPT firmware / configuration'; end if;
  if not v_row.mppt_tested_ok then raise exception 'Verify the MPPT is powered and working'; end if;

  if v_expected_panels>0 then
    if v_row.solar_panel_count<>v_expected_panels or not v_row.solar_panels_verified then
      raise exception 'Verify the required loose solar panel count';
    end if;
  end if;

  if not v_row.batteries_charged_ok then raise exception 'Verify the required battery / battery-box setup'; end if;
  if not v_row.solar_charging_ok then raise exception 'Verify active charging through MPPT / PV'; end if;

  if v_rangers>0 then
    v_battery_count:=v_battery_count+v_rangers;
    v_description:=trim(both ' · ' from v_description||' · '||v_rangers||' x LiTime 12V 110Ah');
  end if;

  if v_helios>0 then
    if not v_row.helios_yard_pv_connected_ok then raise exception 'Connect the Helios unit to the yard tower solar panel'; end if;
    if not v_row.helios_yard_switch_pv_ok then raise exception 'Flip the internal Helios switch to PV'; end if;
    if not v_row.helios_yard_victron_bluetooth_ok then raise exception 'Connect to the Helios MPPT in the Victron Bluetooth app'; end if;
    if not v_row.helios_yard_updates_status_ok then raise exception 'Verify the MPPT is current and healthy in Victron'; end if;
    if not coalesce(v_row.helios_battery_box_charging_ok,false) then raise exception 'Verify the internal Helios battery box is present and charged'; end if;
    if not v_row.helios_yard_solar_charging_ok then raise exception 'Verify solar charging from the yard tower'; end if;
    if not v_row.helios_yard_ptz_wrapped_ok then raise exception 'Remove the PTZ and bubble wrap it for transport'; end if;

    v_battery_count:=v_battery_count+v_helios;
    v_description:=trim(both ' · ' from v_description||' · '||v_helios||' Helios battery box(es)');
    if v_spotters=0 and v_rangers=0 then
      update public.service_solar_checks
      set battery_configuration='helios_battery_box'
      where prep_ticket_id=p_prep_id;
    end if;
  elsif v_spotters=0 and v_rangers>0 then
    update public.service_solar_checks
    set battery_configuration='litime_1x_12v_110ah'
    where prep_ticket_id=p_prep_id;
  end if;

  if v_description='' then v_description:='Battery system used for charging verification'; end if;

  update public.service_solar_checks
  set battery_count=v_battery_count,
      battery_description=v_description,
      completed_at=now(),
      updated_at=now()
  where prep_ticket_id=p_prep_id
  returning * into v_row;

  return v_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_unit_return_conflict()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_key text;
  v_existing public.unit_registry%rowtype;
  v_unused_swap boolean:=false;
begin
  v_key := public.normalize_unit_key(new.unit_tag);

  -- Owner-approved exception: a 110V Stand can return directly to Shop from Service,
  -- including when the stand has no physical tag.
  if new.equipment_type='110V Stand' and new.status='completed' then
    return new;
  end if;

  if v_key='' then
    raise exception 'Unit tag is required';
  end if;

  if tg_op='INSERT' then
    if new.prep_item_id is not null then
      select exists(
        select 1
        from public.prep_items i
        where i.id=new.prep_item_id
          and i.purpose='SWAP'::public.prep_purpose
          and i.swap_outcome='returned_unused'
          and public.normalize_unit_key(i.unit_tag)=v_key
      ) into v_unused_swap;
    end if;

    select * into v_existing
    from public.unit_registry
    where unit_key=v_key
    for update;

    -- A prepared SWAP replacement that Service explicitly marked
    -- NO — DID NOT USE IT is allowed to reverse from ready-for-Service
    -- into IT Intake. This exception is tied to the exact prep item/tag.
    if found
       and v_existing.lifecycle_status<>'deployed'
       and not (
         v_unused_swap
         and v_existing.lifecycle_status in ('ready_for_service','assigned_to_tech','it_prep')
       ) then
      raise exception 'Unit % cannot be returned because its current status is %',
        new.unit_tag,
        replace(upper(v_existing.lifecycle_status),'_',' ');
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.it_add_service_truck_stock_v1(p_service_tech_id uuid, p_item_type text, p_qty_added integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor public.profiles%rowtype;
  v_target public.profiles%rowtype;
  v_actor_name text;
  v_target_name text;
  v_stock public.service_truck_stock%rowtype;
  v_before integer;
  v_after integer;
  v_required integer;
  v_req public.service_truck_restock_requests%rowtype;
begin
  perform public.require_role(array['it'::public.app_role,'owner'::public.app_role]);
  if coalesce(p_qty_added,0)<=0 then raise exception 'Quantity added must be greater than zero.'; end if;
  if p_item_type not in ('Recon Battery','AGM 12V 110Ah','LiTime 12V 100Ah') then
    raise exception 'Invalid permanent truck stock type.';
  end if;

  select * into v_actor from public.profiles where user_id=auth.uid() and active=true;
  v_actor_name:=coalesce(v_actor.full_name,v_actor.username,case when v_actor.role::text='owner' then 'Owner/Admin' else 'IT Technician' end);

  select * into v_target
  from public.profiles
  where user_id=p_service_tech_id and active=true and archived_at is null and role::text='service';
  if not found then raise exception 'Active Service Tech required.'; end if;
  v_target_name:=coalesce(v_target.full_name,v_target.username,'Service Tech');

  perform public.ensure_service_truck_baseline_v1(p_service_tech_id);

  select * into v_stock
  from public.service_truck_stock
  where service_tech_id=p_service_tech_id
  for update;

  if p_item_type='Recon Battery' then
    v_before:=v_stock.recon_battery_qty; v_required:=25; v_after:=v_before+p_qty_added;
    update public.service_truck_stock
    set recon_battery_qty=v_after,updated_by=auth.uid(),updated_by_name=v_actor_name,updated_at=now()
    where service_tech_id=p_service_tech_id;
  elsif p_item_type='AGM 12V 110Ah' then
    v_before:=v_stock.agm_12v_110ah_qty; v_required:=4; v_after:=v_before+p_qty_added;
    update public.service_truck_stock
    set agm_12v_110ah_qty=v_after,updated_by=auth.uid(),updated_by_name=v_actor_name,updated_at=now()
    where service_tech_id=p_service_tech_id;
  else
    v_before:=v_stock.litime_12v_100ah_qty; v_required:=2; v_after:=v_before+p_qty_added;
    update public.service_truck_stock
    set litime_12v_100ah_qty=v_after,updated_by=auth.uid(),updated_by_name=v_actor_name,updated_at=now()
    where service_tech_id=p_service_tech_id;
  end if;

  insert into public.service_truck_stock_history(
    service_tech_id,item_type,qty_before,qty_added,qty_after,actor_id,actor_name,note
  ) values(
    p_service_tech_id,p_item_type,v_before,p_qty_added,v_after,auth.uid(),v_actor_name,
    'IT loaded permanent truck stock.'
  );

  select * into v_req
  from public.service_truck_restock_requests
  where service_tech_id=p_service_tech_id
    and item_kind='battery'
    and item_type=p_item_type
    and status not in ('issued','cancelled')
  order by requested_at desc
  limit 1
  for update;

  if found then
    if v_after>=v_required then
      update public.service_truck_restock_requests
      set status='issued',
          qty_issued=coalesce(qty_issued,0)+p_qty_added,
          prepared_by=auth.uid(),
          prepared_by_name=v_actor_name,
          prepared_at=coalesce(prepared_at,now()),
          issued_at=now(),
          updated_at=now()
      where id=v_req.id;
    else
      update public.service_truck_restock_requests
      set qty_needed=v_required-v_after,
          qty_issued=coalesce(qty_issued,0)+p_qty_added,
          prepared_by=auth.uid(),
          prepared_by_name=v_actor_name,
          updated_at=now()
      where id=v_req.id;
    end if;
  end if;

  update public.service_truck_inventory_checks
  set ready=false,
      missing_items=jsonb_build_array(jsonb_build_object(
        'kind','verification',
        'item_type',p_item_type,
        'message','IT changed permanent truck stock. Service must physically recount the truck before leaving.'
      )),
      updated_at=now()
  where service_tech_id=p_service_tech_id
    and check_date=timezone('America/Chicago',now())::date;

  insert into public.reports(kind,actor_id,actor_name,text)
  values(
    'IT SERVICE TRUCK STOCK LOADED',auth.uid(),v_actor_name,
    p_qty_added||' × '||p_item_type||' added to '||v_target_name||'''s permanent Service truck inventory. Count changed from '||v_before||' to '||v_after||'. Service recount is required.'
  );

  return public.service_departure_readiness_v1(p_service_tech_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.it_adjust_service_truck_inventory_v3(p_service_tech_id uuid, p_kind text, p_slot text, p_value text, p_checks jsonb, p_verified boolean, p_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor public.profiles%rowtype;
  v_target public.profiles%rowtype;
  v_actor_name text;
  v_target_name text;
  v_old text;
  v_new text:=nullif(btrim(coalesce(p_value,'')),'');
  v_key text;
  v_qty integer;
  v_old_qty integer;
  v_required boolean;
begin
  perform public.require_role(array['it'::public.app_role,'owner'::public.app_role]);

  select * into v_actor
  from public.profiles
  where user_id=auth.uid() and active=true;
  if not found then raise exception 'Active IT or Owner account required.'; end if;

  select * into v_target
  from public.profiles
  where user_id=p_service_tech_id
    and active=true
    and archived_at is null
    and role::text='service';
  if not found then raise exception 'Active Service Tech required.'; end if;

  v_actor_name:=coalesce(v_actor.full_name,v_actor.username,case when v_actor.role::text='owner' then 'Owner/Admin' else 'IT Technician' end);
  v_target_name:=coalesce(v_target.full_name,v_target.username,'Service Tech');
  perform public.ensure_service_truck_baseline_v1(p_service_tech_id);

  if p_kind='unit' then
    if p_slot not in ('Sniper','Ranger','Spotter','Solar Spotter') then raise exception 'Invalid permanent truck unit type.'; end if;
    select unit_tag into v_old
    from public.service_truck_units
    where service_tech_id=p_service_tech_id and equipment_type=p_slot
    for update;

    if coalesce(v_old,'')=coalesce(v_new,'') then
      return jsonb_build_object('ok',true,'changed',false);
    end if;

    if v_new is not null then
      if jsonb_typeof(coalesce(p_checks,'{}'::jsonb))<>'object'
         or not (p_checks ?& array['identity_ok','power_ok','functions_ok','programmed_online_ok','sd_storage_ok','sim_monitoring_ok','clean_safe_ok'])
         or exists(
           select 1 from jsonb_each(p_checks)
           where key=any(array['identity_ok','power_ok','functions_ok','programmed_online_ok','sd_storage_ok','sim_monitoring_ok','clean_safe_ok'])
             and value<>'true'::jsonb
         )
      then raise exception 'Complete every IT readiness check before assigning or correcting a truck unit.'; end if;

      if exists(
        select 1 from public.service_truck_units u
        where u.service_tech_id<>p_service_tech_id
          and u.status='assigned'
          and lower(regexp_replace(coalesce(u.unit_tag,''),'[^a-zA-Z0-9]','','g'))
              = lower(regexp_replace(v_new,'[^a-zA-Z0-9]','','g'))
      ) then raise exception 'That unit is already assigned to another Service truck.'; end if;

      select equipment_key into v_key
      from public.equipment_master
      where lower(regexp_replace(coalesce(unit_tag,''),'[^a-zA-Z0-9]','','g'))
            = lower(regexp_replace(v_new,'[^a-zA-Z0-9]','','g'))
        and lower(coalesce(workflow_type,canonical_family))=lower(p_slot)
      limit 1;
      if v_key is null then raise exception 'Unit % is not a known % in the 2026 Unit Tracker.',v_new,p_slot; end if;
    end if;

    if nullif(btrim(coalesce(v_old,'')),'') is not null and lower(coalesce(v_old,''))<>lower(coalesce(v_new,'')) then
      update public.unit_registry
      set lifecycle_status='shop',
          current_holder_id=null,
          current_holder_name='Shop',
          last_event='Removed from permanent Service truck inventory by '||v_actor_name,
          current_site=null,
          ticket_no=null,
          updated_at=now()
      where lower(regexp_replace(coalesce(unit_tag,''),'[^a-zA-Z0-9]','','g'))
            = lower(regexp_replace(v_old,'[^a-zA-Z0-9]','','g'));
    end if;

    update public.service_truck_units
    set unit_tag=v_new,
        status=case when v_new is null then 'unassigned' else 'assigned' end,
        last_used_ticket_no=null,
        last_used_at=null,
        old_unit_tag=v_old,
        assigned_by=auth.uid(),
        assigned_by_name=v_actor_name,
        assigned_at=now(),
        updated_at=now()
    where service_tech_id=p_service_tech_id and equipment_type=p_slot;

    insert into public.service_truck_unit_history(
      service_tech_id,equipment_type,unit_tag,event,ticket_no,old_unit_tag,actor_id,actor_name
    ) values(
      p_service_tech_id,p_slot,coalesce(v_new,v_old),
      case when v_new is null then 'IT REMOVED FROM TRUCK' else 'IT CORRECTED TRUCK INVENTORY' end,
      null,v_old,auth.uid(),v_actor_name
    );

    if v_new is not null then
      insert into public.unit_registry(
        unit_key,unit_tag,equipment_type,lifecycle_status,current_holder_id,current_holder_name,last_event,current_site,updated_at
      ) values(
        v_key,v_new,p_slot,'assigned_to_tech',p_service_tech_id,v_target_name,
        'IT assigned / corrected permanent Service truck inventory',null,now()
      )
      on conflict(unit_key) do update
      set lifecycle_status='assigned_to_tech',
          current_holder_id=p_service_tech_id,
          current_holder_name=v_target_name,
          last_event=excluded.last_event,
          current_site=null,
          ticket_no=null,
          updated_at=now();
    end if;

  elsif p_kind='sim' then
    if p_slot not in ('1','2','3') then raise exception 'SIM slot must be 1, 2, or 3.'; end if;

    select sim_number into v_old
    from public.service_truck_sims
    where service_tech_id=p_service_tech_id and slot_no=p_slot::integer
    for update;

    if coalesce(v_old,'')=coalesce(v_new,'') then
      return jsonb_build_object('ok',true,'changed',false);
    end if;

    if v_new is not null and coalesce(p_verified,false) is not true then
      raise exception 'Physically verify the exact SIM number before saving it.';
    end if;

    if v_new is not null and exists(
      select 1 from public.service_truck_sims s
      where s.status='assigned'
        and lower(btrim(coalesce(s.sim_number,'')))=lower(v_new)
        and not (s.service_tech_id=p_service_tech_id and s.slot_no=p_slot::integer)
    ) then raise exception 'That SIM number is already assigned to another Service truck slot.'; end if;

    update public.service_truck_sims
    set sim_number=v_new,
        status=case when v_new is null then 'unassigned' else 'assigned' end,
        last_used_ticket_no=null,
        last_used_at=null,
        assigned_by=auth.uid(),
        assigned_by_name=v_actor_name,
        assigned_at=now(),
        updated_at=now()
    where service_tech_id=p_service_tech_id and slot_no=p_slot::integer;

    insert into public.service_truck_sim_history(
      service_tech_id,slot_no,sim_number,event,ticket_no,actor_id,actor_name
    ) values(
      p_service_tech_id,p_slot::integer,coalesce(v_new,v_old),
      case when v_new is null then 'IT REMOVED FROM TRUCK' else 'IT CORRECTED TRUCK INVENTORY' end,
      null,auth.uid(),v_actor_name
    );

  elsif p_kind='stock' then
    if p_slot not in ('Recon Battery','AGM 12V 110Ah','LiTime 12V 100Ah','12V 35Ah') then raise exception 'Invalid permanent truck stock type.'; end if;
    begin
      v_qty:=p_value::integer;
    exception when others then
      raise exception 'Enter a whole-number quantity.';
    end;
    if v_qty<0 then raise exception 'Quantity cannot be negative.'; end if;

    if p_slot='Recon Battery' then
      select recon_battery_qty into v_old_qty from public.service_truck_stock where service_tech_id=p_service_tech_id for update;
      update public.service_truck_stock set recon_battery_qty=v_qty,updated_by=auth.uid(),updated_by_name=v_actor_name,updated_at=now() where service_tech_id=p_service_tech_id;
    elsif p_slot='AGM 12V 110Ah' then
      select agm_12v_110ah_qty into v_old_qty from public.service_truck_stock where service_tech_id=p_service_tech_id for update;
      update public.service_truck_stock set agm_12v_110ah_qty=v_qty,updated_by=auth.uid(),updated_by_name=v_actor_name,updated_at=now() where service_tech_id=p_service_tech_id;
    elsif p_slot='LiTime 12V 100Ah' then
      select litime_12v_100ah_qty into v_old_qty from public.service_truck_stock where service_tech_id=p_service_tech_id for update;
      update public.service_truck_stock set litime_12v_100ah_qty=v_qty,updated_by=auth.uid(),updated_by_name=v_actor_name,updated_at=now() where service_tech_id=p_service_tech_id;
    else
      select battery_12v_35ah_qty into v_old_qty from public.service_truck_stock where service_tech_id=p_service_tech_id for update;
      update public.service_truck_stock set battery_12v_35ah_qty=v_qty,updated_by=auth.uid(),updated_by_name=v_actor_name,updated_at=now() where service_tech_id=p_service_tech_id;
    end if;

    if coalesce(v_old_qty,0)<>v_qty then
      insert into public.service_truck_stock_history(
        service_tech_id,item_type,qty_before,qty_added,qty_after,actor_id,actor_name,note
      ) values(
        p_service_tech_id,p_slot,coalesce(v_old_qty,0),v_qty-coalesce(v_old_qty,0),v_qty,auth.uid(),v_actor_name,
        coalesce(nullif(btrim(p_note),''),'IT set exact permanent truck stock count.')
      );
    end if;
  else
    raise exception 'Invalid inventory adjustment type.';
  end if;

  update public.service_truck_inventory_checks
  set ready=false,
      missing_items=jsonb_build_array(jsonb_build_object(
        'kind','verification',
        'item_type',p_slot,
        'message','IT changed permanent truck inventory. Service must physically verify the truck before leaving.'
      )),
      updated_at=now()
  where service_tech_id=p_service_tech_id
    and check_date=timezone('America/Chicago',now())::date;

  perform public.close_stale_service_truck_restock_requests_v1();
  perform public.refresh_service_truck_restock_requests_v1();

  insert into public.reports(kind,actor_id,actor_name,text)
  values(
    'IT SERVICE TRUCK INVENTORY ADJUSTED',
    auth.uid(),v_actor_name,
    v_target_name||' · '||p_kind||' · '||p_slot||' changed. Service re-verification required.'
      ||case when nullif(btrim(coalesce(p_note,'')),'') is not null then ' Note: '||btrim(p_note) else '' end
  );

  return public.service_departure_readiness_v1(p_service_tech_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.it_checkout_truck_spare_battery(p_spare_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_row public.truck_spare_batteries%rowtype;
  v_status public.prep_status;
  v_name text;
begin
  perform public.require_role(array['it'::public.app_role,'owner'::public.app_role]);

  select * into v_row
  from public.truck_spare_batteries
  where id=p_spare_id
  for update;
  if not found then raise exception 'Spare battery batch not found'; end if;

  select status into v_status
  from public.prep_tickets
  where id=v_row.prep_ticket_id
  for update;

  if v_status<>'draft'::public.prep_status or v_row.status<>'prepared' then
    raise exception 'Spare battery checkout must happen while IT is preparing the ticket';
  end if;
  if not coalesce(v_row.ready_ok,false) then
    raise exception 'Mark the spare battery batch physically present, charged, and READY before checkout';
  end if;

  if v_row.it_checked_out_at is not null then
    return;
  end if;

  v_name:=public.actor_display_name();

  update public.truck_spare_batteries
  set it_checked_out_at=now(),
      it_checked_out_by=auth.uid(),
      it_checked_out_by_name=v_name,
      updated_at=now()
  where id=p_spare_id;

  insert into public.reports(kind,actor_id,actor_name,ticket_no,text)
  values(
    'IT TRUCK SPARE BATTERY CHECKOUT',
    auth.uid(),v_name,v_row.ticket_no,
    'IT Tech '||v_name||' checked out '||v_row.qty_prepared||' × '||v_row.battery_type||
    ' as truck spare batteries for '||v_row.equipment_type||'.'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.it_checkout_truck_spare_unit(p_item_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_item public.prep_items%rowtype;
  v_prep public.prep_tickets%rowtype;
  v_name text;
  v_photo_count integer;
  v_sig_count integer;
  v_key text;
  v_asset public.asset_inventory%rowtype;
begin
  perform public.require_role(array['it'::public.app_role,'owner'::public.app_role]);

  select i.* into v_item
  from public.prep_items i
  where i.id=p_item_id
  for update;
  if not found then raise exception 'Truck spare unit not found'; end if;
  if v_item.purpose<>'BACKUP'::public.prep_purpose then
    raise exception 'Only a BACKUP unit can be checked out as a truck spare';
  end if;

  select * into v_prep
  from public.prep_tickets
  where id=v_item.prep_ticket_id
  for update;
  if not found or v_prep.status<>'draft'::public.prep_status then
    raise exception 'Truck spare checkout must happen while IT is still preparing the ticket';
  end if;

  if v_item.verified_at is null then
    raise exception 'Finish all required IT checks before checking out this spare';
  end if;
  if not coalesce(v_item.photo_tag_match_ok,false) then
    raise exception 'Confirm the spare photo clearly shows the matching unit tag before checkout';
  end if;

  select count(*) filter(where kind='photo'),
         count(*) filter(where kind='signature')
  into v_photo_count,v_sig_count
  from public.handoff_evidence
  where prep_ticket_id=v_item.prep_ticket_id
    and prep_item_id=v_item.id
    and stage='it';

  if v_photo_count<>1 then
    raise exception 'This spare requires exactly one IT photo before checkout';
  end if;
  if v_sig_count<1 then
    raise exception 'This spare requires the IT signature before checkout';
  end if;

  if v_item.spare_it_checked_out_at is not null then
    return;
  end if;

  v_name:=public.actor_display_name();

  update public.prep_items
  set spare_it_checked_out_at=now(),
      spare_it_checked_out_by=auth.uid(),
      spare_it_checked_out_by_name=v_name
  where id=p_item_id;

  v_key:=public.normalize_unit_key(v_item.unit_tag);

  update public.unit_registry
  set lifecycle_status='assigned_to_tech',
      current_holder_id=auth.uid(),
      current_holder_name=v_name,
      ticket_no=v_prep.ticket_no,
      prep_ticket_id=v_prep.id,
      prep_item_id=v_item.id,
      last_event='Truck spare checked out by IT Tech '||v_name||' for MHelpDesk #'||v_prep.ticket_no,
      updated_at=now()
  where unit_key=v_key;

  select * into v_asset
  from public.asset_inventory
  where unit_key=v_key
  for update;

  if found then
    if v_asset.availability_status='assigned'
       and v_asset.assigned_to is distinct from auth.uid() then
      raise exception 'This spare is already assigned to another technician';
    end if;
    if v_asset.availability_status in ('maintenance','retired') then
      raise exception 'This spare is not available for truck checkout';
    end if;

    insert into public.asset_inventory_history(
      unit_key,unit_tag,action,from_status,to_status,
      from_user_id,from_user_name,to_user_id,to_user_name,
      actor_id,actor_name,notes
    ) values(
      v_asset.unit_key,v_asset.unit_tag,'it_truck_spare_checkout',
      v_asset.availability_status,'assigned',
      v_asset.assigned_to,v_asset.assigned_to_name,
      auth.uid(),v_name,
      auth.uid(),v_name,
      'IT checked out truck spare for MHelpDesk #'||v_prep.ticket_no
    );

    update public.asset_inventory
    set availability_status='assigned',
        assigned_to=auth.uid(),
        assigned_to_name=v_name,
        last_event='IT truck spare checkout for MHelpDesk #'||v_prep.ticket_no,
        updated_at=now()
    where unit_key=v_key;
  end if;

  insert into public.reports(kind,actor_id,actor_name,ticket_no,text)
  values(
    'IT TRUCK SPARE CHECKOUT',
    auth.uid(),v_name,v_prep.ticket_no,
    'IT Tech '||v_name||' checked out BACKUP '||v_item.equipment_type||' '||coalesce(v_item.unit_tag,'')||
    ' before the Service handoff.'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.it_confirm_swap_site_registration_v1(p_item_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_role public.app_role;
  v_item public.prep_items%rowtype;
  v_prep public.prep_tickets%rowtype;
  v_name text;
  v_key text;
  v_asset public.asset_inventory%rowtype;
begin
  v_role:=public.current_app_role();
  if v_role not in ('it'::public.app_role,'owner'::public.app_role) then
    raise exception 'IT or Owner access required';
  end if;

  select * into v_item
  from public.prep_items
  where id=p_item_id
  for update;

  if not found
     or v_item.purpose<>'SWAP'::public.prep_purpose
     or v_item.swap_outcome<>'installed' then
    raise exception 'Installed SWAP unit not found';
  end if;

  if v_item.swap_site_registration_status='completed' then
    return jsonb_build_object('item_id',v_item.id,'status','completed','already_recorded',true);
  end if;

  select * into v_prep
  from public.prep_tickets
  where id=v_item.prep_ticket_id;

  if not found then raise exception 'SWAP prep record not found'; end if;

  v_name:=public.actor_display_name();
  v_key:=public.normalize_unit_key(v_item.unit_tag);

  update public.prep_items
  set swap_site_registration_status='completed',
      swap_site_registered_by=auth.uid(),
      swap_site_registered_by_name=v_name,
      swap_site_registered_at=now(),
      swap_installed_site=coalesce(
        nullif(trim(swap_installed_site),''),
        nullif(trim(coalesce(v_prep.site,'')),'')
      )
  where id=v_item.id;

  update public.unit_registry
  set lifecycle_status='deployed',
      ticket_no=v_prep.ticket_no,
      prep_ticket_id=v_prep.id,
      prep_item_id=v_item.id,
      current_site=coalesce(
        nullif(trim(v_item.swap_installed_site),''),
        nullif(trim(coalesce(v_prep.site,'')),'')
      ),
      site_registered_at=now(),
      site_registered_by=auth.uid(),
      site_registered_by_name=v_name,
      last_event='IT registered SWAP unit to '||
        coalesce(
          nullif(trim(v_item.swap_installed_site),''),
          nullif(trim(coalesce(v_prep.site,'')),''),
          'customer site'
        )||
        ' on MHelpDesk #'||v_prep.ticket_no,
      updated_at=now()
  where unit_key=v_key;

  select * into v_asset
  from public.asset_inventory
  where unit_key=v_key
  for update;

  if found then
    insert into public.asset_inventory_history(
      unit_key,unit_tag,action,from_status,to_status,
      from_user_id,from_user_name,to_user_id,to_user_name,
      actor_id,actor_name,notes
    )
    values(
      v_asset.unit_key,v_asset.unit_tag,'swap_site_registered',
      v_asset.availability_status,'assigned',
      v_asset.assigned_to,v_asset.assigned_to_name,
      v_asset.assigned_to,v_asset.assigned_to_name,
      auth.uid(),v_name,
      'IT registered SWAP unit to '||
      coalesce(
        nullif(trim(v_item.swap_installed_site),''),
        nullif(trim(coalesce(v_prep.site,'')),''),
        'customer site'
      )||
      ' for MHelpDesk #'||v_prep.ticket_no
    );

    update public.asset_inventory
    set availability_status='assigned',
        last_event='IT site registration complete for '||
          coalesce(
            nullif(trim(v_item.swap_installed_site),''),
            nullif(trim(coalesce(v_prep.site,'')),''),
            'customer site'
          )||
          ' · MHelpDesk #'||v_prep.ticket_no,
        updated_at=now()
    where unit_key=v_key;
  end if;

  update public.app_notifications
  set read_at=coalesce(read_at,now())
  where kind='swap_site_registration'
    and trim(coalesce(ticket_no,''))=trim(v_prep.ticket_no)
    and public.normalize_unit_key(unit_tag)=v_key;

  insert into public.reports(kind,actor_id,actor_name,ticket_no,text)
  values(
    'SWAP SITE REGISTRATION COMPLETE',
    auth.uid(),v_name,v_prep.ticket_no,
    'IT registered replacement '||v_item.equipment_type||' '||v_item.unit_tag||
    ' to '||coalesce(
      nullif(trim(v_item.swap_installed_site),''),
      nullif(trim(coalesce(v_prep.site,'')),''),
      'the customer site'
    )||'.'
  );

  return jsonb_build_object(
    'item_id',v_item.id,
    'status','completed',
    'unit_tag',v_item.unit_tag,
    'site',coalesce(v_item.swap_installed_site,v_prep.site)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.it_load_service_truck_sim_v1(p_service_tech_id uuid, p_slot_no integer, p_sim_number text, p_number_verified boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor public.profiles%rowtype;
  v_target public.profiles%rowtype;
  v_actor_name text;
  v_target_name text;
  v_row public.service_truck_sims%rowtype;
  v_sim text:=btrim(coalesce(p_sim_number,''));
  v_req public.service_truck_restock_requests%rowtype;
  v_has_req boolean := false;
begin
  perform public.require_role(array['it'::public.app_role,'owner'::public.app_role]);
  if p_slot_no not between 1 and 3 then raise exception 'SIM slot must be 1, 2, or 3.'; end if;
  if v_sim='' then raise exception 'Enter the exact SIM number.'; end if;
  if coalesce(p_number_verified,false) is not true then raise exception 'Physically verify the exact SIM number first.'; end if;

  select * into v_actor from public.profiles where user_id=auth.uid() and active=true;
  v_actor_name:=coalesce(v_actor.full_name,v_actor.username,case when v_actor.role::text='owner' then 'Owner/Admin' else 'IT Technician' end);

  select * into v_target
  from public.profiles
  where user_id=p_service_tech_id and active=true and archived_at is null and role::text='service';
  if not found then raise exception 'Active Service Tech required.'; end if;
  v_target_name:=coalesce(v_target.full_name,v_target.username,'Service Tech');

  perform public.ensure_service_truck_baseline_v1(p_service_tech_id);

  select * into v_row
  from public.service_truck_sims
  where service_tech_id=p_service_tech_id and slot_no=p_slot_no
  for update;

  if v_row.status='assigned'
     and nullif(btrim(coalesce(v_row.sim_number,'')),'') is not null
     and lower(btrim(v_row.sim_number))<>lower(v_sim) then
    raise exception 'SIM slot % already has SIM % assigned. Service must mark that SIM used before IT can replace it.',
      p_slot_no,v_row.sim_number;
  end if;

  if exists(
    select 1 from public.service_truck_sims s
    where s.status='assigned'
      and lower(btrim(coalesce(s.sim_number,'')))=lower(v_sim)
      and not (s.service_tech_id=p_service_tech_id and s.slot_no=p_slot_no)
  ) then raise exception 'That SIM number is already assigned to another Service truck slot.'; end if;

  select * into v_req
  from public.service_truck_restock_requests
  where service_tech_id=p_service_tech_id
    and item_kind='sim'
    and sim_slot_no=p_slot_no
    and status not in ('issued','cancelled')
  order by requested_at desc
  limit 1
  for update;
  v_has_req:=found;

  update public.service_truck_sims
  set sim_number=v_sim,
      status='assigned',
      last_used_ticket_no=null,
      last_used_at=null,
      assigned_by=auth.uid(),
      assigned_by_name=v_actor_name,
      assigned_at=now(),
      updated_at=now()
  where service_tech_id=p_service_tech_id and slot_no=p_slot_no;

  insert into public.service_truck_sim_history(
    service_tech_id,slot_no,sim_number,event,ticket_no,actor_id,actor_name
  ) values(
    p_service_tech_id,p_slot_no,v_sim,'IT LOADED TO TRUCK',
    case when v_has_req then v_req.original_ticket_no else null end,
    auth.uid(),v_actor_name
  );

  if v_has_req then
    update public.service_truck_restock_requests
    set status='issued',
        replacement_sim_number=v_sim,
        prep_checks=jsonb_build_object('sim_number_verified',true),
        prepared_by=auth.uid(),
        prepared_by_name=v_actor_name,
        prepared_at=coalesce(prepared_at,now()),
        issued_at=now(),
        updated_at=now()
    where id=v_req.id;
  end if;

  update public.service_truck_inventory_checks
  set ready=false,
      missing_items=jsonb_build_array(jsonb_build_object(
        'kind','verification',
        'item_type','SIM Card',
        'slot_no',p_slot_no,
        'message','IT loaded / changed this SIM. Service must physically verify the exact SIM number before leaving.'
      )),
      updated_at=now()
  where service_tech_id=p_service_tech_id
    and check_date=timezone('America/Chicago',now())::date;

  insert into public.reports(kind,actor_id,actor_name,ticket_no,text)
  values(
    'IT SERVICE TRUCK SIM LOADED',auth.uid(),v_actor_name,
    case when v_has_req then v_req.original_ticket_no else null end,
    'SIM '||v_sim||' loaded to '||v_target_name||'''s permanent truck SIM slot '||p_slot_no||'. Service verification is required.'
  );

  return public.service_departure_readiness_v1(p_service_tech_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.it_load_service_truck_unit_v1(p_service_tech_id uuid, p_equipment_type text, p_unit_tag text, p_checks jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor public.profiles%rowtype;
  v_target public.profiles%rowtype;
  v_actor_name text;
  v_target_name text;
  v_row public.service_truck_units%rowtype;
  v_tag text := btrim(coalesce(p_unit_tag,''));
  v_key text;
  v_req public.service_truck_restock_requests%rowtype;
  v_has_req boolean := false;
begin
  perform public.require_role(array['it'::public.app_role,'owner'::public.app_role]);
  if p_equipment_type not in ('Sniper','Ranger','Spotter','Solar Spotter') then
    raise exception 'Invalid permanent truck unit type.';
  end if;
  if v_tag='' then raise exception 'Enter the exact unit tag.'; end if;

  select * into v_actor from public.profiles where user_id=auth.uid() and active=true;
  v_actor_name:=coalesce(v_actor.full_name,v_actor.username,case when v_actor.role::text='owner' then 'Owner/Admin' else 'IT Technician' end);

  select * into v_target
  from public.profiles
  where user_id=p_service_tech_id and active=true and archived_at is null and role::text='service';
  if not found then raise exception 'Active Service Tech required.'; end if;
  v_target_name:=coalesce(v_target.full_name,v_target.username,'Service Tech');

  perform public.ensure_service_truck_baseline_v1(p_service_tech_id);
  perform public.refresh_service_truck_restock_requests_v1();

  select * into v_row
  from public.service_truck_units
  where service_tech_id=p_service_tech_id and equipment_type=p_equipment_type
  for update;

  if v_row.status='assigned'
     and nullif(btrim(coalesce(v_row.unit_tag,'')),'') is not null
     and lower(regexp_replace(v_row.unit_tag,'[^a-zA-Z0-9]','','g'))
         <> lower(regexp_replace(v_tag,'[^a-zA-Z0-9]','','g')) then
    raise exception 'This truck already has % % assigned. Service must mark that unit used / returned before IT can replace it.',
      p_equipment_type,v_row.unit_tag;
  end if;

  select * into v_req
  from public.service_truck_restock_requests
  where service_tech_id=p_service_tech_id
    and item_kind='unit'
    and item_type=p_equipment_type
    and status not in ('issued','cancelled')
  order by requested_at desc
  limit 1
  for update;
  v_has_req:=found;

  if v_has_req and v_req.status='awaiting_return' then
    raise exception 'The old field unit must come back through Service Return / IT Intake before this truck unit can be replaced.';
  end if;

  select equipment_key into v_key
  from public.equipment_master
  where trim(unit_tag)=v_tag
    and lower(coalesce(workflow_type,canonical_family))=lower(p_equipment_type)
    and tracker_state='shop'
  limit 1;
  if v_key is null then
    raise exception 'Unit % is not a Shop Inventory % in the 2026 Unit Tracker.',v_tag,p_equipment_type;
  end if;

  if exists(
    select 1 from public.service_truck_units u
    where u.status='assigned'
      and u.service_tech_id<>p_service_tech_id
      and lower(regexp_replace(coalesce(u.unit_tag,''),'[^a-zA-Z0-9]','','g'))
          = lower(regexp_replace(v_tag,'[^a-zA-Z0-9]','','g'))
  ) then raise exception 'That unit is already assigned to another Service truck.'; end if;

  if jsonb_typeof(p_checks)<>'object'
     or not (p_checks ?& array['identity_ok','power_ok','functions_ok','programmed_online_ok','sd_storage_ok','sim_monitoring_ok','clean_safe_ok'])
     or exists(
       select 1 from jsonb_each(p_checks)
       where key=any(array['identity_ok','power_ok','functions_ok','programmed_online_ok','sd_storage_ok','sim_monitoring_ok','clean_safe_ok'])
         and value<>'true'::jsonb
     )
  then raise exception 'Complete every IT readiness check before loading this unit onto the Service truck.'; end if;

  update public.service_truck_units
  set unit_tag=v_tag,
      status='assigned',
      last_used_ticket_no=null,
      last_used_at=null,
      old_unit_tag=null,
      assigned_by=auth.uid(),
      assigned_by_name=v_actor_name,
      assigned_at=now(),
      updated_at=now()
  where service_tech_id=p_service_tech_id and equipment_type=p_equipment_type;

  insert into public.service_truck_unit_history(
    service_tech_id,equipment_type,unit_tag,event,ticket_no,old_unit_tag,actor_id,actor_name
  ) values(
    p_service_tech_id,p_equipment_type,v_tag,'IT LOADED TO TRUCK',
    case when v_has_req then v_req.original_ticket_no else null end,
    case when v_has_req then v_req.old_unit_tag else v_row.old_unit_tag end,
    auth.uid(),v_actor_name
  );

  insert into public.unit_registry(
    unit_key,unit_tag,equipment_type,lifecycle_status,current_holder_id,current_holder_name,last_event,current_site,updated_at
  ) values(
    v_key,v_tag,p_equipment_type,'assigned_to_tech',p_service_tech_id,v_target_name,
    'IT loaded to permanent Service Truck inventory',null,now()
  )
  on conflict(unit_key) do update
  set lifecycle_status='assigned_to_tech',
      current_holder_id=p_service_tech_id,
      current_holder_name=v_target_name,
      last_event=excluded.last_event,
      current_site=null,
      ticket_no=null,
      updated_at=now();

  if v_has_req then
    update public.service_truck_restock_requests
    set status='issued',
        replacement_unit_tag=v_tag,
        prep_checks=p_checks,
        prepared_by=auth.uid(),
        prepared_by_name=v_actor_name,
        prepared_at=coalesce(prepared_at,now()),
        issued_at=now(),
        updated_at=now()
    where id=v_req.id;
  end if;

  update public.service_truck_inventory_checks
  set ready=false,
      missing_items=jsonb_build_array(jsonb_build_object(
        'kind','verification',
        'item_type',p_equipment_type,
        'message','IT loaded / changed this permanent truck unit. Service must physically verify the exact unit before leaving.'
      )),
      updated_at=now()
  where service_tech_id=p_service_tech_id
    and check_date=timezone('America/Chicago',now())::date;

  insert into public.reports(kind,actor_id,actor_name,ticket_no,text)
  values(
    'IT SERVICE TRUCK UNIT LOADED',auth.uid(),v_actor_name,
    case when v_has_req then v_req.original_ticket_no else null end,
    p_equipment_type||' '||v_tag||' loaded to '||v_target_name||'''s permanent Service truck inventory. Service verification is required.'
  );

  return public.service_departure_readiness_v1(p_service_tech_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.it_mark_return_needs_replacement_v1(p_return_id uuid, p_damage_notes text, p_intake_photo_paths text[] DEFAULT '{}'::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_return public.unit_returns%rowtype;
  v_name text;
  v_key text;
  v_asset public.asset_inventory%rowtype;
  v_owner record;
  v_existing_hold boolean:=false;
begin
  perform public.require_role(array['it'::public.app_role,'owner'::public.app_role]);

  if nullif(btrim(coalesce(p_damage_notes,'')),'') is null then
    raise exception 'Describe the damage and what needs replacement before escalating to the Owner.';
  end if;
  if coalesce(cardinality(p_intake_photo_paths),0)<1 then
    raise exception 'Take an IT Intake photo showing the damaged unit before escalating it.';
  end if;

  select * into v_return
  from public.unit_returns
  where id=p_return_id
  for update;

  if not found then raise exception 'Return / intake record not found'; end if;
  if v_return.status not in ('waiting_it','needs_replacement') then
    raise exception 'This return is not in IT Intake and cannot be marked for replacement from its current status.';
  end if;

  v_existing_hold := v_return.status='needs_replacement';
  v_name:=public.actor_display_name();
  v_key:=public.normalize_unit_key(v_return.unit_tag);

  update public.unit_returns
  set status='needs_replacement',
      it_tech_id=coalesce(it_tech_id,auth.uid()),
      it_tech_name=coalesce(it_tech_name,v_name),
      it_received_at=coalesce(it_received_at,now()),
      damage_notes=btrim(p_damage_notes),
      intake_photo_paths=coalesce(p_intake_photo_paths,'{}'::text[]),
      mhelp_inventory_confirmed=false,
      mhelp_confirmed_at=null,
      completed_at=null,
      updated_at=now()
  where id=p_return_id;

  if v_key<>'' then
    select * into v_asset
    from public.asset_inventory
    where unit_key=v_key
    for update;

    if found then
      if not v_existing_hold then
        insert into public.asset_inventory_history(
          unit_key,unit_tag,action,from_status,to_status,
          from_user_id,from_user_name,actor_id,actor_name,notes
        ) values(
          v_asset.unit_key,v_asset.unit_tag,'damage_needs_replacement',
          v_asset.availability_status,'maintenance',
          v_asset.assigned_to,v_asset.assigned_to_name,
          auth.uid(),v_name,
          'IT confirmed damage on MHelpDesk #'||v_return.ticket_no||
          '. Equipment is held out of Shop Inventory and needs replacement/repair. '||btrim(p_damage_notes)
        );
      end if;

      update public.asset_inventory
      set availability_status='maintenance',
          assigned_to=null,
          assigned_to_name=null,
          last_event='Damage confirmed by IT — replacement/repair required — Owner notified',
          updated_at=now()
      where unit_key=v_key;
    end if;
  end if;

  if not v_existing_hold then
    for v_owner in
      select user_id from public.profiles where active=true and role='owner'
    loop
      perform public.enqueue_app_notification(
        v_owner.user_id,
        'owner_action',
        'Damaged equipment needs replacement',
        'IT Tech '||v_name||' confirmed damage on '||coalesce(v_return.equipment_type,'equipment')||
          case when nullif(btrim(coalesce(v_return.unit_tag,'')),'') is not null then ' Unit '||v_return.unit_tag else '' end||
          ' for MHelpDesk #'||v_return.ticket_no||
          '. This equipment is NOT available in Shop Inventory. '||btrim(p_damage_notes),
        null,
        v_return.ticket_no,
        v_return.unit_tag
      );
    end loop;

    insert into public.reports(kind,actor_id,actor_name,ticket_no,text)
    values(
      'DAMAGED EQUIPMENT NEEDS REPLACEMENT',
      auth.uid(),v_name,v_return.ticket_no,
      coalesce(v_return.equipment_type,'Equipment')||
        case when nullif(btrim(coalesce(v_return.unit_tag,'')),'') is not null then ' Unit '||v_return.unit_tag else '' end||
        ' was placed in Maintenance / Needs Replacement by IT. It was not returned to available Shop Inventory. '||
        btrim(p_damage_notes)
    );
  end if;

  return jsonb_build_object(
    'return_id',p_return_id,
    'status','needs_replacement',
    'unit_tag',v_return.unit_tag,
    'equipment_type',v_return.equipment_type,
    'owner_notified',true,
    'existing_damage_hold',v_existing_hold
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.it_prepare_service_truck_battery_restock_v1(p_request_id uuid, p_qty_issued integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_req public.service_truck_restock_requests%rowtype;
  v_profile public.profiles%rowtype;
  v_name text;
begin
  perform public.require_role(array['it'::public.app_role,'owner'::public.app_role]);
  select * into v_profile from public.profiles where user_id=auth.uid() and active=true;
  v_name:=coalesce(v_profile.full_name,v_profile.username,case when v_profile.role::text='owner' then 'Owner/Admin' else 'IT Technician' end);
  select * into v_req from public.service_truck_restock_requests where id=p_request_id for update;
  if not found then raise exception 'Truck restock request not found.'; end if;
  if v_req.item_kind<>'battery' or v_req.status not in ('requested','preparing') then raise exception 'This battery restock is not ready for IT.'; end if;
  if coalesce(p_qty_issued,0)<v_req.qty_needed then raise exception 'Issue at least the required quantity: %.',v_req.qty_needed; end if;

  update public.service_truck_restock_requests
  set status='ready',qty_issued=p_qty_issued,prepared_by=auth.uid(),prepared_by_name=v_name,prepared_at=now(),updated_at=now()
  where id=p_request_id;

  insert into public.reports(kind,actor_id,actor_name,ticket_no,text)
  values('IT TRUCK STOCK READY',auth.uid(),v_name,v_req.original_ticket_no,
    p_qty_issued||' × '||v_req.item_type||' ready for '||v_req.service_tech_name||'''s permanent truck inventory.');

  return jsonb_build_object('id',p_request_id,'status','ready','qty_issued',p_qty_issued);
end;
$function$

CREATE OR REPLACE FUNCTION public.it_prepare_service_truck_sim_restock_v1(p_request_id uuid, p_replacement_sim_number text, p_number_verified boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_req public.service_truck_restock_requests%rowtype;
  v_profile public.profiles%rowtype;
  v_name text;
  v_sim text:=btrim(coalesce(p_replacement_sim_number,''));
begin
  perform public.require_role(array['it'::public.app_role,'owner'::public.app_role]);
  if v_sim='' then raise exception 'Enter the exact replacement SIM number.'; end if;
  if coalesce(p_number_verified,false) is not true then
    raise exception 'Physically verify the exact SIM number before marking it ready.';
  end if;

  select * into v_profile from public.profiles where user_id=auth.uid() and active=true;
  v_name:=coalesce(v_profile.full_name,v_profile.username,case when v_profile.role::text='owner' then 'Owner/Admin' else 'IT Technician' end);

  select * into v_req
  from public.service_truck_restock_requests
  where id=p_request_id
  for update;
  if not found then raise exception 'Truck SIM restock request not found.'; end if;
  if v_req.item_kind<>'sim' or v_req.status not in ('requested','preparing') then
    raise exception 'This SIM restock is not ready for IT.';
  end if;
  if v_req.sim_slot_no not between 1 and 3 then raise exception 'SIM slot is missing from this request.'; end if;

  if exists(
    select 1 from public.service_truck_sims s
    where s.status='assigned'
      and lower(btrim(coalesce(s.sim_number,'')))=lower(v_sim)
      and not (s.service_tech_id=v_req.service_tech_id and s.slot_no=v_req.sim_slot_no)
  ) then
    raise exception 'That SIM number is already assigned to another Service truck slot.';
  end if;

  update public.service_truck_restock_requests
  set status='ready',
      replacement_sim_number=v_sim,
      prep_checks=jsonb_build_object('sim_number_verified',true),
      prepared_by=auth.uid(),
      prepared_by_name=v_name,
      prepared_at=now(),
      updated_at=now()
  where id=p_request_id;

  insert into public.reports(kind,actor_id,actor_name,ticket_no,text)
  values(
    'IT TRUCK SIM READY',auth.uid(),v_name,v_req.original_ticket_no,
    'SIM '||v_sim||' verified and ready for '||v_req.service_tech_name||'''s permanent truck slot '||v_req.sim_slot_no||'.'
  );

  return jsonb_build_object('id',p_request_id,'status','ready','replacement_sim_number',v_sim,'sim_slot_no',v_req.sim_slot_no);
end;
$function$

CREATE OR REPLACE FUNCTION public.it_prepare_service_truck_unit_restock_v1(p_request_id uuid, p_replacement_unit_tag text, p_checks jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_req public.service_truck_restock_requests%rowtype;
  v_profile public.profiles%rowtype;
  v_name text;
  v_key text;
begin
  perform public.require_role(array['it'::public.app_role,'owner'::public.app_role]);
  perform public.refresh_service_truck_restock_requests_v1();
  select * into v_profile from public.profiles where user_id=auth.uid() and active=true;
  v_name:=coalesce(v_profile.full_name,v_profile.username,case when v_profile.role::text='owner' then 'Owner/Admin' else 'IT Technician' end);

  select * into v_req from public.service_truck_restock_requests where id=p_request_id for update;
  if not found then raise exception 'Truck restock request not found.'; end if;
  if v_req.item_kind<>'unit' then raise exception 'This is not a unit restock request.'; end if;
  if v_req.status='awaiting_return' then raise exception 'The old unit must be turned in through Service Return / IT Intake first.'; end if;
  if v_req.status not in ('requested','preparing') then raise exception 'This unit restock is not ready for IT preparation.'; end if;

  if nullif(trim(coalesce(p_replacement_unit_tag,'')),'') is null then raise exception 'Enter the replacement unit tag.'; end if;

  select equipment_key into v_key
  from public.equipment_master
  where trim(unit_tag)=trim(p_replacement_unit_tag)
    and lower(coalesce(workflow_type,canonical_family))=lower(v_req.item_type)
    and tracker_state='shop'
  limit 1;
  if v_key is null then
    raise exception 'Unit % is not a Shop Inventory % in the 2026 Unit Tracker.',trim(p_replacement_unit_tag),v_req.item_type;
  end if;

  if exists(
    select 1 from public.service_truck_units u
    where u.unit_tag is not null
      and lower(regexp_replace(u.unit_tag,'[^a-zA-Z0-9]','','g'))=lower(regexp_replace(trim(p_replacement_unit_tag),'[^a-zA-Z0-9]','','g'))
      and u.status='assigned'
  ) then raise exception 'That unit is already assigned to a Service truck.'; end if;

  if jsonb_typeof(p_checks)<>'object'
     or not (p_checks ?& array['identity_ok','power_ok','functions_ok','programmed_online_ok','sd_storage_ok','sim_monitoring_ok','clean_safe_ok'])
     or exists(
       select 1 from jsonb_each(p_checks)
       where key=any(array['identity_ok','power_ok','functions_ok','programmed_online_ok','sd_storage_ok','sim_monitoring_ok','clean_safe_ok'])
         and value<>'true'::jsonb
     )
  then
    raise exception 'Complete every replacement-unit IT readiness check before handing the unit to Service.';
  end if;

  update public.service_truck_restock_requests
  set status='ready',
      replacement_unit_tag=trim(p_replacement_unit_tag),
      prep_checks=p_checks,
      prepared_by=auth.uid(),
      prepared_by_name=v_name,
      prepared_at=now(),
      updated_at=now()
  where id=p_request_id;

  insert into public.unit_registry(unit_key,unit_tag,equipment_type,lifecycle_status,current_holder_id,current_holder_name,last_event,updated_at)
  values(v_key,trim(p_replacement_unit_tag),v_req.item_type,'ready_for_service',auth.uid(),v_name,'Prepared by IT for permanent Service Truck restock',now())
  on conflict(unit_key) do update
  set lifecycle_status='ready_for_service',current_holder_id=auth.uid(),current_holder_name=v_name,last_event=excluded.last_event,updated_at=now();

  insert into public.reports(kind,actor_id,actor_name,ticket_no,text)
  values('IT TRUCK RESTOCK READY',auth.uid(),v_name,v_req.original_ticket_no,
    v_req.item_type||' '||trim(p_replacement_unit_tag)||' is fully checked and ready for '||v_req.service_tech_name||'''s permanent truck inventory.');

  return jsonb_build_object('id',p_request_id,'status','ready','replacement_unit_tag',trim(p_replacement_unit_tag));
end;
$function$

CREATE OR REPLACE FUNCTION public.it_update_offline_escalation_v1(p_escalation_id uuid, p_it_notes text, p_action text, p_backup_prep_item_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_row public.field_escalations%rowtype;
  v_backup_id uuid;
  v_backup_tag text;
  v_backup_type text;
  v_backup_it_checked_out_at timestamptz;
  v_backup_checked_out_to uuid;
  v_backup_outcome text;
  v_backup_ticket text;
  v_name text;
  v_role public.app_role;
  v_status text;
  v_summary text;
  v_owner record;
begin
  perform public.require_role(array['it'::public.app_role,'owner'::public.app_role]);
  v_role:=public.current_app_role();
  v_name:=public.actor_display_name();

  if nullif(btrim(coalesce(p_it_notes,'')),'') is null then
    raise exception 'Record the IT troubleshooting checks and actions.';
  end if;
  if p_action not in ('continue_troubleshooting','repaired_onsite','authorize_backup_swap','unresolved_owner') then
    raise exception 'Choose a valid IT troubleshooting outcome.';
  end if;

  select * into v_row
  from public.field_escalations
  where id=p_escalation_id
  for update;
  if not found then raise exception 'Offline-unit escalation not found.'; end if;
  if v_row.resolved_at is not null or v_row.status not in ('waiting_it','joint_troubleshooting') then
    raise exception 'This offline-unit escalation is no longer waiting for an IT decision.';
  end if;

  if p_action='authorize_backup_swap' then
    if p_backup_prep_item_id is null then
      raise exception 'Choose the IT-checked-out backup unit being authorized.';
    end if;
    select i.id,i.unit_tag,i.equipment_type,i.spare_it_checked_out_at,
           i.spare_checked_out_to,i.spare_outcome,t.ticket_no
    into v_backup_id,v_backup_tag,v_backup_type,v_backup_it_checked_out_at,
         v_backup_checked_out_to,v_backup_outcome,v_backup_ticket
    from public.prep_items i
    join public.prep_tickets t on t.id=i.prep_ticket_id
    where i.id=p_backup_prep_item_id
      and i.purpose='BACKUP'::public.prep_purpose
    for update of i;

    if not found
       or v_backup_it_checked_out_at is null
       or v_backup_checked_out_to is distinct from v_row.service_tech_id
       or v_backup_outcome is not null
       or v_backup_ticket is distinct from v_row.ticket_no
    then
      raise exception 'The selected backup is not an active IT-checked-out unit for this Service Tech and MHelpDesk ticket.';
    end if;
  end if;

  v_status:=case p_action
    when 'continue_troubleshooting' then 'joint_troubleshooting'
    when 'repaired_onsite' then 'repaired_onsite'
    when 'authorize_backup_swap' then 'backup_swap_authorized'
    else 'unresolved_owner'
  end;

  v_summary:='MHelpDesk #'||v_row.ticket_no||' · Unit '||v_row.unit_tag||
    '. Original problem: '||v_row.original_problem||
    '. Service verified power and recorded: '||v_row.service_troubleshooting_notes||
    '. IT recorded: '||btrim(p_it_notes)||'.';

  update public.field_escalations
  set it_tech_id=auth.uid(),
      it_tech_name=v_name,
      it_troubleshooting_notes=btrim(p_it_notes),
      status=v_status,
      backup_prep_item_id=case when p_action='authorize_backup_swap' then v_backup_id else backup_prep_item_id end,
      backup_unit_tag=case when p_action='authorize_backup_swap' then v_backup_tag else backup_unit_tag end,
      backup_equipment_type=case when p_action='authorize_backup_swap' then v_backup_type else backup_equipment_type end,
      backup_authorized_at=case when p_action='authorize_backup_swap' then now() else backup_authorized_at end,
      owner_summary=case when p_action='unresolved_owner' then v_summary||' Service and IT could not determine a solution.' else owner_summary end,
      owner_notified_at=case when p_action='unresolved_owner' then now() else owner_notified_at end,
      resolved_at=case when p_action='repaired_onsite' then now() else resolved_at end
  where id=p_escalation_id;

  if p_action='unresolved_owner' then
    for v_owner in
      select user_id from public.profiles
      where active=true and role='owner'::public.app_role
    loop
      perform public.enqueue_app_notification(
        v_owner.user_id,'owner_action','Offline unit needs Owner decision',
        v_summary||' Service and IT could not determine a solution.',
        null,v_row.ticket_no,v_row.unit_tag
      );
    end loop;
  else
    perform public.enqueue_app_notification(
      v_row.service_tech_id,'equipment_ready_service',
      case p_action
        when 'authorize_backup_swap' then 'IT authorized backup swap'
        when 'repaired_onsite' then 'IT troubleshooting completed'
        else 'IT troubleshooting updated'
      end,
      case p_action
        when 'authorize_backup_swap' then 'IT Tech '||v_name||' authorized BACKUP '||v_backup_type||' Unit '||v_backup_tag||
          ' for MHelpDesk #'||v_row.ticket_no||'. Return the failed unit through IT Intake.'
        when 'repaired_onsite' then 'IT Tech '||v_name||' recorded the offline unit repaired onsite for MHelpDesk #'||v_row.ticket_no||'.'
        else 'IT Tech '||v_name||' recorded joint troubleshooting for Unit '||v_row.unit_tag||'. Continue Service + IT troubleshooting.'
      end,
      null,v_row.ticket_no,v_row.unit_tag
    );
  end if;

  insert into public.reports(kind,actor_id,actor_name,ticket_no,text)
  values(
    case p_action
      when 'continue_troubleshooting' then 'OFFLINE UNIT - JOINT TROUBLESHOOTING'
      when 'repaired_onsite' then 'OFFLINE UNIT - REPAIRED ONSITE'
      when 'authorize_backup_swap' then 'OFFLINE UNIT - BACKUP SWAP AUTHORIZED'
      else 'OFFLINE UNIT - OWNER ESCALATION'
    end,
    auth.uid(),v_name,v_row.ticket_no,
    v_summary||
      case p_action
        when 'continue_troubleshooting' then ' Service + IT troubleshooting remains active.'
        when 'repaired_onsite' then ' IT recorded the unit repaired onsite.'
        when 'authorize_backup_swap' then ' IT authorized BACKUP '||v_backup_type||' Unit '||v_backup_tag||
          '. The failed unit must return through Service Return → IT Intake.'
        else ' Service and IT could not determine a solution; Owner was notified.'
      end
  );

  if v_role='owner'::public.app_role then
    insert into public.reports(kind,actor_id,actor_name,ticket_no,text)
    values(
      'OWNER WORKFLOW OVERRIDE',auth.uid(),v_name,v_row.ticket_no,
      'Owner intentionally performed the IT troubleshooting decision for Unit '||v_row.unit_tag||
      ' with outcome '||replace(upper(p_action),'_',' ')||'.'
    );
  end if;

  return jsonb_build_object(
    'id',p_escalation_id,'status',v_status,
    'backup_unit_tag',case when p_action='authorize_backup_swap' then v_backup_tag else null end,
    'owner_notified',p_action='unresolved_owner'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.link_my_assignment_to_prep(p_assignment_id uuid, p_prep_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_assignment public.job_assignments%rowtype;
  v_prep public.prep_tickets%rowtype;
begin
  select * into v_assignment
  from public.job_assignments
  where id=p_assignment_id
    and assignee_user_id=auth.uid()
    and status in ('assigned','started')
  for update;
  if not found then raise exception 'Assignment not found or no longer active.'; end if;

  select * into v_prep
  from public.prep_tickets
  where id=p_prep_id;
  if not found then raise exception 'Equipment prep not found.'; end if;

  if trim(v_assignment.ticket_no)<>trim(v_prep.ticket_no) then
    raise exception 'The Tech Check prep does not match the assigned MHelpDesk reference.';
  end if;

  update public.job_assignments
  set prep_ticket_id=p_prep_id,
      status='started',
      started_at=coalesce(started_at,now()),
      updated_at=now()
  where id=p_assignment_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.log_service_truck_inventory_audit_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor public.profiles%rowtype;
  v_target public.profiles%rowtype;
  v_actor_name text;
  v_actor_role text;
  v_before text;
  v_after text;
  v_slot text;
  v_kind text;
  v_action text;
begin
  select * into v_actor
  from public.profiles
  where user_id=auth.uid();

  select * into v_target
  from public.profiles
  where user_id=coalesce(new.service_tech_id,old.service_tech_id);

  v_actor_name:=coalesce(
    v_actor.full_name,
    v_actor.username,
    to_jsonb(new)->>'assigned_by_name',
    to_jsonb(new)->>'updated_by_name',
    'System'
  );
  v_actor_role:=coalesce(v_actor.role::text,case when auth.uid() is null then 'system' else 'unknown' end);

  if tg_table_name='service_truck_units' then
    if row(old.unit_tag,old.status) is not distinct from row(new.unit_tag,new.status) then return new; end if;
    v_kind:='unit';
    v_slot:=new.equipment_type;
    v_before:=nullif(btrim(coalesce(old.unit_tag,'')),'');
    v_after:=nullif(btrim(coalesce(new.unit_tag,'')),'');
  elsif tg_table_name='service_truck_sims' then
    if row(old.sim_number,old.status) is not distinct from row(new.sim_number,new.status) then return new; end if;
    v_kind:='sim';
    v_slot:='SIM '||new.slot_no;
    v_before:=nullif(btrim(coalesce(old.sim_number,'')),'');
    v_after:=nullif(btrim(coalesce(new.sim_number,'')),'');
  elsif tg_table_name='service_truck_stock' then
    if old.recon_battery_qty is distinct from new.recon_battery_qty then
      insert into public.service_truck_inventory_audit(
        service_tech_id,service_tech_name,item_kind,item_slot,before_value,after_value,action,
        actor_id,actor_name,actor_role,details
      ) values(
        new.service_tech_id,coalesce(v_target.full_name,v_target.username,'Service Tech'),
        'stock','Recon Battery',old.recon_battery_qty::text,new.recon_battery_qty::text,
        case when new.recon_battery_qty>old.recon_battery_qty then 'added'
             when new.recon_battery_qty<old.recon_battery_qty then 'removed' else 'updated' end,
        auth.uid(),v_actor_name,v_actor_role,
        jsonb_build_object('qty_before',old.recon_battery_qty,'qty_after',new.recon_battery_qty)
      );
    end if;
    if old.agm_12v_110ah_qty is distinct from new.agm_12v_110ah_qty then
      insert into public.service_truck_inventory_audit(
        service_tech_id,service_tech_name,item_kind,item_slot,before_value,after_value,action,
        actor_id,actor_name,actor_role,details
      ) values(
        new.service_tech_id,coalesce(v_target.full_name,v_target.username,'Service Tech'),
        'stock','AGM 12V 110Ah',old.agm_12v_110ah_qty::text,new.agm_12v_110ah_qty::text,
        case when new.agm_12v_110ah_qty>old.agm_12v_110ah_qty then 'added'
             when new.agm_12v_110ah_qty<old.agm_12v_110ah_qty then 'removed' else 'updated' end,
        auth.uid(),v_actor_name,v_actor_role,
        jsonb_build_object('qty_before',old.agm_12v_110ah_qty,'qty_after',new.agm_12v_110ah_qty)
      );
    end if;
    if old.litime_12v_100ah_qty is distinct from new.litime_12v_100ah_qty then
      insert into public.service_truck_inventory_audit(
        service_tech_id,service_tech_name,item_kind,item_slot,before_value,after_value,action,
        actor_id,actor_name,actor_role,details
      ) values(
        new.service_tech_id,coalesce(v_target.full_name,v_target.username,'Service Tech'),
        'stock','LiTime 12V 100Ah',old.litime_12v_100ah_qty::text,new.litime_12v_100ah_qty::text,
        case when new.litime_12v_100ah_qty>old.litime_12v_100ah_qty then 'added'
             when new.litime_12v_100ah_qty<old.litime_12v_100ah_qty then 'removed' else 'updated' end,
        auth.uid(),v_actor_name,v_actor_role,
        jsonb_build_object('qty_before',old.litime_12v_100ah_qty,'qty_after',new.litime_12v_100ah_qty)
      );
    end if;
    return new;
  else
    return new;
  end if;

  v_action:=case
    when v_before is null and v_after is not null then 'added'
    when v_before is not null and v_after is null then 'removed'
    when v_before is distinct from v_after then 'changed'
    else 'updated'
  end;

  insert into public.service_truck_inventory_audit(
    service_tech_id,service_tech_name,item_kind,item_slot,before_value,after_value,action,
    actor_id,actor_name,actor_role,details
  ) values(
    new.service_tech_id,
    coalesce(v_target.full_name,v_target.username,'Service Tech'),
    v_kind,v_slot,v_before,v_after,v_action,
    auth.uid(),v_actor_name,v_actor_role,
    jsonb_build_object('status_before',old.status,'status_after',new.status)
  );

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.owner_add_inventory_asset(p_unit_tag text, p_asset_type text, p_asset_category text, p_notes text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_key text;
  v_owner public.profiles%rowtype;
  v_registry public.unit_registry%rowtype;
begin
  select * into v_owner from public.profiles
  where user_id=auth.uid() and role='owner' and active=true;
  if not found then raise exception 'Owner/Admin access required.'; end if;

  v_key := public.normalize_unit_key(p_unit_tag);
  if v_key='' then raise exception 'Unit / asset tag is required.'; end if;
  if nullif(trim(coalesce(p_asset_type,'')),'') is null then raise exception 'Equipment type is required.'; end if;
  if p_asset_category not in ('device','stand') then raise exception 'Choose Device or Stand.'; end if;

  if exists(select 1 from public.asset_inventory where unit_key=v_key) then
    raise exception 'Asset % is already in Equipment Inventory.', trim(p_unit_tag);
  end if;

  insert into public.asset_inventory(
    unit_key,unit_tag,asset_type,asset_category,availability_status,
    notes,last_event,created_by,created_by_name
  )
  values(
    v_key,trim(p_unit_tag),trim(p_asset_type),p_asset_category,'shop',
    nullif(trim(coalesce(p_notes,'')),''),
    'Added to Shop / Shelf Inventory',
    auth.uid(),public.actor_display_name()
  );

  select * into v_registry from public.unit_registry where unit_key=v_key for update;
  if not found then
    insert into public.unit_registry(
      unit_key,unit_tag,equipment_type,lifecycle_status,current_holder_id,current_holder_name,last_event,updated_at
    )
    values(
      v_key,trim(p_unit_tag),trim(p_asset_type),'shop_inventory',null,null,
      'Added to Shop / Shelf Inventory',now()
    );
  elsif v_registry.lifecycle_status in ('shop_inventory','assigned_to_tech','maintenance','retired') then
    update public.unit_registry
    set unit_tag=trim(p_unit_tag),
        equipment_type=trim(p_asset_type),
        lifecycle_status='shop_inventory',
        current_holder_id=null,
        current_holder_name=null,
        last_event='Added / confirmed in Shop Inventory',
        updated_at=now()
    where unit_key=v_key;
  end if;

  insert into public.asset_inventory_history(
    unit_key,unit_tag,action,to_status,actor_id,actor_name,notes
  ) values(
    v_key,trim(p_unit_tag),'added','shop',auth.uid(),public.actor_display_name(),
    nullif(trim(coalesce(p_notes,'')),'')
  );

  return v_key;
end;
$function$

CREATE OR REPLACE FUNCTION public.owner_adjust_service_truck_inventory_v2(p_service_tech_id uuid, p_kind text, p_slot text, p_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_owner public.profiles%rowtype; v_target public.profiles%rowtype; v_name text; v_qty int; v_before int;
begin
 select * into v_owner from public.profiles where user_id=auth.uid() and active=true and role::text='owner';
 if not found then raise exception 'Owner/Admin access required.'; end if;
 select * into v_target from public.profiles where user_id=p_service_tech_id and active=true and archived_at is null and role::text='service';
 if not found then raise exception 'Active Service Tech required.'; end if;
 v_name:=coalesce(v_owner.full_name,v_owner.username,'Owner');
 perform public.ensure_service_truck_baseline_v1(p_service_tech_id);

 if p_kind='unit' then
   if p_slot not in ('Sniper','Ranger','Spotter','Solar Spotter') or nullif(trim(p_value),'') is null then raise exception 'Exact unit tag required.'; end if;
   update public.service_truck_units set unit_tag=trim(p_value),status='assigned',assigned_by=auth.uid(),assigned_by_name=v_name,assigned_at=now(),last_used_ticket_no=null,last_used_at=null,old_unit_tag=null
   where service_tech_id=p_service_tech_id and equipment_type=p_slot;
 elsif p_kind='sim' then
   if p_slot not in ('1','2','3') or nullif(trim(p_value),'') is null then raise exception 'Exact SIM number required.'; end if;
   update public.service_truck_sims set sim_number=trim(p_value),status='assigned',assigned_by=auth.uid(),assigned_by_name=v_name,assigned_at=now(),last_used_ticket_no=null,last_used_at=null
   where service_tech_id=p_service_tech_id and slot_no=p_slot::int;
 elsif p_kind='stock' then
   v_qty:=p_value::int; if v_qty<0 then raise exception 'Quantity cannot be negative.'; end if;
   if p_slot='Recon Battery' then update public.service_truck_stock set recon_battery_qty=v_qty,updated_by=auth.uid(),updated_by_name=v_name,updated_at=now() where service_tech_id=p_service_tech_id;
   elsif p_slot='AGM 12V 110Ah' then update public.service_truck_stock set agm_12v_110ah_qty=v_qty,updated_by=auth.uid(),updated_by_name=v_name,updated_at=now() where service_tech_id=p_service_tech_id;
   elsif p_slot='LiTime 12V 100Ah' then update public.service_truck_stock set litime_12v_100ah_qty=v_qty,updated_by=auth.uid(),updated_by_name=v_name,updated_at=now() where service_tech_id=p_service_tech_id;
   else raise exception 'Invalid stock type.'; end if;
 else raise exception 'Invalid inventory adjustment type.'; end if;

 update public.service_truck_inventory_checks set ready=false,updated_at=now() where service_tech_id=p_service_tech_id and check_date=timezone('America/Chicago',now())::date;
 insert into public.reports(kind,actor_id,actor_name,text) values('OWNER TRUCK INVENTORY ADJUSTED',auth.uid(),v_name,coalesce(v_target.full_name,v_target.username,'Service Tech')||' · '||p_kind||' · '||p_slot||' = '||p_value||'. Service re-verification required.');
 perform public.refresh_service_truck_restock_requests_v1();
 return jsonb_build_object('ok',true,'service_tech_id',p_service_tech_id,'kind',p_kind,'slot',p_slot,'value',p_value);
end $function$

CREATE OR REPLACE FUNCTION public.owner_assign_inventory_asset(p_unit_key text, p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_owner public.profiles%rowtype;
  v_asset public.asset_inventory%rowtype;
  v_tech public.profiles%rowtype;
  v_registry public.unit_registry%rowtype;
  v_name text;
begin
  select * into v_owner from public.profiles
  where user_id=auth.uid() and role='owner' and active=true;
  if not found then raise exception 'Owner/Admin access required.'; end if;

  select * into v_asset from public.asset_inventory where unit_key=p_unit_key for update;
  if not found then raise exception 'Equipment asset not found.'; end if;
  if v_asset.availability_status in ('maintenance','retired') then
    raise exception 'Move this asset back to Shop Inventory before assigning it.';
  end if;

  select * into v_tech from public.profiles
  where user_id=p_user_id and active=true and archived_at is null and role in ('it','service');
  if not found then raise exception 'Choose an active IT Tech or Service Tech.'; end if;
  v_name := coalesce(v_tech.full_name,v_tech.username,'Technician');

  select * into v_registry from public.unit_registry where unit_key=v_asset.unit_key for update;
  if found and v_registry.lifecycle_status not in ('shop_inventory','assigned_to_tech','maintenance','retired') then
    raise exception 'Unit % is currently % on an active workflow and cannot be manually reassigned.',
      v_asset.unit_tag, replace(upper(v_registry.lifecycle_status),'_',' ');
  end if;

  insert into public.asset_inventory_history(
    unit_key,unit_tag,action,from_status,to_status,
    from_user_id,from_user_name,to_user_id,to_user_name,
    actor_id,actor_name
  ) values(
    v_asset.unit_key,v_asset.unit_tag,'assigned',
    v_asset.availability_status,'assigned',
    v_asset.assigned_to,v_asset.assigned_to_name,
    v_tech.user_id,v_name,
    auth.uid(),public.actor_display_name()
  );

  update public.asset_inventory
  set availability_status='assigned',
      assigned_to=v_tech.user_id,
      assigned_to_name=v_name,
      last_event='Assigned to '||
        case when v_tech.role='it' then 'IT Tech ' else 'Service Tech ' end||v_name,
      updated_at=now()
  where unit_key=v_asset.unit_key;

  insert into public.unit_registry(
    unit_key,unit_tag,equipment_type,lifecycle_status,current_holder_id,current_holder_name,last_event,updated_at
  )
  values(
    v_asset.unit_key,v_asset.unit_tag,v_asset.asset_type,'assigned_to_tech',
    v_tech.user_id,v_name,
    'Assigned to '||case when v_tech.role='it' then 'IT Tech ' else 'Service Tech ' end||v_name,
    now()
  )
  on conflict(unit_key) do update set
    unit_tag=excluded.unit_tag,
    equipment_type=excluded.equipment_type,
    lifecycle_status='assigned_to_tech',
    current_holder_id=excluded.current_holder_id,
    current_holder_name=excluded.current_holder_name,
    last_event=excluded.last_event,
    updated_at=now();
end;
$function$

