CREATE OR REPLACE FUNCTION public.owner_save_service_truck_inventory_batch_v1(p_service_tech_id uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_owner public.profiles%rowtype; v_target public.profiles%rowtype; v_name text; k text; v text; q int;
begin
 select * into v_owner from public.profiles where user_id=auth.uid() and active=true and role::text='owner'; if not found then raise exception 'Owner/Admin access required.'; end if;
 select * into v_target from public.profiles where user_id=p_service_tech_id and active=true and archived_at is null and role::text='service'; if not found then raise exception 'Active Service Tech required.'; end if;
 v_name:=coalesce(v_owner.full_name,v_owner.username,'Owner'); perform public.ensure_service_truck_baseline_v1(p_service_tech_id);
 -- Free this technician's existing tags first so a single batch can swap/move tags between its four slots.
 update public.service_truck_units set status='unassigned',unit_tag=null where service_tech_id=p_service_tech_id;
 foreach k in array array['Sniper','Ranger','Spotter','Solar Spotter'] loop
   v:=nullif(trim(p_payload->'units'->>k),'');
   if v is not null then
     if exists(select 1 from public.service_truck_units u where u.service_tech_id<>p_service_tech_id and u.status='assigned' and u.unit_tag=v) then
       raise exception 'Unit % is already assigned to another Service Tech truck.',v;
     end if;
     update public.service_truck_units set unit_tag=v,status='assigned',assigned_by=auth.uid(),assigned_by_name=v_name,assigned_at=now(),last_used_ticket_no=null,last_used_at=null,old_unit_tag=null where service_tech_id=p_service_tech_id and equipment_type=k;
   end if;
 end loop;
 for q in 1..3 loop v:=nullif(trim(p_payload->'sims'->>q::text),''); if v is not null then update public.service_truck_sims set sim_number=v,status='assigned',assigned_by=auth.uid(),assigned_by_name=v_name,assigned_at=now(),last_used_ticket_no=null,last_used_at=null where service_tech_id=p_service_tech_id and slot_no=q; end if; end loop;
 q:=greatest(0,coalesce((p_payload->'stock'->>'Recon Battery')::int,0)); update public.service_truck_stock set recon_battery_qty=q,updated_by=auth.uid(),updated_by_name=v_name,updated_at=now() where service_tech_id=p_service_tech_id;
 q:=greatest(0,coalesce((p_payload->'stock'->>'AGM 12V 110Ah')::int,0)); update public.service_truck_stock set agm_12v_110ah_qty=q,updated_by=auth.uid(),updated_by_name=v_name,updated_at=now() where service_tech_id=p_service_tech_id;
 q:=greatest(0,coalesce((p_payload->'stock'->>'LiTime 12V 100Ah')::int,0)); update public.service_truck_stock set litime_12v_100ah_qty=q,updated_by=auth.uid(),updated_by_name=v_name,updated_at=now() where service_tech_id=p_service_tech_id;
 q:=greatest(0,coalesce((p_payload->'stock'->>'12V 35Ah')::int,0)); update public.service_truck_stock set battery_12v_35ah_qty=q,updated_by=auth.uid(),updated_by_name=v_name,updated_at=now() where service_tech_id=p_service_tech_id;
 perform public.close_stale_service_truck_restock_requests_v1(); perform public.refresh_service_truck_restock_requests_v1();
 update public.service_truck_inventory_checks set ready=false,updated_at=now() where service_tech_id=p_service_tech_id and check_date=timezone('America/Chicago',now())::date;
 insert into public.reports(kind,actor_id,actor_name,text) values('OWNER TRUCK INVENTORY SAVED',auth.uid(),v_name,coalesce(v_target.full_name,v_target.username,'Service Tech')||' truck inventory saved as one Owner update. Service re-verification required.');
 return jsonb_build_object('ok',true);
end $function$

CREATE OR REPLACE FUNCTION public.owner_set_inventory_asset_status(p_unit_key text, p_status text, p_notes text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_owner public.profiles%rowtype;
  v_asset public.asset_inventory%rowtype;
  v_registry public.unit_registry%rowtype;
  v_lifecycle text;
  v_event text;
begin
  select * into v_owner from public.profiles
  where user_id=auth.uid() and role='owner' and active=true;
  if not found then raise exception 'Owner/Admin access required.'; end if;
  if p_status not in ('shop','maintenance','retired') then
    raise exception 'Invalid equipment status.';
  end if;

  select * into v_asset from public.asset_inventory where unit_key=p_unit_key for update;
  if not found then raise exception 'Equipment asset not found.'; end if;

  if p_status='shop' and exists (
    select 1
    from public.unit_returns r
    where public.normalize_unit_key(r.unit_tag)=v_asset.unit_key
      and r.status='needs_replacement'
  ) then
    raise exception
      'Damaged Unit % is still under a Needs Replacement hold and cannot be returned to Shop Inventory. MISSING INFORMATION: the final repair/replacement disposition has not been completed.',
      v_asset.unit_tag;
  end if;

  select * into v_registry from public.unit_registry where unit_key=v_asset.unit_key for update;
  if found and v_registry.lifecycle_status not in ('shop_inventory','assigned_to_tech','maintenance','retired') then
    raise exception 'Unit % is currently % on an active workflow. Finish that workflow before changing inventory status.',
      v_asset.unit_tag, replace(upper(v_registry.lifecycle_status),'_',' ');
  end if;

  v_lifecycle := case p_status when 'shop' then 'shop_inventory' when 'maintenance' then 'maintenance' else 'retired' end;
  v_event := case p_status when 'shop' then 'Returned to Shop / Shelf Inventory' when 'maintenance' then 'Moved to Maintenance' else 'Retired from active inventory' end;

  insert into public.asset_inventory_history(
    unit_key,unit_tag,action,from_status,to_status,
    from_user_id,from_user_name,actor_id,actor_name,notes
  ) values(
    v_asset.unit_key,v_asset.unit_tag,
    case p_status when 'shop' then 'returned_to_shop' when 'maintenance' then 'maintenance' else 'retired' end,
    v_asset.availability_status,p_status,
    v_asset.assigned_to,v_asset.assigned_to_name,
    auth.uid(),public.actor_display_name(),
    nullif(trim(coalesce(p_notes,'')),'')
  );

  update public.asset_inventory
  set availability_status=p_status,
      assigned_to=null,
      assigned_to_name=null,
      notes=case when nullif(trim(coalesce(p_notes,'')),'') is null then notes else trim(p_notes) end,
      last_event=v_event,
      updated_at=now()
  where unit_key=v_asset.unit_key;

  insert into public.unit_registry(
    unit_key,unit_tag,equipment_type,lifecycle_status,current_holder_id,current_holder_name,last_event,updated_at
  )
  values(
    v_asset.unit_key,v_asset.unit_tag,v_asset.asset_type,v_lifecycle,
    null,null,v_event,now()
  )
  on conflict(unit_key) do update set
    unit_tag=excluded.unit_tag,
    equipment_type=excluded.equipment_type,
    lifecycle_status=excluded.lifecycle_status,
    current_holder_id=null,
    current_holder_name=null,
    last_event=excluded.last_event,
    updated_at=now();
end;
$function$

CREATE OR REPLACE FUNCTION public.owner_set_service_truck_stock_count_v1(p_service_tech_id uuid, p_item_type text, p_qty integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor public.profiles%rowtype;
  v_target public.profiles%rowtype;
  v_actor_name text;
  v_target_name text;
  v_stock public.service_truck_stock%rowtype;
  v_before integer;
begin
  perform public.require_role(array['owner'::public.app_role]);
  if coalesce(p_qty,-1) < 0 then raise exception 'Quantity cannot be negative.'; end if;
  if p_item_type not in ('Recon Battery','AGM 12V 110Ah','LiTime 12V 100Ah') then raise exception 'Invalid permanent truck stock type.'; end if;

  select * into v_actor from public.profiles where user_id=auth.uid() and active=true;
  v_actor_name:=coalesce(v_actor.full_name,v_actor.username,'Owner/Admin');
  select * into v_target from public.profiles where user_id=p_service_tech_id and active=true and archived_at is null and role::text='service';
  if not found then raise exception 'Active Service Tech required.'; end if;
  v_target_name:=coalesce(v_target.full_name,v_target.username,'Service Tech');

  perform public.ensure_service_truck_baseline_v1(p_service_tech_id);
  select * into v_stock from public.service_truck_stock where service_tech_id=p_service_tech_id for update;

  if p_item_type='Recon Battery' then
    v_before:=v_stock.recon_battery_qty;
    update public.service_truck_stock set recon_battery_qty=p_qty,updated_by=auth.uid(),updated_by_name=v_actor_name,updated_at=now() where service_tech_id=p_service_tech_id;
  elsif p_item_type='AGM 12V 110Ah' then
    v_before:=v_stock.agm_12v_110ah_qty;
    update public.service_truck_stock set agm_12v_110ah_qty=p_qty,updated_by=auth.uid(),updated_by_name=v_actor_name,updated_at=now() where service_tech_id=p_service_tech_id;
  else
    v_before:=v_stock.litime_12v_100ah_qty;
    update public.service_truck_stock set litime_12v_100ah_qty=p_qty,updated_by=auth.uid(),updated_by_name=v_actor_name,updated_at=now() where service_tech_id=p_service_tech_id;
  end if;

  insert into public.service_truck_stock_history(service_tech_id,item_type,qty_before,qty_added,qty_after,actor_id,actor_name,note)
  values(p_service_tech_id,p_item_type,v_before,p_qty-v_before,p_qty,auth.uid(),v_actor_name,'Owner corrected permanent truck stock count from Technician Command Board.');

  update public.service_truck_inventory_checks
  set ready=false,missing_items=jsonb_build_array(jsonb_build_object('kind','verification','item_type',p_item_type,'message','Owner adjusted permanent truck stock. Service must physically recount the truck before leaving.')),updated_at=now()
  where service_tech_id=p_service_tech_id and check_date=timezone('America/Chicago',now())::date;

  insert into public.reports(kind,actor_id,actor_name,text)
  values('OWNER SERVICE TRUCK STOCK ADJUSTED',auth.uid(),v_actor_name,p_item_type||' on '||v_target_name||'''s truck changed from '||v_before||' to '||p_qty||'. Service recount required.');

  perform public.refresh_service_truck_restock_requests_v1();
  return public.service_departure_readiness_v1(p_service_tech_id);
end;
$function$

