$function$

CREATE OR REPLACE FUNCTION public.owner_update_ticket_equipment_v1(p_ticket_no text, p_equipment_manifest jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_ticket text:=trim(coalesce(p_ticket_no,''));
  v_manifest jsonb:='[]'::jsonb;
  v_device_count int:=0;
  v_assignment_rows int:=0;
  v_prep_rows int:=0;
  v_before jsonb;
begin
  perform public.require_role(array['owner'::public.app_role]);
  if v_ticket='' then raise exception 'MHelpDesk ticket number is required.'; end if;
  if jsonb_typeof(coalesce(p_equipment_manifest,'[]'::jsonb))<>'array' then
    raise exception 'Equipment manifest must be an array.';
  end if;

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'category',case when lower(trim(x->>'category')) in ('device','stand','other') then lower(trim(x->>'category')) else 'other' end,
      'label',trim(x->>'label'),
      'qty',(x->>'qty')::int
    )
    order by ord
  ),'[]'::jsonb)
  into v_manifest
  from jsonb_array_elements(coalesce(p_equipment_manifest,'[]'::jsonb)) with ordinality e(x,ord)
  where nullif(trim(x->>'label'),'') is not null
    and (x->>'qty') ~ '^[0-9]+$'
    and (x->>'qty')::int > 0;

  if exists(
    select 1 from jsonb_array_elements(coalesce(p_equipment_manifest,'[]'::jsonb)) x
    where nullif(trim(x->>'label'),'') is not null
      and (
        not ((x->>'qty') ~ '^[0-9]+$')
        or (x->>'qty')::int < 0
        or (x->>'qty')::int > 999
      )
  ) then
    raise exception 'Equipment quantities must be whole numbers from 0 to 999.';
  end if;

  select coalesce(sum((x->>'qty')::int),0)
  into v_device_count
  from jsonb_array_elements(v_manifest) x
  where x->>'category'='device';

  select jsonb_build_object(
    'assignments',coalesce(jsonb_agg(jsonb_build_object('id',a.id,'role',a.assigned_role,'status',a.status,'equipment_manifest',a.equipment_manifest)),'[]'::jsonb)
  )
  into v_before
  from public.job_assignments a
  where trim(a.ticket_no)=v_ticket and a.status in ('assigned','started');

  update public.job_assignments
  set equipment_manifest=v_manifest,
      requested_unit_count=v_device_count,
      updated_at=now()
  where trim(ticket_no)=v_ticket
    and status in ('assigned','started');
  get diagnostics v_assignment_rows=row_count;

  update public.prep_tickets
  set equipment_manifest=v_manifest,
      requested_unit_count=v_device_count
  where trim(ticket_no)=v_ticket
    and status in ('draft','released');
  get diagnostics v_prep_rows=row_count;

  if v_assignment_rows=0 and v_prep_rows=0 then
    raise exception 'No active Tech Check record exists for MHelpDesk #%.' ,v_ticket;
  end if;

  insert into public.reports(kind,actor_id,actor_name,ticket_no,text)
  values(
    'OWNER EQUIPMENT UPDATE',
    auth.uid(),
    public.actor_display_name(),
    v_ticket,
    'Owner updated Tech Check equipment quantities to '||v_manifest::text||'. MHelpDesk unchanged.'
  );

  return jsonb_build_object(
    'ok',true,
    'ticket_no',v_ticket,
    'equipment_manifest',v_manifest,
    'requested_unit_count',v_device_count,
    'assignment_rows_updated',v_assignment_rows,
    'prep_rows_updated',v_prep_rows,
    'before_state',v_before
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.owner_verify_helios_install_v1(p_prep_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_status public.prep_status; v_ticket text; v_test boolean; v_name text; v_helios int:=0; v_swaps int:=0; v_returns int:=0;
begin
  perform public.require_role(array['owner'::public.app_role]);
  select status,ticket_no,is_test into v_status,v_ticket,v_test from public.prep_tickets where id=p_prep_id for update;
  if not found or v_status<>'released' then raise exception 'Helios job is not waiting for Owner verification'; end if;
  select count(*) filter(where equipment_type='Helios' and purpose in ('DELIVERY','SWAP')),count(*) filter(where equipment_type='Helios' and purpose='SWAP')
  into v_helios,v_swaps from public.prep_items where prep_ticket_id=p_prep_id;
  if v_helios<1 then raise exception 'No field-installed Helios is on this ticket'; end if;
  if not exists(select 1 from public.service_solar_checks where prep_ticket_id=p_prep_id and helios_field_completed_at is not null) then raise exception 'Service has not submitted the Helios field installation'; end if;
  if (select count(*) from public.service_solar_evidence where prep_ticket_id=p_prep_id and category='helios_install' and kind='photo')<v_helios then raise exception 'Final Helios installation photo proof is incomplete'; end if;
  if not exists(select 1 from public.service_solar_evidence where prep_ticket_id=p_prep_id and category='helios_install' and kind='signature') then raise exception 'Final Helios installation signature is missing'; end if;
  if v_swaps>0 then
    select count(*) into v_returns from public.unit_returns
    where trim(ticket_no)=trim(v_ticket) and equipment_type='Helios' and coalesce(array_length(return_photo_paths,1),0)>0
      and nullif(trim(coalesce(return_notes,'')),'') is not null and coalesce(tag_scan_status,'')<>'mismatch';
    if v_returns<v_swaps then raise exception 'OLD UNIT RETURNING documentation is incomplete for this Helios SWAP'; end if;
  end if;
  if exists(select 1 from public.prep_items where prep_ticket_id=p_prep_id and purpose='BACKUP' and spare_outcome is null) then raise exception 'Resolve every checked-out truck spare as USED FOR SWAP or RETURN UNUSED TO SHOP before final Owner verification'; end if;
  v_name:=public.actor_display_name();
  update public.service_solar_checks set helios_owner_verified_at=now(),helios_owner_verified_by=auth.uid(),helios_owner_verified_by_name=v_name,updated_at=now() where prep_ticket_id=p_prep_id;
  update public.prep_tickets set status='closed',closed_by=auth.uid(),closed_by_name=v_name,closed_at=now() where id=p_prep_id;
  update public.job_assignments set prep_ticket_id=p_prep_id,status='completed',completed_at=now(),updated_at=now()
  where assigned_role='service' and ticket_no=v_ticket and status in ('assigned','started');
  insert into public.reports(kind,actor_id,actor_name,ticket_no,text,is_test)
  values(case when coalesce(v_test,false) then 'TEST HELIOS OWNER FINAL VERIFIED' else 'HELIOS OWNER FINAL VERIFIED' end,
    auth.uid(),v_name,v_ticket,
    'Owner '||v_name||' reviewed the Helios field-install checklist, final photos, timestamped Service signature, and any OLD UNIT RETURNING swap documentation. The Helios deployment is final verified.',
    coalesce(v_test,false));
end;
$function$

CREATE OR REPLACE FUNCTION public.record_handoff_evidence(p_prep_id uuid, p_stage text, p_kind text, p_storage_path text, p_original_name text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_status public.prep_status;
  v_role public.app_role;
  v_id uuid;
  v_name text;
  v_original text;
  v_existing public.handoff_evidence%rowtype;
begin
  v_role:=public.current_app_role();
  if v_role is null or v_role not in ('owner'::public.app_role,'it'::public.app_role,'service'::public.app_role) then
    raise exception 'Active technician access is required';
  end if;
  if p_stage not in ('it','service') then raise exception 'Invalid handoff stage'; end if;
  if p_kind not in ('photo','signature') then raise exception 'Invalid evidence type'; end if;
  if nullif(trim(p_storage_path),'') is null then raise exception 'Evidence file path is required'; end if;
  if split_part(p_storage_path,'/',1)<>auth.uid()::text then
    raise exception 'Evidence path does not belong to this technician';
  end if;

  select status into v_status
  from public.prep_tickets
  where id=p_prep_id
  for update;
  if not found then raise exception 'Equipment prep not found'; end if;

  if p_stage='it' then
    if v_role not in ('it'::public.app_role,'owner'::public.app_role) then
      raise exception 'Only IT or Owner can add IT handoff evidence';
    end if;
    if v_status<>'draft'::public.prep_status then
      raise exception 'IT handoff evidence can only be added before equipment is sent to Service';
    end if;
  else
    if v_role not in ('service'::public.app_role,'owner'::public.app_role) then
      raise exception 'Only Service or Owner can add Service receipt evidence';
    end if;
    if v_status<>'released'::public.prep_status then
      raise exception 'Service receipt evidence can only be added while equipment is waiting for Service';
    end if;
  end if;

  select * into v_existing
  from public.handoff_evidence
  where storage_path=trim(p_storage_path)
  limit 1;

  if found then
    if v_existing.prep_ticket_id<>p_prep_id
       or v_existing.stage<>p_stage
       or v_existing.kind<>p_kind
       or v_existing.prep_item_id is not null
       or v_existing.created_by<>auth.uid() then
      raise exception 'This evidence file path is already attached to a different Tech Check record';
    end if;
    return v_existing.id;
  end if;

  v_name:=public.actor_display_name();
  v_original:=nullif(trim(p_original_name),'');

  if p_kind='signature' then
    if v_original is null then
      delete from public.handoff_evidence
      where prep_ticket_id=p_prep_id
        and stage=p_stage
        and kind='signature';
    else
      delete from public.handoff_evidence
      where prep_ticket_id=p_prep_id
        and stage=p_stage
        and kind='signature'
        and original_name=v_original;
    end if;
  end if;

  insert into public.handoff_evidence(
    prep_ticket_id,stage,kind,storage_path,original_name,created_by,created_by_name
  )
  values(
    p_prep_id,p_stage,p_kind,trim(p_storage_path),v_original,auth.uid(),v_name
  )
  returning id into v_id;

  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_it_unit_ai_tag_scan(p_item_id uuid, p_status text, p_detected text DEFAULT NULL::text, p_confidence numeric DEFAULT NULL::numeric, p_engine text DEFAULT 'tesseract.js-7.0.0'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_status public.prep_status;
  v_tag text;
  v_prep uuid;
begin
  perform public.require_role(array['it'::public.app_role,'owner'::public.app_role]);

  if p_status not in ('match','mismatch','unreadable') then
    raise exception 'Invalid AI tag scan status';
  end if;

  select i.prep_ticket_id,t.status,i.unit_tag
  into v_prep,v_status,v_tag
  from public.prep_items i
  join public.prep_tickets t on t.id=i.prep_ticket_id
  where i.id=p_item_id
  for update of i,t;

  if not found then raise exception 'Prep item not found'; end if;
  if v_status<>'draft'::public.prep_status then
    raise exception 'AI photo tag scan can only be recorded while IT prep is pending';
  end if;
  if nullif(trim(v_tag),'') is null then
    raise exception 'Enter the exact unit tag before scanning the photo';
  end if;
  if not exists(
    select 1 from public.handoff_evidence
    where prep_ticket_id=v_prep
      and prep_item_id=p_item_id
      and stage='it'
      and kind='photo'
  ) then
    raise exception 'Save the unit photo before recording the AI tag scan';
  end if;

  update public.prep_items
  set ai_tag_scan_status=p_status,
      ai_tag_scan_detected=nullif(trim(coalesce(p_detected,'')),''),
      ai_tag_scan_expected=v_tag,
      ai_tag_scan_confidence=case when p_confidence is null then null else greatest(0,least(100,p_confidence)) end,
      ai_tag_scan_engine=left(coalesce(nullif(trim(p_engine),''),'tesseract.js-7.0.0'),80),
      ai_tag_scan_at=now(),
      photo_tag_match_ok=case when p_status='mismatch' then false else photo_tag_match_ok end
  where id=p_item_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_service_solar_evidence(p_prep_id uuid, p_category text, p_kind text, p_storage_path text, p_original_name text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_role public.app_role;
  v_status public.prep_status;
  v_id uuid;
  v_name text;
begin
  v_role:=public.current_app_role();
  if v_role not in ('service'::public.app_role,'owner'::public.app_role) then
    raise exception 'Service or Operations Manager access required';
  end if;

  if p_category not in ('solar_stand','batteries','mppt','helios_cerbo_mppt','helios_yard','helios_install') then
    raise exception 'Invalid Solar / Helios evidence category';
  end if;
  if p_kind not in ('photo','signature') then
    raise exception 'Invalid evidence type';
  end if;
  if nullif(trim(p_storage_path),'') is null then
    raise exception 'Evidence file path is required';
  end if;
  if split_part(p_storage_path,'/',1)<>auth.uid()::text then
    raise exception 'Evidence path does not belong to this technician';
  end if;

  select status into v_status
  from public.prep_tickets
  where id=p_prep_id
  for update;

  if not found then raise exception 'Equipment prep not found'; end if;
  if v_status<>'released'::public.prep_status then
    raise exception 'Service Solar / Helios evidence can only be added while equipment is waiting for Service';
  end if;

  v_name:=public.actor_display_name();

  if p_kind='signature' then
    delete from public.service_solar_evidence
    where prep_ticket_id=p_prep_id
      and category=p_category
      and kind='signature'
      and created_by=auth.uid()
      and storage_path<>trim(p_storage_path);
  end if;

  insert into public.service_solar_evidence(
    prep_ticket_id,category,kind,storage_path,original_name,created_by,created_by_name
  )
  values(
    p_prep_id,p_category,p_kind,trim(p_storage_path),
    nullif(trim(p_original_name),''),
    auth.uid(),v_name
  )
  on conflict(storage_path) do update
  set original_name=excluded.original_name
  returning id into v_id;

  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_unit_handoff_evidence(p_prep_id uuid, p_item_id uuid, p_stage text, p_kind text, p_storage_path text, p_original_name text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_status public.prep_status; v_role public.app_role; v_id uuid; v_name text;
begin
  v_role:=public.current_app_role();
  if v_role is null or v_role not in ('owner'::public.app_role,'it'::public.app_role,'service'::public.app_role) then raise exception 'Active technician access is required'; end if;
  if p_stage not in ('it','service') then raise exception 'Invalid handoff stage'; end if;
  if p_kind not in ('photo','signature') then raise exception 'Invalid evidence type'; end if;
  if nullif(trim(p_storage_path),'') is null then raise exception 'Evidence file path is required'; end if;
  if split_part(p_storage_path,'/',1)<>auth.uid()::text then raise exception 'Evidence path does not belong to this technician'; end if;
  select t.status into v_status from public.prep_items i join public.prep_tickets t on t.id=i.prep_ticket_id where i.id=p_item_id and i.prep_ticket_id=p_prep_id for update of i,t;
  if not found then raise exception 'Equipment unit not found'; end if;
  if p_stage='it' then
    if v_role not in ('it'::public.app_role,'owner'::public.app_role) then raise exception 'Only IT or Owner can add IT evidence'; end if;
    if v_status<>'draft'::public.prep_status then raise exception 'IT evidence can only be added before equipment is sent to Service'; end if;
  else
    if v_role not in ('service'::public.app_role,'owner'::public.app_role) then raise exception 'Only Service or Owner can add Service evidence'; end if;
    if v_status<>'released'::public.prep_status then raise exception 'Service evidence can only be added while equipment is waiting for Service'; end if;
  end if;
  v_name:=public.actor_display_name();
  delete from public.handoff_evidence where prep_ticket_id=p_prep_id and prep_item_id=p_item_id and stage=p_stage and kind=p_kind;
  insert into public.handoff_evidence(prep_ticket_id,prep_item_id,stage,kind,storage_path,original_name,created_by,created_by_name)
  values(p_prep_id,p_item_id,p_stage,p_kind,trim(p_storage_path),nullif(trim(p_original_name),''),auth.uid(),v_name)
  returning id into v_id;
  if p_stage='it' and p_kind='photo' then
    update public.prep_items set photo_tag_match_ok=false where id=p_item_id;
  end if;
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.release_prep(p_prep_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_no text; v_test boolean; v_name text; v_photos int; v_signed_at timestamptz;
  v_expected integer; v_items integer; v_assignment record; v_recipient record;
  v_actor_id uuid; v_role public.app_role;
begin
  perform public.require_role(array['it'::public.app_role,'owner'::public.app_role]);
  v_role:=public.current_app_role();

  select ticket_no,is_test,expected_unit_count into v_no,v_test,v_expected
  from public.prep_tickets where id=p_prep_id and status='draft' for update;
  if not found then raise exception 'Draft equipment prep not found'; end if;

  select count(*) into v_items from public.prep_items where prep_ticket_id=p_prep_id;
  if v_expected is not null and v_items<>v_expected then
    raise exception 'This ticket requires % total job + truck-spare items, but % have been completed',v_expected,v_items;
  end if;
  if exists(
    select 1 from public.prep_items
    where prep_ticket_id=p_prep_id
      and (verified_at is null or (equipment_type<>'110V Stand' and unit_tag is null))
  ) then
    raise exception 'Every equipment item must be verified before the Service handoff';
  end if;

  if exists(
    select 1 from public.prep_items
    where prep_ticket_id=p_prep_id and equipment_type not in ('Solar Stand','110V Stand','Pole')
      and (purpose='DELIVERY'::public.prep_purpose or (equipment_type='Sniper' and purpose='SWAP'::public.prep_purpose))
      and not(delivery_sim_ok and delivery_camera_app_ok and delivery_customer_email_app_ok
        and delivery_batteries_charged_ok and delivery_monitoring_ok and delivery_ticket_count_ok
        and delivery_sd_formatted_ok and delivery_recording_ok)
  ) then
    raise exception 'Every DELIVERY camera unit and Sniper SWAP must pass all customer deployment readiness checks before the Service handoff';
  end if;

  if exists(
    select 1 from public.prep_items
    where prep_ticket_id=p_prep_id and equipment_type not in ('Solar Stand','110V Stand','Pole')
      and purpose='BACKUP'::public.prep_purpose
      and not(delivery_sim_ok and delivery_camera_app_ok and delivery_batteries_charged_ok
        and delivery_sd_formatted_ok and delivery_recording_ok)
  ) then
    raise exception 'Every BACKUP unit must be hardware-ready before the Service handoff';
  end if;

  if exists(
    select 1 from public.prep_items i
    where i.prep_ticket_id=p_prep_id
      and not (i.equipment_type='110V Stand' and nullif(trim(coalesce(i.unit_tag,'')),'') is null)
      and (
        (select count(*) from public.handoff_evidence e
         where e.prep_ticket_id=p_prep_id and e.prep_item_id=i.id and e.stage='it' and e.kind='photo')<>1
        or not coalesce(i.photo_tag_match_ok,false)
      )
  ) then
    raise exception 'Every tagged item requires exactly one IT photo clearly showing the matching unit tag before the Service handoff';
  end if;

  if v_expected is not null then
    if exists(
      select 1 from public.prep_items i where i.prep_ticket_id=p_prep_id
        and (select count(*) from public.handoff_evidence e
             where e.prep_ticket_id=p_prep_id and e.prep_item_id=i.id and e.stage='it' and e.kind='photo')<>1
    ) then
      raise exception 'Every item requires exactly one IT photo before the Service handoff';
    end if;
    if exists(
      select 1 from public.prep_items i where i.prep_ticket_id=p_prep_id
        and not exists(
          select 1 from public.handoff_evidence e
          where e.prep_ticket_id=p_prep_id and e.prep_item_id=i.id and e.stage='it' and e.kind='signature'
        )
    ) then
      raise exception 'Every item requires an IT signature before the Service handoff';
    end if;
    select count(*),max(created_at) into v_photos,v_signed_at
    from public.handoff_evidence
    where prep_ticket_id=p_prep_id and stage='it' and kind='photo' and prep_item_id is not null;
  else
    select count(*) into v_photos
    from public.handoff_evidence where prep_ticket_id=p_prep_id and stage='it' and kind='photo';
    if v_photos<1 then
      raise exception 'Upload at least one IT handoff photo before creating the Service handoff';
    end if;
    select max(created_at) into v_signed_at
    from public.handoff_evidence where prep_ticket_id=p_prep_id and stage='it' and kind='signature';
    if v_signed_at is null then raise exception 'IT signature is required before creating the Service handoff'; end if;
  end if;

  v_actor_id:=auth.uid();
  v_name:=public.actor_display_name();

  if coalesce(v_test,false) and v_role='owner'::public.app_role then
    select a.assignee_user_id,coalesce(a.assignee_name,p.full_name,p.username,'Test IT')
      into v_actor_id,v_name
    from public.job_assignments a
    left join public.profiles p on p.user_id=a.assignee_user_id
    where trim(a.ticket_no)=trim(v_no)
      and a.assigned_role='it'
      and a.created_from='owner_test_center'
      and a.assignee_user_id is not null
    order by a.assigned_at desc
    limit 1;

    if v_actor_id is null then
      v_actor_id:=auth.uid();
      v_name:=public.actor_display_name();
    end if;
  end if;

  update public.prep_tickets
  set status='released',released_by=v_actor_id,released_by_name=v_name,released_at=now()
  where id=p_prep_id;

  update public.job_assignments
  set prep_ticket_id=p_prep_id,status='completed',completed_at=now(),updated_at=now()
  where assigned_role='it'
    and ticket_no=v_no
    and assignee_user_id=v_actor_id
    and status in ('assigned','started');

  for v_assignment in
    select * from public.job_assignments
    where assigned_role='service' and ticket_no=v_no and status in ('assigned','started')
  loop
    update public.job_assignments set prep_ticket_id=p_prep_id,updated_at=now() where id=v_assignment.id;
    if v_assignment.assignee_user_id is not null then
      perform public.enqueue_app_notification(
        v_assignment.assignee_user_id,'equipment_ready_service','Equipment ready from IT',
        'IT Tech '||v_name||' created the Service handoff for MHelpDesk #'||v_no||
        '. Verify the units, truck spares, and parts before accepting them.',
        v_assignment.id,v_no,null
      );
    else
      for v_recipient in
        select * from public.profiles where active=true and role='service'
      loop
        perform public.enqueue_app_notification(
          v_recipient.user_id,'equipment_ready_service','Equipment ready for Service',
          'IT Tech '||v_name||' created the Service handoff for MHelpDesk #'||v_no||
          '. Claim the Service task and verify the equipment and truck spares.',
          v_assignment.id,v_no,null
        );
      end loop;
    end if;
  end loop;

  insert into public.reports(kind,actor_id,actor_name,ticket_no,text,is_test)
  values(
    case when v_test then 'TEST IT EQUIPMENT HANDOFF TO SERVICE' else 'IT EQUIPMENT HANDOFF TO SERVICE' end,
    v_actor_id,v_name,v_no,
    'IT Tech '||v_name||' verified '||v_items||' item'||case when v_items=1 then '' else 's' end||
    ', including any truck BACKUP units, attached '||coalesce(v_photos,0)||' matching handoff photo'||
    case when coalesce(v_photos,0)=1 then '' else 's' end||
    ' with matching unit tags where present, completed signed verification, and created the Service handoff.',
    coalesce(v_test,false)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.reopen_it_prep(p_prep_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_status public.prep_status;
  v_no text;
begin
  perform public.require_role(array['it'::public.app_role,'owner'::public.app_role]);
  select status,ticket_no into v_status,v_no from public.prep_tickets where id=p_prep_id for update;
  if not found then raise exception 'Equipment prep not found'; end if;
  if v_status='closed'::public.prep_status then raise exception 'Completed Service verification is locked. Owner can use Reset All Workflow Data if a full reset is needed.'; end if;
  if v_status='released'::public.prep_status then
    update public.prep_tickets
      set status='draft'::public.prep_status,released_by=null,released_by_name=null,released_at=null
      where id=p_prep_id;
    update public.prep_items
      set service_battery_count=null,service_unit_confirmed=null,service_verified_by=null,service_verified_at=null
      where prep_ticket_id=p_prep_id;
    insert into public.reports(kind,actor_id,actor_name,ticket_no,text)
    values('IT EQUIPMENT PREP REOPENED',auth.uid(),public.actor_display_name(),v_no,'IT reopened sent equipment prep to make corrections before Service verification.');
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.reopen_it_prep_with_reason(p_prep_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_status public.prep_status;
  v_no text;
  v_test boolean;
  v_reason text := nullif(trim(p_reason),'');
begin
  perform public.require_role(array['it'::public.app_role,'owner'::public.app_role]);
  if v_reason is null then raise exception 'A short reason is required'; end if;

  select status,ticket_no,is_test
  into v_status,v_no,v_test
  from public.prep_tickets
  where id=p_prep_id
  for update;

  if not found then raise exception 'Equipment prep not found'; end if;
  if v_status='closed'::public.prep_status then
    raise exception 'Completed Service verification is locked. Owner can clear the workspace if needed.';
  end if;

  if v_status='released'::public.prep_status then
    update public.prep_tickets
    set status='draft'::public.prep_status,
        released_by=null,
        released_by_name=null,
        released_at=null,
        service_parts_confirmed=false,
        service_parts_confirmed_by=null,
        service_parts_confirmed_by_name=null,
        service_parts_confirmed_at=null
    where id=p_prep_id;

    update public.prep_items
    set service_battery_count=null,
        service_unit_confirmed=null,
        service_verified_by=null,
        service_verified_at=null
    where prep_ticket_id=p_prep_id;

    delete from public.handoff_evidence
    where prep_ticket_id=p_prep_id and stage='service';

    delete from public.service_solar_evidence
    where prep_ticket_id=p_prep_id;

    delete from public.service_solar_checks
    where prep_ticket_id=p_prep_id;

    update public.job_assignments
    set status='started',
        completed_at=null,
        updated_at=now()
    where prep_ticket_id=p_prep_id
      and assigned_role='it'
      and status='completed';

    insert into public.reports(kind,actor_id,actor_name,ticket_no,text,reason,is_test)
    values(
      'IT EQUIPMENT RETURNED FOR CHANGES',
      auth.uid(),
      public.actor_display_name(),
      v_no,
      'The Service handoff was returned to IT for correction before Service verification.',
      v_reason,
      coalesce(v_test,false)
    );
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.reopen_service_solar_progress_v1(p_prep_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_role public.app_role;
  v_ticket text;
begin
  v_role:=public.current_app_role();
  if v_role not in ('service'::public.app_role,'owner'::public.app_role) then
    raise exception 'Service or Owner access required';
  end if;

  select ticket_no into v_ticket
  from public.prep_tickets
  where id=p_prep_id and status='released';

  if not found then
    raise exception 'Service handoff not found or no longer waiting for Service';
  end if;

  if v_role='service'::public.app_role and not exists(
    select 1
    from public.job_assignments a
    where a.assigned_role='service'
      and (a.prep_ticket_id=p_prep_id or trim(a.ticket_no)=trim(v_ticket))
      and a.assignee_user_id=auth.uid()
      and a.status in ('assigned','started','completed')
  ) then
    raise exception 'This Service handoff is not assigned to you';
  end if;

  update public.service_solar_checks
  set completed_at=null,
      updated_at=now()
  where prep_ticket_id=p_prep_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.repair_workflow_issue_v1(p_issue_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_profile public.profiles%rowtype;
  v_ticket text;
  v_prep public.prep_tickets%rowtype;
  v_assignment public.job_assignments%rowtype;
  v_before jsonb;
  v_after jsonb;
  v_repair text;
begin
  select * into v_profile from public.profiles
  where user_id=auth.uid() and active=true and archived_at is null and role='owner';
  if not found then raise exception 'Owner/Admin access required.'; end if;

  if p_issue_key like 'released_unlinked:%' then
    v_ticket:=substring(p_issue_key from length('released_unlinked:')+1);
    select * into v_prep from public.prep_tickets
      where trim(ticket_no)=trim(v_ticket) and status='released' and not is_test
      order by released_at desc limit 1 for update;
    select * into v_assignment from public.job_assignments
      where trim(ticket_no)=trim(v_ticket) and assigned_role='service' and status in ('assigned','started')
      order by assigned_at desc limit 1 for update;
    if v_prep.id is null or v_assignment.id is null then raise exception 'The records changed. Refresh Workflow Health.'; end if;
    v_before:=jsonb_build_object('assignment_id',v_assignment.id,'prep_ticket_id',v_assignment.prep_ticket_id);
    update public.job_assignments set prep_ticket_id=v_prep.id,updated_at=now() where id=v_assignment.id;
    v_after:=jsonb_build_object('assignment_id',v_assignment.id,'prep_ticket_id',v_prep.id);
    v_repair:='relink_service_assignment';
  elsif p_issue_key like 'released_missing_service:%' then
    v_ticket:=substring(p_issue_key from length('released_missing_service:')+1);
    select * into v_prep from public.prep_tickets
      where trim(ticket_no)=trim(v_ticket) and status='released' and not is_test
      order by released_at desc limit 1 for update;
    if v_prep.id is null then raise exception 'The IT handoff is no longer available. Refresh Workflow Health.'; end if;
    if exists(select 1 from public.job_assignments where trim(ticket_no)=trim(v_ticket) and assigned_role='service' and status in ('assigned','started')) then
      raise exception 'A Service assignment now exists. Refresh Workflow Health.';
    end if;
    v_before:=jsonb_build_object('service_assignment','missing','prep_ticket_id',v_prep.id);
    insert into public.job_assignments(ticket_no,site,assigned_role,status,prep_ticket_id,assigned_by,assigned_by_name,
      assigned_at,updated_at,assignment_scope,requires_it_handoff,work_type,requested_unit_count,equipment_manifest)
    values(v_prep.ticket_no,v_prep.site,'service','assigned',v_prep.id,auth.uid(),coalesce(v_profile.full_name,v_profile.username,'Owner/Admin'),
      now(),now(),'department',true,v_prep.work_type,v_prep.requested_unit_count,v_prep.equipment_manifest)
    returning * into v_assignment;
    v_after:=jsonb_build_object('assignment_id',v_assignment.id,'prep_ticket_id',v_prep.id,'status','assigned');
    v_repair:='recreate_service_assignment';
  else
    raise exception 'This issue is review-only and cannot be repaired automatically.';
  end if;

  insert into public.workflow_repair_audit(issue_key,ticket_no,repair_type,reason,before_state,after_state,repaired_by,repaired_by_name)
  values(p_issue_key,v_ticket,v_repair,'Existing workflow records proved the safe next state. No technician evidence or physical confirmation was created.',
    v_before,v_after,auth.uid(),coalesce(v_profile.full_name,v_profile.username,'Owner/Admin'));
  insert into public.reports(kind,actor_id,actor_name,ticket_no,text)
  values('WORKFLOW REPAIRED',auth.uid(),coalesce(v_profile.full_name,v_profile.username,'Owner/Admin'),v_ticket,
    'Safe workflow repair: '||replace(v_repair,'_',' ')||'. Existing records were relinked; no evidence or technician answer was invented.');
  return jsonb_build_object('ok',true,'ticket_no',v_ticket,'repair_type',v_repair,'after_state',v_after);
end;
$function$

CREATE OR REPLACE FUNCTION public.resolve_my_truck_spare_unit_v2(p_item_id uuid, p_outcome text, p_return_photo_paths text[] DEFAULT '{}'::text[], p_return_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_item public.prep_items%rowtype;
  v_prep public.prep_tickets%rowtype;
  v_name text;
  v_key text;
  v_owner boolean;
  v_return_service_id uuid;
  v_return_service_name text;
  v_return_id uuid := coalesce(p_return_id,gen_random_uuid());
begin
  perform public.require_role(array['service'::public.app_role,'owner'::public.app_role]);
  v_owner:=public.current_app_role()='owner'::public.app_role;

  if p_outcome not in ('used','returned_unused') then
    raise exception 'Choose used or returned_unused';
  end if;

  select * into v_item
  from public.prep_items
  where id=p_item_id
  for update;

  if not found or v_item.purpose<>'BACKUP'::public.prep_purpose then
    raise exception 'Truck spare unit not found';
  end if;

  if v_item.spare_outcome is not null then
    raise exception 'This truck spare has already been resolved';
  end if;

  select * into v_prep
  from public.prep_tickets
  where id=v_item.prep_ticket_id;

  if not found or v_prep.status<>'closed'::public.prep_status then
    raise exception 'Service must accept the IT handoff before resolving a truck spare';
  end if;

  if not v_owner and v_prep.closed_by is distinct from auth.uid() then
    raise exception 'This truck spare is assigned to another Service Tech';
  end if;

  if p_outcome='returned_unused'
     and coalesce(cardinality(p_return_photo_paths),0)<1 then
    raise exception 'Take a clear Service return photo of the unused backup before sending it to IT Intake';
  end if;

  v_name:=public.actor_display_name();
  v_return_service_id:=coalesce(v_item.spare_checked_out_to,v_prep.closed_by,auth.uid());
  v_return_service_name:=coalesce(
    nullif(trim(v_item.spare_checked_out_to_name),''),
    nullif(trim(v_prep.closed_by_name),''),
    v_name,
    'Service Tech'
  );

  update public.prep_items
  set spare_outcome=p_outcome,
      spare_outcome_by=auth.uid(),
      spare_outcome_by_name=v_name,
      spare_outcome_at=now()
  where id=p_item_id;

  v_key:=public.normalize_unit_key(v_item.unit_tag);

  if p_outcome='returned_unused' then
    insert into public.unit_returns(
      id,prep_ticket_id,prep_item_id,ticket_no,unit_tag,equipment_type,
      service_tech_id,service_tech_name,return_notes,return_photo_paths,status
    )
    values(
      v_return_id,v_prep.id,v_item.id,v_prep.ticket_no,v_item.unit_tag,v_item.equipment_type,
      v_return_service_id,v_return_service_name,
      'Unused complete BACKUP returned after transport. Service return photo is attached. IT Intake is required before this unit can return to Shop Inventory.',
      p_return_photo_paths,
      'waiting_it'
    );

    insert into public.reports(kind,actor_id,actor_name,ticket_no,text)
    values(
      'TRUCK SPARE RETURNED UNUSED',
      auth.uid(),v_name,v_prep.ticket_no,
      'Unused BACKUP '||v_item.equipment_type||' '||coalesce(v_item.unit_tag,'')||
      ' returned from the Service truck with Service return photo proof and entered Service Return → IT Intake. It is not available Shop Inventory until IT Intake and normal inventory completion are finished.'
    );
  else
    update public.unit_registry
    set lifecycle_status='deployed',
        current_holder_id=auth.uid(),
        current_holder_name=v_name,
        last_event='Truck spare used in field on MHelpDesk #'||v_prep.ticket_no,
        updated_at=now()
    where unit_key=v_key;

    insert into public.reports(kind,actor_id,actor_name,ticket_no,text)
    values(
      'TRUCK SPARE USED',
      auth.uid(),v_name,v_prep.ticket_no,
      'Service Tech '||v_name||' used BACKUP '||v_item.equipment_type||' '||coalesce(v_item.unit_tag,'')||
      ' in the field. Any replaced/failed unit must be returned through Service Return → IT Intake.'
    );
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_it_camera_family_checks_v1(p_item_id uuid, p_programmed_ok boolean, p_port_81_ok boolean, p_port_554_ok boolean, p_recon_camera_count integer DEFAULT NULL::integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_status public.prep_status;
  v_type text;
begin
  perform public.require_role(array['it'::public.app_role,'owner'::public.app_role]);

  select t.status,i.equipment_type
  into v_status,v_type
  from public.prep_items i
  join public.prep_tickets t on t.id=i.prep_ticket_id
  where i.id=p_item_id
  for update of i,t;

  if not found then raise exception 'Prep item not found'; end if;
  if v_status<>'draft'::public.prep_status then
    raise exception 'Only draft IT equipment can be edited';
  end if;
  if v_type not in ('Spotter','Recon 2','Ranger') then
    raise exception 'Camera-family checks apply only to Spotter, Recon II, or Ranger';
  end if;
  if v_type='Recon 2' and coalesce(p_recon_camera_count,0)<1 then
    raise exception 'Recon II requires the number of cameras being prepared';
  end if;

  update public.prep_items set
    unit_programmed_ok=case when v_type in ('Spotter','Recon 2') then coalesce(p_programmed_ok,false) else true end,
    camera_port_81_ok=coalesce(p_port_81_ok,false),
    camera_port_554_ok=coalesce(p_port_554_ok,false),
    recon_camera_count=case when v_type='Recon 2' then greatest(1,coalesce(p_recon_camera_count,1)) else null end
  where id=p_item_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_it_prep_item_draft(p_item_id uuid, p_unit_tag text, p_battery_count integer, p_power_ok boolean, p_functions_ok boolean, p_safe_ok boolean, p_sim_ok boolean DEFAULT false, p_camera_app_ok boolean DEFAULT false, p_batteries_charged_ok boolean DEFAULT false, p_monitoring_ok boolean DEFAULT false, p_ticket_count_ok boolean DEFAULT false, p_sd_formatted_ok boolean DEFAULT false, p_recording_ok boolean DEFAULT false, p_mppt_updated_ok boolean DEFAULT false, p_mppt_tested_ok boolean DEFAULT false, p_pv_charging_ok boolean DEFAULT false, p_solar_panels_match_ok boolean DEFAULT false, p_ticket_item_match_ok boolean DEFAULT false, p_customer_email_app_ok boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_status public.prep_status; v_purpose public.prep_purpose; v_required int; v_type text;
  v_tag text; v_count int; v_ready boolean; v_deploy_ready boolean;
  v_customer_deploy boolean; v_hardware_deploy boolean; v_camera_family_ready boolean;
  v_helios_detail_ready boolean;
begin
  perform public.require_role(array['it'::public.app_role,'owner'::public.app_role]);
  select t.status,i.purpose,i.required_battery_count,i.equipment_type
  into v_status,v_purpose,v_required,v_type
  from public.prep_items i join public.prep_tickets t on t.id=i.prep_ticket_id
  where i.id=p_item_id for update of i,t;
  if not found then raise exception 'Prep item not found'; end if;
  if v_status<>'draft'::public.prep_status then raise exception 'Return the Service handoff to IT before editing. Completed Service verification is locked.'; end if;

  v_tag:=nullif(trim(p_unit_tag),''); v_count:=greatest(coalesce(p_battery_count,0),0);
  if v_tag is not null and exists(
    select 1 from public.prep_items oi join public.prep_tickets ot on ot.id=oi.prep_ticket_id
    where oi.id<>p_item_id and lower(oi.unit_tag)=lower(v_tag) and ot.status<>'closed'::public.prep_status
  ) then raise exception 'Unit tag is already assigned to another active equipment prep'; end if;

  v_customer_deploy := v_purpose='DELIVERY'::public.prep_purpose
    or (v_type in ('Sniper','Spotter','Recon 2','Ranger') and v_purpose='SWAP'::public.prep_purpose);
  v_hardware_deploy := v_purpose in ('DELIVERY'::public.prep_purpose,'BACKUP'::public.prep_purpose
    ) or (v_type in ('Sniper','Spotter','Recon 2','Ranger') and v_purpose='SWAP'::public.prep_purpose);

  select case
    when v_type='Spotter' then coalesce(camera_port_81_ok,false) and coalesce(camera_port_554_ok,false) and coalesce(unit_programmed_ok,false)
    when v_type='Recon 2' then coalesce(camera_port_81_ok,false) and coalesce(camera_port_554_ok,false) and coalesce(unit_programmed_ok,false) and coalesce(recon_camera_count,0)>=1
    when v_type='Ranger' then coalesce(camera_port_81_ok,false) and coalesce(camera_port_554_ok,false)
    else true end,
    case when v_type='Helios' then
      coalesce(helios_camera1_hardware_ok,false) and coalesce(helios_camera2_hardware_ok,false)
      and coalesce(helios_ptz_assembly_ok,false) and coalesce(helios_proxicast_4x4_ok,false)
      and coalesce(helios_router_sim_ok,false) and coalesce(helios_speaker_24v_ok,false)
      and coalesce(helios_cameras_12v_ok,false) and coalesce(helios_ptz_plate_4bolts_ok,false)
      and coalesce(helios_cerbo_network_ok,false) and coalesce(helios_cerbo_vrm_ok,false)
      and coalesce(helios_rear_unit_tag_ok,false) and coalesce(helios_battery_box_installed_ok,false)
      and coalesce(helios_battery_120v_charged_ok,false) and coalesce(helios_camera_router_programming_ok,false)
      and coalesce(helios_alibi_vigilant_ok,false) and coalesce(helios_3x1tb_sd_ok,false)
      and coalesce(helios_camera1_ports_ok,false) and coalesce(helios_camera2_ports_ok,false)
      and coalesce(helios_ptz_ports_ok,false) and coalesce(helios_speaker_ports_ok,false)
    else true end
  into v_camera_family_ready,v_helios_detail_ready
  from public.prep_items where id=p_item_id;

  v_deploy_ready := case
    when v_customer_deploy then coalesce(p_sim_ok,false) and coalesce(p_camera_app_ok,false)
      and coalesce(p_customer_email_app_ok,false)
      and (v_type in ('Solar Spotter','Spotter') or coalesce(p_batteries_charged_ok,false))
      and coalesce(p_monitoring_ok,false) and (v_type='Helios' or coalesce(p_ticket_count_ok,false))
      and coalesce(p_sd_formatted_ok,false) and coalesce(p_recording_ok,false) and v_camera_family_ready
    when v_purpose='BACKUP'::public.prep_purpose then coalesce(p_sim_ok,false) and coalesce(p_camera_app_ok,false)
      and (v_type in ('Solar Spotter','Spotter') or coalesce(p_batteries_charged_ok,false))
      and coalesce(p_sd_formatted_ok,false) and coalesce(p_recording_ok,false) and v_camera_family_ready
    else true end;

  if v_type='110V Stand' then v_ready:=coalesce(p_ticket_item_match_ok,false);
  elsif v_type in ('Solar Stand','Pole') then v_ready:=v_tag is not null and coalesce(p_ticket_item_match_ok,false);
  elsif v_type='Ranger' then v_ready:=v_tag is not null and coalesce(p_power_ok,false) and coalesce(p_functions_ok,false)
      and coalesce(p_safe_ok,false) and v_count>=coalesce(v_required,0) and coalesce(p_mppt_updated_ok,false)
      and coalesce(p_mppt_tested_ok,false) and v_deploy_ready;
  elsif v_type='Helios' then v_ready:=v_tag is not null and coalesce(p_power_ok,false) and coalesce(p_functions_ok,false)
      and coalesce(p_safe_ok,false) and v_count>=coalesce(v_required,0)
      and v_deploy_ready and v_helios_detail_ready;
  else v_ready:=v_tag is not null and coalesce(p_power_ok,false) and coalesce(p_functions_ok,false)
      and coalesce(p_safe_ok,false) and v_count>=coalesce(v_required,0) and v_deploy_ready;
  end if;

  update public.prep_items set unit_tag=v_tag,battery_count=v_count,power_ok=coalesce(p_power_ok,false),
    functions_ok=coalesce(p_functions_ok,false),safe_ok=coalesce(p_safe_ok,false),
    verified_by=case when v_ready then auth.uid() else null end,verified_at=case when v_ready then now() else null end,
    delivery_sim_ok=case when v_hardware_deploy then coalesce(p_sim_ok,false) else false end,
    delivery_camera_app_ok=case when v_hardware_deploy then coalesce(p_camera_app_ok,false) else false end,
    delivery_customer_email_app_ok=case when v_customer_deploy then coalesce(p_customer_email_app_ok,false) else false end,
    delivery_batteries_charged_ok=case when v_type in ('Solar Spotter','Spotter') and v_hardware_deploy then true when v_hardware_deploy then coalesce(p_batteries_charged_ok,false) else false end,
    delivery_monitoring_ok=case when v_customer_deploy then coalesce(p_monitoring_ok,false) else false end,
    delivery_ticket_count_ok=case when v_type='Helios' and v_customer_deploy then true when v_customer_deploy then coalesce(p_ticket_count_ok,false) else false end,
    delivery_sd_formatted_ok=case when v_hardware_deploy then coalesce(p_sd_formatted_ok,false) else false end,
    delivery_recording_ok=case when v_hardware_deploy then coalesce(p_recording_ok,false) else false end,
    solar_mppt_updated_ok=case when v_type in ('Ranger','Helios') then coalesce(p_mppt_updated_ok,false) else false end,
    solar_mppt_tested_ok=case when v_type in ('Ranger','Helios') then coalesce(p_mppt_tested_ok,false) else false end,
    solar_pv_charging_ok=case when v_type in ('Ranger','Helios') then coalesce(p_pv_charging_ok,false) else false end,
    solar_panels_match_ok=case when v_type='Helios' then coalesce(p_solar_panels_match_ok,false) else false end,
    ticket_item_match_ok=case when v_type in ('Solar Stand','110V Stand','Pole') then coalesce(p_ticket_item_match_ok,false) else false end
  where id=p_item_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_it_prep_item_draft(p_item_id uuid, p_unit_tag text, p_battery_count integer, p_power_ok boolean, p_functions_ok boolean, p_safe_ok boolean, p_sim_ok boolean DEFAULT false, p_camera_app_ok boolean DEFAULT false, p_batteries_charged_ok boolean DEFAULT false, p_monitoring_ok boolean DEFAULT false, p_ticket_count_ok boolean DEFAULT false, p_sd_formatted_ok boolean DEFAULT false, p_recording_ok boolean DEFAULT false, p_mppt_updated_ok boolean DEFAULT false, p_mppt_tested_ok boolean DEFAULT false, p_pv_charging_ok boolean DEFAULT false, p_solar_panels_match_ok boolean DEFAULT false, p_ticket_item_match_ok boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_status public.prep_status; v_purpose public.prep_purpose; v_required int; v_type text; v_tag text; v_count int; v_ready boolean;
begin
  perform public.require_role(array['it'::public.app_role,'owner'::public.app_role]);
  select t.status,i.purpose,i.required_battery_count,i.equipment_type into v_status,v_purpose,v_required,v_type from public.prep_items i join public.prep_tickets t on t.id=i.prep_ticket_id where i.id=p_item_id for update of i,t;
  if not found then raise exception 'Prep item not found'; end if;
  if v_status<>'draft'::public.prep_status then raise exception 'Return the Service handoff to IT before editing. Completed Service verification is locked.'; end if;
  v_tag:=nullif(trim(p_unit_tag),''); v_count:=greatest(coalesce(p_battery_count,0),0);
  if v_tag is not null and exists(select 1 from public.prep_items oi join public.prep_tickets ot on ot.id=oi.prep_ticket_id where oi.id<>p_item_id and lower(oi.unit_tag)=lower(v_tag) and ot.status<>'closed'::public.prep_status) then raise exception 'Unit tag is already assigned to another active equipment prep'; end if;
  if v_type in ('Solar Stand') then
    v_ready:=v_tag is not null and v_count>=1 and coalesce(p_mppt_updated_ok,false) and coalesce(p_mppt_tested_ok,false) and coalesce(p_pv_charging_ok,false) and coalesce(p_solar_panels_match_ok,false) and coalesce(p_ticket_item_match_ok,false);
  elsif v_type='110V Stand' then
    v_ready:=coalesce(p_ticket_item_match_ok,false);
  elsif v_type='Pole' then
    v_ready:=v_tag is not null and coalesce(p_ticket_item_match_ok,false);
  else
    v_ready:=v_tag is not null and coalesce(p_power_ok,false) and coalesce(p_functions_ok,false) and coalesce(p_safe_ok,false) and v_count>=coalesce(v_required,0) and (v_purpose<>'DELIVERY'::public.prep_purpose or (coalesce(p_sim_ok,false) and coalesce(p_camera_app_ok,false) and coalesce(p_batteries_charged_ok,false) and coalesce(p_monitoring_ok,false) and coalesce(p_ticket_count_ok,false) and coalesce(p_sd_formatted_ok,false) and coalesce(p_recording_ok,false)));
  end if;
  update public.prep_items set unit_tag=v_tag,battery_count=v_count,power_ok=coalesce(p_power_ok,false),functions_ok=coalesce(p_functions_ok,false),safe_ok=coalesce(p_safe_ok,false),verified_by=case when v_ready then auth.uid() else null end,verified_at=case when v_ready then now() else null end,
    delivery_sim_ok=case when v_type not in ('Solar Stand','110V Stand','Pole') and v_purpose='DELIVERY'::public.prep_purpose then coalesce(p_sim_ok,false) else false end,
    delivery_camera_app_ok=case when v_type not in ('Solar Stand','110V Stand','Pole') and v_purpose='DELIVERY'::public.prep_purpose then coalesce(p_camera_app_ok,false) else false end,
    delivery_batteries_charged_ok=case when v_type not in ('Solar Stand','110V Stand','Pole') and v_purpose='DELIVERY'::public.prep_purpose then coalesce(p_batteries_charged_ok,false) else false end,
    delivery_monitoring_ok=case when v_type not in ('Solar Stand','110V Stand','Pole') and v_purpose='DELIVERY'::public.prep_purpose then coalesce(p_monitoring_ok,false) else false end,
    delivery_ticket_count_ok=case when v_type not in ('Solar Stand','110V Stand','Pole') and v_purpose='DELIVERY'::public.prep_purpose then coalesce(p_ticket_count_ok,false) else false end,
    delivery_sd_formatted_ok=case when v_type not in ('Solar Stand','110V Stand','Pole') and v_purpose='DELIVERY'::public.prep_purpose then coalesce(p_sd_formatted_ok,false) else false end,
    delivery_recording_ok=case when v_type not in ('Solar Stand','110V Stand','Pole') and v_purpose='DELIVERY'::public.prep_purpose then coalesce(p_recording_ok,false) else false end,
    solar_mppt_updated_ok=case when v_type in ('Solar Stand') then coalesce(p_mppt_updated_ok,false) else false end,
    solar_mppt_tested_ok=case when v_type in ('Solar Stand') then coalesce(p_mppt_tested_ok,false) else false end,
    solar_pv_charging_ok=case when v_type in ('Solar Stand') then coalesce(p_pv_charging_ok,false) else false end,
    solar_panels_match_ok=case when v_type in ('Solar Stand') then coalesce(p_solar_panels_match_ok,false) else false end,
    ticket_item_match_ok=case when v_type in ('Solar Stand','110V Stand','Pole') then coalesce(p_ticket_item_match_ok,false) else false end
  where id=p_item_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_it_truck_spare_battery(p_prep_id uuid, p_equipment_type text, p_battery_type text, p_qty integer, p_ready_ok boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_status public.prep_status;
  v_ticket text;
  v_qty integer:=greatest(coalesce(p_qty,0),0);
  v_type text:=btrim(coalesce(p_equipment_type,''));
  v_battery text:=btrim(coalesce(p_battery_type,''));
  v_existing public.truck_spare_batteries%rowtype;
begin
  perform public.require_role(array['it'::public.app_role,'owner'::public.app_role]);

  select status,ticket_no into v_status,v_ticket
  from public.prep_tickets where id=p_prep_id for update;
  if not found then raise exception 'Equipment prep not found'; end if;
  if v_status<>'draft'::public.prep_status then
    raise exception 'Spare batteries can only be changed before the Service handoff';
  end if;

  if not (
    (v_type='Solar Spotter' and v_battery in ('AGM 12V 110Ah','12V 350Ah'))
    or (v_type='Ranger' and v_battery='LiTime 12V 110Ah')
    or (v_type='Helios' and v_battery='Helios Battery Box')
    or (v_type='Recon 2' and v_battery='Recon II Battery')
  ) then
    raise exception 'That spare battery type does not match the selected equipment';
  end if;

  select * into v_existing
  from public.truck_spare_batteries
  where prep_ticket_id=p_prep_id
    and equipment_type=v_type
    and battery_type=v_battery
  for update;

  if found and v_existing.it_checked_out_at is not null then
    raise exception 'This spare battery batch has already been checked out by IT and is locked';
  end if;

  if v_qty=0 then
    delete from public.truck_spare_batteries
    where prep_ticket_id=p_prep_id
      and equipment_type=v_type
      and battery_type=v_battery
      and status='prepared'
      and it_checked_out_at is null;
    return;
  end if;

  insert into public.truck_spare_batteries(
    prep_ticket_id,ticket_no,equipment_type,battery_type,qty_prepared,ready_ok,
    prepared_by,prepared_by_name,status,updated_at
  )
  values(
    p_prep_id,v_ticket,v_type,v_battery,v_qty,coalesce(p_ready_ok,false),
    auth.uid(),public.actor_display_name(),'prepared',now()
  )
  on conflict(prep_ticket_id,equipment_type,battery_type)
  do update set
    qty_prepared=excluded.qty_prepared,
    ready_ok=excluded.ready_ok,
    prepared_by=excluded.prepared_by,
    prepared_by_name=excluded.prepared_by_name,
    updated_at=now();
end;
$function$

CREATE OR REPLACE FUNCTION public.save_my_helios_field_install_v1(p_prep_id uuid, p_box_mounted_ok boolean, p_pv_connected_ok boolean, p_ptz_secured_ok boolean, p_switch_pv_ok boolean, p_unit_battery_on_ok boolean, p_it_online_verified_ok boolean, p_cameras_aimed_ok boolean, p_recording_ok boolean, p_tower_20ft_ok boolean, p_mast_lock_bolt_ok boolean, p_panel_45deg_ok boolean, p_panel_bolt_ok boolean, p_4_sandbags_ok boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_role public.app_role;
  v_status public.prep_status;
  v_ticket text;
  v_is_test boolean;
  v_helios int:=0;
  v_swaps int:=0;
  v_returns int:=0;
  v_name text;
  v_complete boolean;
  v_check public.service_solar_checks%rowtype;
begin
  v_role:=public.current_app_role();
  if v_role not in ('service'::public.app_role,'owner'::public.app_role) then
    raise exception 'Service or Owner access required';
  end if;

  select status,ticket_no,coalesce(is_test,false)
  into v_status,v_ticket,v_is_test
  from public.prep_tickets
  where id=p_prep_id
  for update;

  if not found or v_status<>'released' then
    raise exception 'Helios handoff is not open for field installation';
  end if;

  if v_role='service'::public.app_role and not exists(
    select 1
    from public.job_assignments a
    where a.assigned_role='service'
      and a.assignee_user_id=auth.uid()
      and a.status in ('assigned','started')
      and (
        a.prep_ticket_id=p_prep_id
        or (
          a.prep_ticket_id is null
          and btrim(a.ticket_no)=btrim(v_ticket)
        )
      )
      and (
        (v_is_test and a.created_from='owner_test_center')
        or
        (not v_is_test and coalesce(a.created_from,'')<>'owner_test_center')
      )
  ) then
    raise exception 'This Service handoff is not actively assigned to you';
  end if;

  select *
  into v_check
  from public.service_solar_checks
  where prep_ticket_id=p_prep_id
  for update;

  if not found then
    raise exception 'Complete the Helios Service workflow before final submission';
  end if;

  if v_check.helios_field_completed_at is not null then
    return;
  end if;

  if exists(
    select 1 from public.prep_items
    where prep_ticket_id=p_prep_id
      and equipment_type='Helios'
      and purpose='SWAP'
      and swap_outcome is null
  ) then
    raise exception 'Answer whether each Helios SWAP replacement was actually installed before submitting the field installation.';
  end if;

  select
    count(*) filter(
      where equipment_type='Helios'
        and (
          purpose='DELIVERY'
          or (purpose='SWAP' and swap_outcome='installed')
        )
    ),
    count(*) filter(
      where equipment_type='Helios'
        and purpose='SWAP'
        and swap_outcome='installed'
    )
  into v_helios,v_swaps
  from public.prep_items
  where prep_ticket_id=p_prep_id;

  if v_helios<1 then
    raise exception 'No installed Helios remains on this ticket. Unused SWAP replacement units should return through IT Intake.';
  end if;

  if v_check.handoff_accepted_at is null then
    raise exception 'Accept the IT handoff after completing the yard test first';
  end if;

  if v_swaps>0 then
    select count(*) into v_returns
    from public.unit_returns r
    where btrim(r.ticket_no)=btrim(v_ticket)
      and r.equipment_type='Helios'
      and coalesce(array_length(r.return_photo_paths,1),0)>0
      and nullif(btrim(coalesce(r.return_notes,'')),'') is not null
      and coalesce(r.tag_scan_status,'')<>'mismatch'
      and not exists(
        select 1
        from public.prep_items replacement
        where replacement.prep_ticket_id=p_prep_id
          and replacement.purpose='SWAP'
          and public.normalize_unit_key(replacement.unit_tag)=public.normalize_unit_key(r.unit_tag)
      );

    if v_returns<v_swaps then
      raise exception 'Each installed Helios SWAP requires the OLD UNIT RETURNING tag photo, reason/issues/repair notes, and Service Return before final install submission';
    end if;
  end if;

  if (
    select count(*)
    from public.service_solar_evidence
    where prep_ticket_id=p_prep_id
      and category='helios_install'
      and kind='photo'
  )<v_helios then
    raise exception 'Upload at least one final installation photo for each installed Helios';
  end if;

  if not exists(
    select 1
    from public.service_solar_evidence
    where prep_ticket_id=p_prep_id
      and category='helios_install'
      and kind='signature'
  ) then
    raise exception 'A dated Service installation signature is required';
  end if;

  v_complete:=coalesce(p_box_mounted_ok,false)
    and coalesce(p_pv_connected_ok,false)
    and coalesce(p_ptz_secured_ok,false)
    and coalesce(p_switch_pv_ok,false)
    and coalesce(p_unit_battery_on_ok,false)
    and coalesce(p_it_online_verified_ok,false)
    and coalesce(p_cameras_aimed_ok,false)
    and coalesce(p_recording_ok,false)
    and coalesce(p_tower_20ft_ok,false)
    and coalesce(p_mast_lock_bolt_ok,false)
    and coalesce(p_panel_45deg_ok,false)
    and coalesce(p_panel_bolt_ok,false)
    and coalesce(p_4_sandbags_ok,false);

  if not v_complete then
    raise exception 'Complete every Helios field installation check before submitting to the Owner';
  end if;

  if not (
    coalesce(v_check.helios_field_box_mounted_ok,false)
    and coalesce(v_check.helios_field_pv_connected_ok,false)
    and coalesce(v_check.helios_field_ptz_secured_ok,false)
    and coalesce(v_check.helios_field_switch_pv_ok,false)
    and coalesce(v_check.helios_field_unit_battery_on_ok,false)
    and coalesce(v_check.helios_field_it_online_verified_ok,false)
    and coalesce(v_check.helios_field_cameras_aimed_ok,false)
    and coalesce(v_check.helios_field_panel_45deg_ok,false)
    and coalesce(v_check.helios_field_panel_bolt_ok,false)
    and coalesce(v_check.helios_field_tower_20ft_ok,false)
    and coalesce(v_check.helios_field_mast_lock_bolt_ok,false)
    and coalesce(v_check.helios_field_recording_ok,false)
    and coalesce(v_check.helios_field_4_sandbags_ok,false)
  ) then
    raise exception 'Saved Helios field-install steps are incomplete. Reload Tech Check and finish the required steps in order.';
  end if;

  v_name:=public.actor_display_name();

  update public.service_solar_checks
  set helios_field_completed_at=now(),
      helios_field_completed_by=auth.uid(),
      helios_field_completed_by_name=v_name,
      updated_at=now()
  where prep_ticket_id=p_prep_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_my_ranger_field_check_v1(p_item_id uuid, p_victron_updated_ok boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_role public.app_role;
  v_prep_id uuid;
  v_ticket text;
  v_status public.prep_status;
  v_type text;
  v_purpose public.prep_purpose;
  v_swap_outcome text;
  v_already boolean;
  v_name text;
begin
  v_role:=public.current_app_role();
  if v_role not in ('service'::public.app_role,'owner'::public.app_role) then
    raise exception 'Service or Operations Manager access required';
  end if;

  select t.id,t.ticket_no,t.status,i.equipment_type,i.purpose,i.swap_outcome,
         coalesce(i.ranger_field_victron_updated_ok,false)
  into v_prep_id,v_ticket,v_status,v_type,v_purpose,v_swap_outcome,v_already
  from public.prep_items i
  join public.prep_tickets t on t.id=i.prep_ticket_id
  where i.id=p_item_id
  for update of i,t;

  if not found then raise exception 'Ranger prep item not found'; end if;
  if v_status<>'released'::public.prep_status then
    raise exception 'Ranger field verification is available only after the IT → Service handoff';
  end if;
  if v_type<>'Ranger'
     or not (
       v_purpose='DELIVERY'::public.prep_purpose
       or (v_purpose='SWAP'::public.prep_purpose and v_swap_outcome='installed')
     ) then
    raise exception 'Ranger field verification applies only to Ranger DELIVERY or an installed Ranger SWAP';
  end if;

  if v_role='service'::public.app_role and not exists(
    select 1
    from public.job_assignments a
    where a.assigned_role='service'
      and (a.prep_ticket_id=v_prep_id or btrim(a.ticket_no)=btrim(v_ticket))
      and a.assignee_user_id=auth.uid()
      and a.status in ('assigned','started','completed')
  ) then
    raise exception 'This Ranger field job is not assigned to you';
  end if;

  if not coalesce(p_victron_updated_ok,false) then
    raise exception 'Verify the Ranger is up to date in the Victron Bluetooth app before completing the field job';
  end if;

  if v_already then
    return;
  end if;

  v_name:=public.actor_display_name();

  update public.prep_items set
    ranger_field_victron_updated_ok=true,
    ranger_field_victron_updated_by=auth.uid(),
    ranger_field_victron_updated_by_name=v_name,
    ranger_field_victron_updated_at=now()
  where id=p_item_id
    and coalesce(ranger_field_victron_updated_ok,false)=false;

  if found then
    insert into public.reports(kind,actor_id,actor_name,ticket_no,text)
    values(
      'RANGER FIELD VICTRON VERIFIED',
      auth.uid(),
      v_name,
      v_ticket,
      'Service Tech '||v_name||' verified Ranger '||
        coalesce((select unit_tag from public.prep_items where id=p_item_id),'unit')||
        ' is up to date in the Victron Bluetooth app in the field.'
    );
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_my_service_solar_check_v2(p_prep_id uuid, p_stand_tag text, p_stand_verified boolean, p_mppt_updated_ok boolean, p_mppt_tested_ok boolean, p_cerbo_updated_ok boolean, p_cerbo_online_ok boolean, p_solar_panel_count integer, p_solar_panels_verified boolean, p_battery_count integer, p_batteries_charged_ok boolean, p_solar_charging_ok boolean)
 RETURNS service_solar_checks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_role public.app_role;
  v_name text;
  v_status public.prep_status;
  v_need_solar boolean;
  v_need_stand boolean;
  v_has_helios boolean;
  v_has_ranger boolean;
  v_spotters integer;
  v_rangers integer;
  v_expected_batteries integer;
  v_expected_panels integer;
  v_assignment uuid;
  v_complete boolean;
  v_was_complete boolean := false;
  v_row public.service_solar_checks%rowtype;
  v_tag_count integer := 0;
begin
  v_role:=public.current_app_role();
  if v_role not in ('service'::public.app_role,'owner'::public.app_role) then
    raise exception 'Service or Owner access required';
  end if;

  select status into v_status from public.prep_tickets where id=p_prep_id;
  if not found then raise exception 'Equipment prep not found'; end if;
  if v_status<>'released'::public.prep_status then
    raise exception 'Solar checkout verification is only available while equipment is waiting for Service';
  end if;

  select c.need_solar,c.need_stand,c.has_helios,c.has_ranger,
         c.solar_spotter_count,c.ranger_count,c.expected_batteries,
         c.expected_solar_panels,c.assignment_id
  into v_need_solar,v_need_stand,v_has_helios,v_has_ranger,
       v_spotters,v_rangers,v_expected_batteries,v_expected_panels,v_assignment
  from public.service_solar_context_v2(p_prep_id) c;

  if not coalesce(v_need_solar,false) then
    raise exception 'This ticket does not require a Solar / Ranger / Helios Service checkout';
  end if;

  if coalesce(p_solar_panel_count,0)<0 or coalesce(p_battery_count,0)<0 then
    raise exception 'Counts cannot be negative';
  end if;

  if v_need_stand then
    select count(*) into v_tag_count
    from regexp_split_to_table(coalesce(p_stand_tag,''), E'[,\\n]+') tag
    where nullif(trim(tag),'') is not null;

    if v_spotters>0 and v_tag_count<>v_spotters then
      raise exception 'This delivery requires % Solar Stand tag(s), one for each Solar Spotter. You entered %.',v_spotters,v_tag_count;
    elsif v_spotters=0 and v_tag_count<1 then
      raise exception 'Enter the Solar Stand tag.';
    end if;
  end if;

  if v_expected_panels>0 and coalesce(p_solar_panel_count,0)<>v_expected_panels then
    raise exception 'This job requires % solar panel(s).',v_expected_panels;
  elsif v_expected_panels=0 and coalesce(p_solar_panel_count,0)<1 then
    raise exception 'Use at least one solar panel for the charging verification.';
  end if;

  if v_expected_batteries>0 and coalesce(p_battery_count,0)<>v_expected_batteries then
    raise exception 'This job requires % battery/battery-box item(s) for Service checkout.',v_expected_batteries;
  end if;

  select completed_at is not null into v_was_complete
  from public.service_solar_checks where prep_ticket_id=p_prep_id;

  v_complete :=
    (not v_need_stand or (
      v_tag_count>=1 and coalesce(p_stand_verified,false)
    ))
    and coalesce(p_mppt_updated_ok,false)
    and coalesce(p_mppt_tested_ok,false)
    and (not v_has_helios or (
      coalesce(p_cerbo_updated_ok,false)
      and coalesce(p_cerbo_online_ok,false)
    ))
    and coalesce(p_solar_panel_count,0)>0
    and coalesce(p_solar_panels_verified,false)
    and (v_expected_batteries=0 or (
      coalesce(p_battery_count,0)=v_expected_batteries
      and coalesce(p_batteries_charged_ok,false)
    ))
    and coalesce(p_solar_charging_ok,false);

  v_name:=public.actor_display_name();

  insert into public.service_solar_checks(
    prep_ticket_id,assignment_id,service_tech_id,service_tech_name,
    stand_tag,stand_verified,mppt_updated_ok,mppt_tested_ok,
    cerbo_updated_ok,cerbo_online_ok,solar_panel_count,solar_panels_verified,
    battery_count,batteries_charged_ok,solar_charging_ok,completed_at,updated_at
  )
  values(
    p_prep_id,v_assignment,auth.uid(),v_name,
    nullif(trim(coalesce(p_stand_tag,'')),''),
    coalesce(p_stand_verified,false),
    coalesce(p_mppt_updated_ok,false),
    coalesce(p_mppt_tested_ok,false),
    case when v_has_helios then coalesce(p_cerbo_updated_ok,false) else null end,
    case when v_has_helios then coalesce(p_cerbo_online_ok,false) else null end,
    coalesce(p_solar_panel_count,0),
    coalesce(p_solar_panels_verified,false),
    coalesce(p_battery_count,0),
    case when v_expected_batteries>0 then coalesce(p_batteries_charged_ok,false) else true end,
    coalesce(p_solar_charging_ok,false),
    case when v_complete then now() else null end,
    now()
  )
  on conflict(prep_ticket_id) do update set
    assignment_id=excluded.assignment_id,
    service_tech_id=auth.uid(),
    service_tech_name=v_name,
    stand_tag=excluded.stand_tag,
    stand_verified=excluded.stand_verified,
    mppt_updated_ok=excluded.mppt_updated_ok,
    mppt_tested_ok=excluded.mppt_tested_ok,
    cerbo_updated_ok=excluded.cerbo_updated_ok,
    cerbo_online_ok=excluded.cerbo_online_ok,
    solar_panel_count=excluded.solar_panel_count,
    solar_panels_verified=excluded.solar_panels_verified,
    battery_count=excluded.battery_count,
    batteries_charged_ok=excluded.batteries_charged_ok,
    solar_charging_ok=excluded.solar_charging_ok,
    completed_at=excluded.completed_at,
    updated_at=now()
  returning * into v_row;

  if v_complete and not coalesce(v_was_complete,false) then
    insert into public.reports(kind,actor_id,actor_name,ticket_no,text)
    select
      'SERVICE SOLAR / HELIOS CHECK COMPLETE',
      auth.uid(),v_name,p.ticket_no,
      'Service Tech '||v_name||
      ' completed the solar checkout: '||
      case when v_spotters>0 then v_spotters||' Solar Spotter(s), '||v_spotters||' Solar Stand(s), '||(v_spotters*4)||' batteries; ' else '' end||
      case when v_rangers>0 then v_rangers||' Ranger(s), '||v_rangers||' solar panel(s); ' else '' end||
      case when v_has_helios then 'Helios Cerbo + MPPT verified; ' else '' end||
      'MPPT updated/tested and charging verified.'
    from public.prep_tickets p where p.id=p_prep_id;
  end if;

  return v_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_my_service_solar_check_v3(p_prep_id uuid, p_stand_tag text, p_battery_configuration text, p_mppt_updated_ok boolean, p_mppt_tested_ok boolean, p_solar_panel_count integer, p_solar_panels_verified boolean, p_batteries_charged_ok boolean, p_solar_charging_ok boolean, p_cerbo_updated_ok boolean DEFAULT false, p_cerbo_online_ok boolean DEFAULT false, p_helios_battery_box_charging_ok boolean DEFAULT false)
 RETURNS service_solar_checks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_role public.app_role; v_name text; v_status public.prep_status; v_spotters int:=0; v_rangers int:=0; v_helios int:=0; v_expected_panels int:=0; v_assignment uuid; v_complete boolean; v_row public.service_solar_checks%rowtype; v_batt_count int:=0; v_desc text;
begin
 v_role:=public.current_app_role(); if v_role not in ('service'::public.app_role,'owner'::public.app_role) then raise exception 'Service or Owner access required'; end if;
 select status into v_status from public.prep_tickets where id=p_prep_id; if not found or v_status<>'released' then raise exception 'Equipment must be waiting for Service'; end if;
 select count(*) filter(where equipment_type='Solar Spotter' and purpose='DELIVERY'),count(*) filter(where equipment_type='Ranger' and purpose='DELIVERY'),count(*) filter(where equipment_type='Helios' and purpose='DELIVERY')
 into v_spotters,v_rangers,v_helios from public.prep_items where prep_ticket_id=p_prep_id;
 select id into v_assignment from public.job_assignments where assigned_role='service' and (prep_ticket_id=p_prep_id or ticket_no=(select ticket_no from public.prep_tickets where id=p_prep_id)) and (v_role='owner' or assignee_user_id=auth.uid()) order by assigned_at desc limit 1;
 v_expected_panels:=v_rangers;
 if v_spotters>0 then
   if p_battery_configuration='agm_4x_12v_110ah' then v_batt_count:=v_spotters*4; v_desc:=v_spotters||' Solar Spotter stand(s): 4 x AGM 12V 110Ah each';
   elsif p_battery_configuration='single_12v_350ah' then v_batt_count:=v_spotters; v_desc:=v_spotters||' Solar Spotter stand(s): 1 x 12V 350Ah each';
   else raise exception 'Choose the Solar Spotter battery setup: 4 x AGM 12V 110Ah OR 1 x 12V 350Ah per stand.'; end if;
 elsif v_rangers>0 and v_helios=0 then v_batt_count:=v_rangers; v_desc:=v_rangers||' x LiTime 12V 110Ah'; p_battery_configuration:='litime_1x_12v_110ah';
 elsif v_helios>0 and v_rangers=0 then v_batt_count:=v_helios; v_desc:=v_helios||' Helios battery box(es)'; p_battery_configuration:='helios_battery_box';
 else v_batt_count:=v_rangers+v_helios; v_desc:='Mixed Ranger LiTime 12V 110Ah and Helios battery-box package'; p_battery_configuration:='mixed'; end if;
 if v_spotters>0 and (nullif(trim(coalesce(p_stand_tag,'')),'') is null) then raise exception 'Enter the Solar Stand tag(s).'; end if;
 if v_rangers>0 and coalesce(p_solar_panel_count,0)<>v_expected_panels then raise exception 'This ticket requires % removable Ranger solar panel(s).',v_expected_panels; end if;
 v_complete:=coalesce(p_mppt_updated_ok,false) and coalesce(p_mppt_tested_ok,false) and coalesce(p_batteries_charged_ok,false) and coalesce(p_solar_charging_ok,false)
   and (v_rangers=0 or (p_solar_panel_count=v_expected_panels and coalesce(p_solar_panels_verified,false)))
   and (v_helios=0 or (coalesce(p_cerbo_updated_ok,false) and coalesce(p_cerbo_online_ok,false) and coalesce(p_helios_battery_box_charging_ok,false)));
 v_name:=public.actor_display_name();
 insert into public.service_solar_checks(prep_ticket_id,assignment_id,service_tech_id,service_tech_name,stand_tag,stand_verified,mppt_updated_ok,mppt_tested_ok,cerbo_updated_ok,cerbo_online_ok,solar_panel_count,solar_panels_verified,battery_count,batteries_charged_ok,solar_charging_ok,battery_configuration,battery_description,helios_battery_box_charging_ok,completed_at,updated_at)
 values(p_prep_id,v_assignment,auth.uid(),v_name,nullif(trim(coalesce(p_stand_tag,'')),''),v_spotters=0 or nullif(trim(coalesce(p_stand_tag,'')),'') is not null,p_mppt_updated_ok,p_mppt_tested_ok,case when v_helios>0 then p_cerbo_updated_ok else null end,case when v_helios>0 then p_cerbo_online_ok else null end,coalesce(p_solar_panel_count,0),case when v_rangers>0 then p_solar_panels_verified else true end,v_batt_count,p_batteries_charged_ok,p_solar_charging_ok,p_battery_configuration,v_desc,case when v_helios>0 then p_helios_battery_box_charging_ok else null end,case when v_complete then now() else null end,now())
