CREATE OR REPLACE FUNCTION public.save_service_helios_field_check_v1(p_prep_id uuid, p_field text, p_value boolean)
 RETURNS service_solar_checks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_role public.app_role;
  v_ticket text;
  v_order text[]:=array[
    'helios_field_box_mounted_ok',
    'helios_field_pv_connected_ok',
    'helios_field_ptz_secured_ok',
    'helios_field_switch_pv_ok',
    'helios_field_unit_battery_on_ok',
    'helios_field_it_online_verified_ok',
    'helios_field_cameras_aimed_ok',
    'helios_field_panel_45deg_ok',
    'helios_field_panel_bolt_ok',
    'helios_field_tower_20ft_ok',
    'helios_field_mast_lock_bolt_ok',
    'helios_field_recording_ok',
    'helios_field_4_sandbags_ok'
  ];
  v_pos integer;
  v_i integer;
  v_prior boolean;
  v_row public.service_solar_checks%rowtype;
begin
  v_role:=public.current_app_role();
  if v_role not in ('service'::public.app_role,'owner'::public.app_role) then
    raise exception 'Service or Operations Manager access required';
  end if;

  v_pos:=array_position(v_order,p_field);
  if v_pos is null then
    raise exception 'Unsupported Helios field-install check';
  end if;

  select ticket_no into v_ticket
  from public.prep_tickets
  where id=p_prep_id and status='released'
  for update;

  if not found then
    raise exception 'Helios handoff is not open for field installation';
  end if;

  if v_role='service'::public.app_role and not exists(
    select 1
    from public.job_assignments a
    where a.assigned_role='service'
      and (a.prep_ticket_id=p_prep_id or trim(a.ticket_no)=trim(v_ticket))
      and a.assignee_user_id=auth.uid()
      and a.status in ('assigned','started','completed')
  ) then
    raise exception 'This Service handoff is not assigned to you';
  end if;

  if not exists(
    select 1
    from public.service_solar_checks
    where prep_ticket_id=p_prep_id and handoff_accepted_at is not null
  ) then
    raise exception 'Accept the IT handoff before starting the field installation';
  end if;

  if coalesce(p_value,false) and v_pos>1 then
    for v_i in 1..v_pos-1 loop
      execute format(
        'select coalesce(%I,false) from public.service_solar_checks where prep_ticket_id=$1',
        v_order[v_i]
      ) into v_prior using p_prep_id;
      if not coalesce(v_prior,false) then
        raise exception 'Complete the previous Helios field-install step before this one.';
      end if;
    end loop;
  end if;

  execute format(
    'update public.service_solar_checks
       set %I=$1,
           helios_field_completed_at=null,
           helios_field_completed_by=null,
           helios_field_completed_by_name=null,
           helios_owner_verified_at=null,
           helios_owner_verified_by=null,
           helios_owner_verified_by_name=null,
           updated_at=now()
     where prep_ticket_id=$2',
    p_field
  ) using coalesce(p_value,false),p_prep_id;

  if not coalesce(p_value,false) and v_pos<array_length(v_order,1) then
    for v_i in v_pos+1..array_length(v_order,1) loop
      execute format(
        'update public.service_solar_checks
           set %I=false, updated_at=now()
         where prep_ticket_id=$1',
        v_order[v_i]
      ) using p_prep_id;
    end loop;
  end if;

  select * into v_row
  from public.service_solar_checks
  where prep_ticket_id=p_prep_id;

  return v_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_service_solar_progress_v1(p_prep_id uuid, p_field text, p_value text)
 RETURNS service_solar_checks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_role public.app_role;
  v_prep public.prep_tickets%rowtype;
  v_actor_id uuid;
  v_actor_name text;
  v_assignment_id uuid;
  v_row public.service_solar_checks%rowtype;
begin
  v_role:=public.current_app_role();
  if v_role not in ('service'::public.app_role,'owner'::public.app_role) then
    raise exception 'Service or Owner access required';
  end if;

  select * into v_prep
  from public.prep_tickets
  where id=p_prep_id and status='released';

  if not found then
    raise exception 'Equipment must be waiting for Service';
  end if;

  v_actor_id:=auth.uid();
  v_actor_name:=public.actor_display_name();

  select a.id
  into v_assignment_id
  from public.job_assignments a
  where a.assigned_role='service'
    and (a.prep_ticket_id=p_prep_id or trim(a.ticket_no)=trim(v_prep.ticket_no))
    and a.status in ('assigned','started','completed')
    and (v_role='owner'::public.app_role or a.assignee_user_id=auth.uid())
  order by case when a.prep_ticket_id=p_prep_id then 0 else 1 end,a.assigned_at desc
  limit 1;

  if coalesce(v_prep.is_test,false) and v_role='owner'::public.app_role then
    select a.id,a.assignee_user_id,coalesce(a.assignee_name,p.full_name,p.username,'Test Service')
    into v_assignment_id,v_actor_id,v_actor_name
    from public.job_assignments a
    left join public.profiles p on p.user_id=a.assignee_user_id
    where trim(a.ticket_no)=trim(v_prep.ticket_no)
      and a.assigned_role='service'
      and a.created_from='owner_test_center'
      and a.assignee_user_id is not null
    order by a.assigned_at desc
    limit 1;

    if v_actor_id is null then
      v_actor_id:=auth.uid();
      v_actor_name:=public.actor_display_name();
    end if;
  end if;

  insert into public.service_solar_checks(
    prep_ticket_id,assignment_id,service_tech_id,service_tech_name,updated_at
  ) values(
    p_prep_id,v_assignment_id,v_actor_id,v_actor_name,now()
  )
  on conflict(prep_ticket_id) do update set
    assignment_id=coalesce(excluded.assignment_id,public.service_solar_checks.assignment_id),
    service_tech_id=excluded.service_tech_id,
    service_tech_name=excluded.service_tech_name,
    updated_at=now();

  case p_field
    when 'stand_tag' then
      update public.service_solar_checks set stand_tag=nullif(trim(p_value),''),updated_at=now() where prep_ticket_id=p_prep_id;
    when 'stand_verified' then
      update public.service_solar_checks set stand_verified=coalesce(p_value::boolean,false),updated_at=now() where prep_ticket_id=p_prep_id;
    when 'battery_configuration' then
      if p_value not in ('agm_4x_12v_110ah','single_12v_350ah','litime_1x_12v_110ah','helios_battery_box','mixed') then
        raise exception 'Invalid battery configuration';
      end if;
      update public.service_solar_checks set battery_configuration=p_value,updated_at=now() where prep_ticket_id=p_prep_id;
    when 'mppt_updated_ok' then
      update public.service_solar_checks set mppt_updated_ok=coalesce(p_value::boolean,false),updated_at=now() where prep_ticket_id=p_prep_id;
    when 'mppt_tested_ok' then
      update public.service_solar_checks set mppt_tested_ok=coalesce(p_value::boolean,false),updated_at=now() where prep_ticket_id=p_prep_id;
    when 'cerbo_updated_ok' then
      update public.service_solar_checks set cerbo_updated_ok=coalesce(p_value::boolean,false),updated_at=now() where prep_ticket_id=p_prep_id;
    when 'cerbo_online_ok' then
      update public.service_solar_checks set cerbo_online_ok=coalesce(p_value::boolean,false),updated_at=now() where prep_ticket_id=p_prep_id;
    when 'solar_panel_count' then
      update public.service_solar_checks set solar_panel_count=greatest(coalesce(p_value::int,0),0),updated_at=now() where prep_ticket_id=p_prep_id;
    when 'solar_panels_verified' then
      update public.service_solar_checks set solar_panels_verified=coalesce(p_value::boolean,false),updated_at=now() where prep_ticket_id=p_prep_id;
    when 'batteries_charged_ok' then
      update public.service_solar_checks set batteries_charged_ok=coalesce(p_value::boolean,false),updated_at=now() where prep_ticket_id=p_prep_id;
    when 'solar_charging_ok' then
      update public.service_solar_checks set solar_charging_ok=coalesce(p_value::boolean,false),updated_at=now() where prep_ticket_id=p_prep_id;
    when 'helios_battery_box_charging_ok' then
      update public.service_solar_checks set helios_battery_box_charging_ok=coalesce(p_value::boolean,false),updated_at=now() where prep_ticket_id=p_prep_id;
    when 'helios_yard_pv_connected_ok' then
      update public.service_solar_checks set helios_yard_pv_connected_ok=coalesce(p_value::boolean,false),updated_at=now() where prep_ticket_id=p_prep_id;
    when 'helios_yard_switch_pv_ok' then
      update public.service_solar_checks set helios_yard_switch_pv_ok=coalesce(p_value::boolean,false),updated_at=now() where prep_ticket_id=p_prep_id;
    when 'helios_yard_victron_bluetooth_ok' then
      update public.service_solar_checks set helios_yard_victron_bluetooth_ok=coalesce(p_value::boolean,false),updated_at=now() where prep_ticket_id=p_prep_id;
    when 'helios_yard_updates_status_ok' then
      update public.service_solar_checks set helios_yard_updates_status_ok=coalesce(p_value::boolean,false),updated_at=now() where prep_ticket_id=p_prep_id;
    when 'helios_yard_solar_charging_ok' then
      update public.service_solar_checks set helios_yard_solar_charging_ok=coalesce(p_value::boolean,false),updated_at=now() where prep_ticket_id=p_prep_id;
    when 'helios_yard_ptz_wrapped_ok' then
      update public.service_solar_checks set helios_yard_ptz_wrapped_ok=coalesce(p_value::boolean,false),updated_at=now() where prep_ticket_id=p_prep_id;
    else
      raise exception 'Unsupported Service pre-trip field';
  end case;

  select * into v_row
  from public.service_solar_checks
  where prep_ticket_id=p_prep_id;

  return v_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.service_accept_truck_restock_v1(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_req public.service_truck_restock_requests%rowtype;
  v_profile public.profiles%rowtype;
  v_name text;
  v_key text;
begin
  perform public.require_role(array['service'::public.app_role]);
  select * into v_profile from public.profiles where user_id=auth.uid() and active=true;
  v_name:=coalesce(v_profile.full_name,v_profile.username,'Service Tech');

  select * into v_req
  from public.service_truck_restock_requests
  where id=p_request_id and service_tech_id=auth.uid()
  for update;
  if not found then raise exception 'Truck restock request not found for your account.'; end if;
  if v_req.status<>'ready' then raise exception 'IT has not marked this restock READY yet.'; end if;

  if v_req.item_kind='unit' then
    if nullif(btrim(coalesce(v_req.replacement_unit_tag,'')),'') is null then
      raise exception 'IT did not record the replacement unit tag.';
    end if;

    update public.service_truck_units
    set unit_tag=v_req.replacement_unit_tag,status='assigned',old_unit_tag=null,
        assigned_by=v_req.prepared_by,assigned_by_name=v_req.prepared_by_name,
        assigned_at=now(),updated_at=now()
    where service_tech_id=auth.uid() and equipment_type=v_req.item_type;

    insert into public.service_truck_unit_history(service_tech_id,equipment_type,unit_tag,event,ticket_no,old_unit_tag,actor_id,actor_name)
    values(auth.uid(),v_req.item_type,v_req.replacement_unit_tag,'RESTOCK ACCEPTED ON TRUCK',v_req.original_ticket_no,v_req.old_unit_tag,auth.uid(),v_name);

    select equipment_key into v_key from public.equipment_master
    where trim(unit_tag)=trim(v_req.replacement_unit_tag)
      and lower(coalesce(workflow_type,canonical_family))=lower(v_req.item_type)
    limit 1;
    if v_key is not null then
      insert into public.unit_registry(unit_key,unit_tag,equipment_type,lifecycle_status,current_holder_id,current_holder_name,last_event,current_site,updated_at)
      values(v_key,v_req.replacement_unit_tag,v_req.item_type,'assigned_to_tech',auth.uid(),v_name,'Assigned to permanent Service Truck inventory',null,now())
      on conflict(unit_key) do update
      set lifecycle_status='assigned_to_tech',current_holder_id=auth.uid(),current_holder_name=v_name,
          last_event=excluded.last_event,current_site=null,ticket_no=null,updated_at=now();
    end if;

  elsif v_req.item_kind='sim' then
    if v_req.sim_slot_no not between 1 and 3 then raise exception 'IT did not record the SIM truck slot.'; end if;
    if nullif(btrim(coalesce(v_req.replacement_sim_number,'')),'') is null then
      raise exception 'IT did not record the replacement SIM number.';
    end if;

    update public.service_truck_sims
    set sim_number=v_req.replacement_sim_number,
        status='assigned',
        last_used_ticket_no=null,
        last_used_at=null,
        assigned_by=v_req.prepared_by,
        assigned_by_name=v_req.prepared_by_name,
        assigned_at=now(),
        updated_at=now()
    where service_tech_id=auth.uid() and slot_no=v_req.sim_slot_no;

    insert into public.service_truck_sim_history(
      service_tech_id,slot_no,sim_number,event,ticket_no,actor_id,actor_name
    ) values(
      auth.uid(),v_req.sim_slot_no,v_req.replacement_sim_number,'RESTOCK ACCEPTED ON TRUCK',
      v_req.original_ticket_no,auth.uid(),v_name
    );

  else
    if coalesce(v_req.qty_issued,0)<=0 then raise exception 'IT did not record an issued quantity.'; end if;
    if v_req.item_type='Recon Battery' then
      update public.service_truck_stock set recon_battery_qty=recon_battery_qty+v_req.qty_issued,updated_by=auth.uid(),updated_by_name=v_name,updated_at=now() where service_tech_id=auth.uid();
    elsif v_req.item_type='AGM 12V 110Ah' then
      update public.service_truck_stock set agm_12v_110ah_qty=agm_12v_110ah_qty+v_req.qty_issued,updated_by=auth.uid(),updated_by_name=v_name,updated_at=now() where service_tech_id=auth.uid();
    elsif v_req.item_type='LiTime 12V 100Ah' then
      update public.service_truck_stock set litime_12v_100ah_qty=litime_12v_100ah_qty+v_req.qty_issued,updated_by=auth.uid(),updated_by_name=v_name,updated_at=now() where service_tech_id=auth.uid();
    end if;
  end if;

  update public.service_truck_restock_requests
  set status='issued',issued_at=now(),updated_at=now()
  where id=p_request_id;

  insert into public.reports(kind,actor_id,actor_name,ticket_no,text)
  values(
    'SERVICE TRUCK RESTOCK RECEIVED',auth.uid(),v_name,v_req.original_ticket_no,
    case
      when v_req.item_kind='unit' then v_req.item_type||' '||v_req.replacement_unit_tag||' received from IT and assigned to permanent truck inventory.'
      when v_req.item_kind='sim' then 'SIM '||v_req.replacement_sim_number||' received from IT and assigned to permanent truck slot '||v_req.sim_slot_no||'.'
      else v_req.qty_issued||' × '||v_req.item_type||' received from IT for permanent truck inventory.'
    end
  );

  return public.service_departure_readiness_v1(auth.uid());
end;
$function$

CREATE OR REPLACE FUNCTION public.service_link_offline_failed_return_v1(p_escalation_id uuid, p_return_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_row public.field_escalations%rowtype;
  v_return public.unit_returns%rowtype;
  v_item public.prep_items%rowtype;
  v_name text;
  v_role public.app_role;
begin
  perform public.require_role(array['service'::public.app_role,'owner'::public.app_role]);
  v_role:=public.current_app_role();
  v_name:=public.actor_display_name();

  select * into v_row from public.field_escalations where id=p_escalation_id for update;
  if not found then raise exception 'Offline-unit escalation not found.'; end if;
  if v_row.status<>'backup_swap_authorized' or v_row.resolved_at is not null then
    raise exception 'This escalation is not waiting for completion of an authorized backup swap.';
  end if;
  if v_role='service'::public.app_role and v_row.service_tech_id is distinct from auth.uid() then
    raise exception 'This offline-unit escalation belongs to another Service Tech.';
  end if;

  select * into v_item from public.prep_items where id=v_row.backup_prep_item_id for update;
  if not found or v_item.spare_outcome is distinct from 'used' then
    raise exception 'Mark the authorized backup unit USED FOR SWAP before linking the failed-unit return.';
  end if;

  select * into v_return from public.unit_returns where id=p_return_id for update;
  if not found then raise exception 'Failed-unit IT Intake return not found.'; end if;
  if v_return.ticket_no is distinct from v_row.ticket_no
     or public.normalize_unit_key(v_return.unit_tag) is distinct from public.normalize_unit_key(v_row.unit_tag)
  then
    raise exception 'The failed-unit return must match this MHelpDesk ticket and offline unit.';
  end if;
  if v_role='service'::public.app_role and v_return.service_tech_id is distinct from auth.uid() then
    raise exception 'This failed-unit return belongs to another Service Tech.';
  end if;

  update public.field_escalations
  set failed_return_id=p_return_id,
      status='failed_unit_in_it_intake',
      resolved_at=now()
  where id=p_escalation_id;

  insert into public.reports(kind,actor_id,actor_name,ticket_no,text)
  values(
    'OFFLINE UNIT - AUTHORIZED SWAP COMPLETED',auth.uid(),v_name,v_row.ticket_no,
    'Service Tech '||v_name||' completed the IT-authorized backup swap. BACKUP '||
      coalesce(v_row.backup_equipment_type,'Unit')||' Unit '||coalesce(v_row.backup_unit_tag,'—')||
      ' was used. Failed Unit '||v_row.unit_tag||' entered Service Return → IT Intake.'
  );

  if v_role='owner'::public.app_role then
    insert into public.reports(kind,actor_id,actor_name,ticket_no,text)
    values(
      'OWNER WORKFLOW OVERRIDE',auth.uid(),v_name,v_row.ticket_no,
      'Owner intentionally linked the failed-unit IT Intake return to the authorized backup swap for Unit '||v_row.unit_tag||'.'
    );
  end if;

  return jsonb_build_object('id',p_escalation_id,'status','failed_unit_in_it_intake','failed_return_id',p_return_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.service_resolve_swap_unit_v1(p_item_id uuid, p_used boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_role public.app_role;
  v_item public.prep_items%rowtype;
  v_prep public.prep_tickets%rowtype;
  v_name text;
  v_key text;
  v_it record;
begin
  v_role:=public.current_app_role();
  if v_role not in ('service'::public.app_role,'owner'::public.app_role) then raise exception 'Service or Owner access required'; end if;

  select * into v_item from public.prep_items where id=p_item_id for update;
  if not found or v_item.purpose<>'SWAP'::public.prep_purpose then raise exception 'SWAP replacement unit not found'; end if;
  if nullif(trim(coalesce(v_item.unit_tag,'')),'') is null then raise exception 'The SWAP replacement unit must have a unit tag before Service can resolve it'; end if;

  select * into v_prep from public.prep_tickets where id=v_item.prep_ticket_id;
  if not found or v_prep.status not in ('released'::public.prep_status,'closed'::public.prep_status) then raise exception 'Service must receive the IT handoff before resolving the SWAP unit'; end if;

  if v_role='service'::public.app_role and not exists(
    select 1 from public.job_assignments a
    where trim(a.ticket_no)=trim(v_prep.ticket_no)
      and a.assigned_role='service' and a.assignee_user_id=auth.uid()
      and a.status in ('assigned','started')
  ) and v_prep.closed_by is distinct from auth.uid() then raise exception 'This SWAP is assigned to another Service Tech'; end if;

  if v_item.swap_outcome is not null then
    if (p_used and v_item.swap_outcome='installed') or (not p_used and v_item.swap_outcome='returned_unused') then
      return jsonb_build_object('item_id',v_item.id,'outcome',v_item.swap_outcome,'already_recorded',true);
    end if;
    raise exception 'This SWAP unit already has a different outcome. Owner review is required to change it.';
  end if;

  v_name:=public.actor_display_name();
  v_key:=public.normalize_unit_key(v_item.unit_tag);

  if p_used then
    update public.prep_items
    set swap_outcome='installed', swap_outcome_by=auth.uid(), swap_outcome_by_name=v_name, swap_outcome_at=now(),
        swap_installed_site=nullif(trim(coalesce(v_prep.site,'')),''),
        swap_site_registration_status='pending_it', swap_site_registered_by=null, swap_site_registered_by_name=null, swap_site_registered_at=null
    where id=v_item.id;

    update public.unit_registry
    set lifecycle_status='deployed', ticket_no=v_prep.ticket_no, prep_ticket_id=v_prep.id, prep_item_id=v_item.id,
        current_holder_id=null, current_holder_name=null,
        current_site=nullif(trim(coalesce(v_prep.site,'')),''),
        last_event='Service confirmed SWAP installed at '||coalesce(nullif(trim(coalesce(v_prep.site,'')),''),'customer site')||
          ' on MHelpDesk #'||v_prep.ticket_no||' — IT site registration pending',
        updated_at=now()
    where unit_key=v_key;

    update public.asset_inventory
    set availability_status='assigned', assigned_to=null, assigned_to_name=null,
        last_event='SWAP installed at '||coalesce(nullif(trim(coalesce(v_prep.site,'')),''),'customer site')||
          ' — IT site registration pending · MHelpDesk #'||v_prep.ticket_no, updated_at=now()
    where unit_key=v_key;

    for v_it in select user_id from public.profiles where active=true and archived_at is null and role='it' loop
      perform public.enqueue_app_notification(v_it.user_id,'swap_site_registration','SWAP installed — register unit at site',
        'Service Tech '||v_name||' confirmed '||v_item.equipment_type||' '||v_item.unit_tag||' was installed at '||
        coalesce(nullif(trim(coalesce(v_prep.site,'')),''),'the customer site')||' for MHelpDesk #'||v_prep.ticket_no||
        '. Complete the IT site-registration task.',null,v_prep.ticket_no,v_item.unit_tag);
    end loop;

    insert into public.reports(kind,actor_id,actor_name,ticket_no,text)
    values('SWAP REPLACEMENT INSTALLED',auth.uid(),v_name,v_prep.ticket_no,
      'Service confirmed replacement '||v_item.equipment_type||' '||v_item.unit_tag||' was installed at '||
      coalesce(nullif(trim(coalesce(v_prep.site,'')),''),'the customer site')||
      '. The OLD field unit must return through IT Intake. IT site registration is now ready.');

    return jsonb_build_object('item_id',v_item.id,'outcome','installed','site',v_prep.site,'old_unit_return_required',true,'it_site_registration_required',true);
  else
    update public.prep_items
    set swap_outcome='returned_unused', swap_outcome_by=auth.uid(), swap_outcome_by_name=v_name, swap_outcome_at=now(),
        swap_installed_site=null, swap_site_registration_status='not_required',
        swap_site_registered_by=null, swap_site_registered_by_name=null, swap_site_registered_at=null
    where id=v_item.id;

    update public.unit_registry
    set lifecycle_status='assigned_to_tech', ticket_no=v_prep.ticket_no, prep_ticket_id=v_prep.id, prep_item_id=v_item.id,
        current_holder_id=auth.uid(), current_holder_name=v_name, current_site=null,
        last_event='Service confirmed prepared SWAP replacement was not used — physical Service Return to IT Intake required',
        updated_at=now()
    where unit_key=v_key;

    insert into public.reports(kind,actor_id,actor_name,ticket_no,text)
    values('SWAP REPLACEMENT NOT USED',auth.uid(),v_name,v_prep.ticket_no,
      'Service confirmed replacement '||v_item.equipment_type||' '||v_item.unit_tag||
      ' was NOT installed. Service must now physically return this exact replacement through Service Return → IT Intake.');

    return jsonb_build_object('item_id',v_item.id,'outcome','returned_unused','replacement_return_required',true,'old_unit_return_required',false,'it_site_registration_required',false);
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.service_return_110v_stand_to_shop_v1(p_ticket_no text, p_unit_tag text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_return_photo_paths text[] DEFAULT '{}'::text[], p_return_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_id uuid := coalesce(p_return_id,gen_random_uuid());
  v_tag text := nullif(trim(coalesce(p_unit_tag,'')),'');
  v_key text := public.normalize_unit_key(p_unit_tag);
  v_name text;
  v_asset public.asset_inventory%rowtype;
begin
  perform public.require_role(array['service'::public.app_role,'owner'::public.app_role]);

  if nullif(trim(coalesce(p_ticket_no,'')),'') is null then
    raise exception 'MHelpDesk ticket number is required';
  end if;

  if coalesce(cardinality(p_return_photo_paths),0)<1 then
    raise exception 'Take a clear 110V Stand return photo before adding it back to Shop';
  end if;

  if v_tag is not null and exists(
    select 1 from public.unit_returns
    where trim(ticket_no)=trim(p_ticket_no)
      and equipment_type='110V Stand'
      and public.normalize_unit_key(unit_tag)=v_key
  ) then
    raise exception 'This 110V Stand has already been returned for MHelpDesk #% ', trim(p_ticket_no);
  end if;

  v_name:=public.actor_display_name();

  insert into public.unit_returns(
    id,ticket_no,unit_tag,equipment_type,
    service_tech_id,service_tech_name,return_notes,return_photo_paths,
    status,completed_at,updated_at
  )
  values(
    v_id,trim(p_ticket_no),v_tag,'110V Stand',
    auth.uid(),v_name,nullif(trim(coalesce(p_notes,'')),''),
    coalesce(p_return_photo_paths,'{}'::text[]),
    'completed',now(),now()
  );

  if v_tag is not null then
    select * into v_asset
    from public.asset_inventory
    where unit_key=v_key
    for update;

    if found then
      insert into public.asset_inventory_history(
        unit_key,unit_tag,action,from_status,to_status,
        from_user_id,from_user_name,actor_id,actor_name,notes
      ) values(
        v_asset.unit_key,v_asset.unit_tag,'service_returned_110v_to_shop',
        v_asset.availability_status,'shop',
        v_asset.assigned_to,v_asset.assigned_to_name,
        auth.uid(),v_name,
        '110V Stand returned directly to Shop by Service on MHelpDesk #'||trim(p_ticket_no)
      );

      update public.asset_inventory
      set availability_status='shop',
          assigned_to=null,
          assigned_to_name=null,
          last_event='110V Stand returned directly to Shop by Service',
          updated_at=now()
      where unit_key=v_key;
    end if;
  end if;

  insert into public.reports(kind,actor_id,actor_name,ticket_no,text)
  values(
    '110V STAND RETURNED TO SHOP',
    auth.uid(),v_name,trim(p_ticket_no),
    'Service Tech '||v_name||' returned a 110V Stand directly to Shop Inventory'||
      case when v_tag is null then ' with no physical tag.' else ' with tag '||v_tag||'.' end
  );

  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.service_return_110v_stand_to_shop_v2(p_ticket_no text, p_unit_tag text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_return_photo_paths text[] DEFAULT '{}'::text[], p_return_id uuid DEFAULT NULL::uuid, p_pole_bent boolean DEFAULT false, p_brick_fascia_damaged boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_id uuid := coalesce(p_return_id,gen_random_uuid());
  v_tag text := nullif(trim(coalesce(p_unit_tag,'')),'');
  v_key text := public.normalize_unit_key(p_unit_tag);
  v_name text;
  v_asset public.asset_inventory%rowtype;
  v_owner record;
  v_damage text;
  v_notes text;
begin
  perform public.require_role(array['service'::public.app_role,'owner'::public.app_role]);
  if nullif(trim(coalesce(p_ticket_no,'')),'') is null then raise exception 'MHelpDesk ticket number is required'; end if;
  if coalesce(cardinality(p_return_photo_paths),0)<1 then raise exception 'Take a clear 110V Stand return photo before adding it back to Shop'; end if;
  if v_tag is not null and exists(
    select 1 from public.unit_returns where trim(ticket_no)=trim(p_ticket_no)
      and equipment_type='110V Stand' and public.normalize_unit_key(unit_tag)=v_key
  ) then raise exception 'This 110V Stand has already been returned for MHelpDesk #% ',trim(p_ticket_no); end if;

  v_name:=public.actor_display_name();
  v_damage:=trim(both ' · ' from
    case when coalesce(p_pole_bent,false) then 'POLE BENT' else '' end ||
    case when coalesce(p_pole_bent,false) and coalesce(p_brick_fascia_damaged,false) then ' · ' else '' end ||
    case when coalesce(p_brick_fascia_damaged,false) then 'BRICK FASCIA DAMAGED' else '' end);
  v_notes:=nullif(trim(coalesce(p_notes,'')),'');
  if v_damage<>'' then
    v_notes:=trim(both ' ' from coalesce(v_notes||E'\n','')||'[110V STAND CONDITION: '||v_damage||']');
  end if;

  insert into public.unit_returns(id,ticket_no,unit_tag,equipment_type,service_tech_id,service_tech_name,return_notes,return_photo_paths,status,completed_at,updated_at)
  values(v_id,trim(p_ticket_no),v_tag,'110V Stand',auth.uid(),v_name,v_notes,coalesce(p_return_photo_paths,'{}'::text[]),'completed',now(),now());

  if v_tag is not null then
    select * into v_asset from public.asset_inventory where unit_key=v_key for update;
    if found then
      insert into public.asset_inventory_history(unit_key,unit_tag,action,from_status,to_status,from_user_id,from_user_name,actor_id,actor_name,notes)
      values(v_asset.unit_key,v_asset.unit_tag,'service_returned_110v_to_shop',v_asset.availability_status,'shop',
        v_asset.assigned_to,v_asset.assigned_to_name,auth.uid(),v_name,
        '110V Stand returned directly to Shop by Service on MHelpDesk #'||trim(p_ticket_no)||
        case when v_damage<>'' then ' · Owner notified: '||v_damage else '' end);
      update public.asset_inventory set availability_status='shop',assigned_to=null,assigned_to_name=null,
        last_event='110V Stand returned directly to Shop by Service'||case when v_damage<>'' then ' · DAMAGE REPORTED TO OWNER' else '' end,
        updated_at=now() where unit_key=v_key;
    end if;
  end if;

  if v_damage<>'' then
    for v_owner in select user_id from public.profiles where active=true and role='owner' loop
      perform public.enqueue_app_notification(v_owner.user_id,'owner_action','110V Stand damage reported',
        'Service Tech '||v_name||' reported '||v_damage||' on the 110V Stand returned for MHelpDesk #'||trim(p_ticket_no)||
        '. Review the return photos and notes. No repair/disposition action is assumed by Tech Check.',
        null,trim(p_ticket_no),v_tag);
    end loop;
  end if;

  insert into public.reports(kind,actor_id,actor_name,ticket_no,text)
  values(case when v_damage<>'' then '110V STAND DAMAGE REPORTED TO OWNER' else '110V STAND RETURNED TO SHOP' end,
    auth.uid(),v_name,trim(p_ticket_no),
    'Service Tech '||v_name||' returned a 110V Stand directly to Shop Inventory'||
    case when v_tag is null then ' with no physical tag.' else ' with tag '||v_tag||'.' end||
    case when v_damage<>'' then ' Owner notification required and created for: '||v_damage||'.' else '' end);
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.service_return_110v_stand_to_shop_v3(p_ticket_no text, p_unit_tag text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_return_photo_paths text[] DEFAULT '{}'::text[], p_return_id uuid DEFAULT NULL::uuid, p_damage_found boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_id uuid:=coalesce(p_return_id,gen_random_uuid());
  v_tag text:=nullif(btrim(coalesce(p_unit_tag,'')),'');
  v_key text:=public.normalize_unit_key(p_unit_tag);
  v_name text;
  v_asset public.asset_inventory%rowtype;
  v_owner record;
  v_status text:=case when coalesce(p_damage_found,false) then 'needs_replacement' else 'completed' end;
begin
  perform public.require_role(array['service'::public.app_role,'owner'::public.app_role]);

  if nullif(btrim(coalesce(p_ticket_no,'')),'') is null then
    raise exception 'MHelpDesk ticket number is required';
  end if;
  if coalesce(cardinality(p_return_photo_paths),0)<1 then
    raise exception 'Take a clear 110V Stand return photo first';
  end if;
  if coalesce(p_damage_found,false)
     and nullif(btrim(coalesce(p_notes,'')),'') is null then
    raise exception 'Describe the 110V Stand damage so the Owner knows what needs replacement.';
  end if;
  if coalesce(p_damage_found,false)
     and not exists (
       select 1 from unnest(coalesce(p_return_photo_paths,'{}'::text[])) p(path)
       where p.path ilike '%damage%'
     ) then
    raise exception 'Add at least one close-up damage photo before marking this stand as damaged.';
  end if;
  if v_tag is not null and exists(
    select 1 from public.unit_returns
    where btrim(ticket_no)=btrim(p_ticket_no)
      and equipment_type='110V Stand'
      and public.normalize_unit_key(unit_tag)=v_key
  ) then
    raise exception 'This 110V Stand has already been returned for MHelpDesk #% ',btrim(p_ticket_no);
  end if;

  v_name:=public.actor_display_name();

  insert into public.unit_returns(
    id,ticket_no,unit_tag,equipment_type,
    service_tech_id,service_tech_name,return_notes,return_photo_paths,
    status,completed_at,updated_at
  )
  values(
    v_id,btrim(p_ticket_no),v_tag,'110V Stand',
    auth.uid(),v_name,nullif(btrim(coalesce(p_notes,'')),''),
    coalesce(p_return_photo_paths,'{}'::text[]),
    v_status,case when v_status='completed' then now() else null end,now()
  );

  if v_tag is not null then
    select * into v_asset from public.asset_inventory where unit_key=v_key for update;
    if found then
      insert into public.asset_inventory_history(
        unit_key,unit_tag,action,from_status,to_status,
        from_user_id,from_user_name,actor_id,actor_name,notes
      )
      values(
        v_asset.unit_key,v_asset.unit_tag,
        case when v_status='needs_replacement' then 'damage_needs_replacement' else 'service_returned_110v_to_shop' end,
        v_asset.availability_status,
        case when v_status='needs_replacement' then 'maintenance' else 'shop' end,
        v_asset.assigned_to,v_asset.assigned_to_name,
        auth.uid(),v_name,
        case when v_status='needs_replacement'
          then '110V Stand returned damaged on MHelpDesk #'||btrim(p_ticket_no)||'. Owner notified; stand needs replacement/repair.'
          else '110V Stand returned directly to Shop by Service on MHelpDesk #'||btrim(p_ticket_no)
        end
      );

      update public.asset_inventory
      set availability_status=case when v_status='needs_replacement' then 'maintenance' else 'shop' end,
          assigned_to=null,
          assigned_to_name=null,
          last_event=case when v_status='needs_replacement'
            then '110V Stand damage confirmed — replacement/repair required — Owner notified'
            else '110V Stand returned directly to Shop by Service'
          end,
          updated_at=now()
      where unit_key=v_key;
    end if;
  end if;

  if v_status='needs_replacement' then
    for v_owner in select user_id from public.profiles where active=true and role='owner'
    loop
      perform public.enqueue_app_notification(
        v_owner.user_id,
        'owner_action',
        'Damaged 110V Stand needs replacement',
        'Service Tech '||v_name||' returned a damaged 110V Stand for MHelpDesk #'||btrim(p_ticket_no)||
          case when v_tag is null then ' (no tag).' else ' Tag '||v_tag||'.' end||
          ' It is NOT available in Shop Inventory. '||btrim(p_notes),
        null,btrim(p_ticket_no),v_tag
      );
    end loop;
  end if;

  insert into public.reports(kind,actor_id,actor_name,ticket_no,text)
  values(
    case when v_status='needs_replacement'
      then 'DAMAGED 110V STAND NEEDS REPLACEMENT'
      else '110V STAND RETURNED TO SHOP'
    end,
    auth.uid(),v_name,btrim(p_ticket_no),
    case when v_status='needs_replacement'
      then 'Service Tech '||v_name||' returned a damaged 110V Stand. It was placed in Maintenance / Needs Replacement and was not made available in Shop Inventory. '||btrim(p_notes)
      else 'Service Tech '||v_name||' returned a 110V Stand directly to Shop Inventory'||
        case when v_tag is null then ' with no physical tag.' else ' with tag '||v_tag||'.' end
    end
  );

  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.service_save_my_truck_inventory_v1(p_units jsonb, p_sims jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_name text; v_type text; v_slot integer; v_value text;
begin
  perform public.require_role(array['service'::public.app_role]);
  select coalesce(full_name,username,'Service Tech') into v_name from public.profiles where user_id=auth.uid() and active=true and role::text='service';
  if v_name is null then raise exception 'Active Service Tech account required.'; end if;
  perform public.ensure_service_truck_baseline_v1(auth.uid());

  foreach v_type in array array['Sniper','Ranger','Spotter','Solar Spotter'] loop
    v_value:=nullif(btrim(coalesce(p_units->>v_type,'')),'');
    if v_value is not null and exists(select 1 from public.service_truck_units u where u.service_tech_id<>auth.uid() and u.status='assigned' and lower(btrim(u.unit_tag))=lower(v_value)) then
      raise exception 'Unit % is already assigned to another Service truck.',v_value;
    end if;
    update public.service_truck_units set unit_tag=v_value,status=case when v_value is null then 'unassigned' else 'assigned' end,assigned_by=auth.uid(),assigned_by_name=v_name,assigned_at=now(),updated_at=now()
    where service_tech_id=auth.uid() and equipment_type=v_type;
  end loop;

  for v_slot in 1..3 loop
    v_value:=nullif(btrim(coalesce(p_sims->>(v_slot::text),'')),'');
    if v_value is not null and exists(select 1 from public.service_truck_sims s where s.status='assigned' and lower(btrim(s.sim_number))=lower(v_value) and not(s.service_tech_id=auth.uid() and s.slot_no=v_slot)) then
      raise exception 'SIM % is already assigned to another Service truck slot.',v_value;
    end if;
    update public.service_truck_sims set sim_number=v_value,status=case when v_value is null then 'unassigned' else 'assigned' end,assigned_by=auth.uid(),assigned_by_name=v_name,assigned_at=now(),updated_at=now()
    where service_tech_id=auth.uid() and slot_no=v_slot;
  end loop;

  update public.service_truck_inventory_checks set ready=false,updated_at=now()
  where service_tech_id=auth.uid() and check_date=timezone('America/Chicago',now())::date;
  perform public.close_stale_service_truck_restock_requests_v1();
  return public.service_departure_readiness_v1(auth.uid());
end
$function$

CREATE OR REPLACE FUNCTION public.service_save_my_truck_inventory_v2(p_units jsonb, p_sims jsonb, p_recon_battery_qty integer, p_agm_12v_110ah_qty integer, p_litime_12v_100ah_qty integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_name text;
  v_type text;
  v_slot integer;
  v_value text;
begin
  perform public.require_role(array['service'::public.app_role]);

  select coalesce(full_name,username,'Service Tech')
  into v_name
  from public.profiles
  where user_id=auth.uid() and active=true and role::text='service';

  if v_name is null then
    raise exception 'Active Service Tech account required.';
  end if;

  if coalesce(p_recon_battery_qty,-1)<0
     or coalesce(p_agm_12v_110ah_qty,-1)<0
     or coalesce(p_litime_12v_100ah_qty,-1)<0 then
    raise exception 'Enter valid battery quantities before saving.';
  end if;

  perform public.ensure_service_truck_baseline_v1(auth.uid());

  foreach v_type in array array['Sniper','Ranger','Spotter','Solar Spotter']
  loop
    v_value:=nullif(btrim(coalesce(p_units->>v_type,'')),'');
    if v_value is not null and exists(
      select 1
      from public.service_truck_units u
      where u.service_tech_id<>auth.uid()
        and u.status='assigned'
        and lower(btrim(coalesce(u.unit_tag,'')))=lower(v_value)
    ) then
      raise exception 'Unit % is already assigned to another Service truck.',v_value;
    end if;

    update public.service_truck_units
    set unit_tag=v_value,
        status=case when v_value is null then 'unassigned' else 'assigned' end,
        assigned_by=auth.uid(),
        assigned_by_name=v_name,
        assigned_at=now(),
        updated_at=now()
    where service_tech_id=auth.uid() and equipment_type=v_type;
  end loop;

  for v_slot in 1..3
  loop
    v_value:=nullif(btrim(coalesce(p_sims->>(v_slot::text),'')),'');
    if v_value is not null and exists(
      select 1
      from public.service_truck_sims s
      where s.status='assigned'
        and lower(btrim(coalesce(s.sim_number,'')))=lower(v_value)
        and not(s.service_tech_id=auth.uid() and s.slot_no=v_slot)
    ) then
      raise exception 'SIM % is already assigned to another Service truck slot.',v_value;
    end if;

    update public.service_truck_sims
    set sim_number=v_value,
        status=case when v_value is null then 'unassigned' else 'assigned' end,
        assigned_by=auth.uid(),
        assigned_by_name=v_name,
        assigned_at=now(),
        updated_at=now()
    where service_tech_id=auth.uid() and slot_no=v_slot;
  end loop;

  update public.service_truck_stock
  set recon_battery_qty=p_recon_battery_qty,
      agm_12v_110ah_qty=p_agm_12v_110ah_qty,
      litime_12v_100ah_qty=p_litime_12v_100ah_qty,
      updated_by=auth.uid(),
      updated_by_name=v_name,
      updated_at=now()
  where service_tech_id=auth.uid();

  update public.service_truck_inventory_checks
  set ready=false,updated_at=now()
  where service_tech_id=auth.uid()
    and check_date=timezone('America/Chicago',now())::date;

  perform public.close_stale_service_truck_restock_requests_v1();

  return public.service_departure_readiness_v1(auth.uid());
end
$function$

