CREATE OR REPLACE FUNCTION public.service_use_permanent_truck_unit_v1(p_ticket_no text, p_equipment_type text, p_old_unit_tag text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_profile public.profiles%rowtype;
  v_assignment public.job_assignments%rowtype;
  v_truck public.service_truck_units%rowtype;
  v_request_id uuid;
  v_name text;
  v_key text;
begin
  perform public.require_role(array['service'::public.app_role]);
  if p_equipment_type not in ('Sniper','Ranger','Spotter','Solar Spotter') then raise exception 'Invalid permanent truck unit type.'; end if;
  if nullif(trim(coalesce(p_old_unit_tag,'')),'') is null then raise exception 'Enter the old customer/site unit being returned to IT.'; end if;

  select * into v_profile from public.profiles where user_id=auth.uid() and active=true;
  v_name:=coalesce(v_profile.full_name,v_profile.username,'Service Tech');

  select * into v_assignment
  from public.job_assignments
  where assignee_user_id=auth.uid() and assigned_role='service' and status='started' and trim(ticket_no)=trim(p_ticket_no)
  order by assigned_at desc limit 1;
  if not found then raise exception 'Open and start this Service job before using permanent truck inventory.'; end if;

  select * into v_truck from public.service_truck_units
  where service_tech_id=auth.uid() and equipment_type=p_equipment_type
  for update;
  if not found or v_truck.status<>'assigned' or nullif(trim(coalesce(v_truck.unit_tag,'')),'') is null then
    raise exception 'No ready % is assigned to your truck.',p_equipment_type;
  end if;

  update public.service_truck_units
  set status='used_restock_due',
      last_used_ticket_no=p_ticket_no,
      last_used_at=now(),
      old_unit_tag=trim(p_old_unit_tag),
      updated_at=now()
  where service_tech_id=auth.uid() and equipment_type=p_equipment_type;

  insert into public.service_truck_restock_requests(
    service_tech_id,service_tech_name,item_kind,item_type,qty_needed,used_unit_tag,original_ticket_no,old_unit_tag,status,reason
  ) values(
    auth.uid(),v_name,'unit',p_equipment_type,1,v_truck.unit_tag,trim(p_ticket_no),trim(p_old_unit_tag),'awaiting_return',
    'Permanent truck unit was installed at a Service job. Old field unit must be returned through normal IT Intake before truck replenishment.'
  ) returning id into v_request_id;

  insert into public.service_truck_unit_history(service_tech_id,equipment_type,unit_tag,event,ticket_no,old_unit_tag,actor_id,actor_name)
  values(auth.uid(),p_equipment_type,v_truck.unit_tag,'USED AT JOB - RESTOCK REQUIRED',trim(p_ticket_no),trim(p_old_unit_tag),auth.uid(),v_name);

  update public.service_truck_inventory_checks
  set ready=false,
      missing_items=coalesce(missing_items,'[]'::jsonb)||jsonb_build_array(jsonb_build_object(
        'kind','unit','item_type',p_equipment_type,'used_unit_tag',v_truck.unit_tag,'need',1,'message','Permanent truck unit used at job; IT replenishment required.'
      )),
      updated_at=now()
  where service_tech_id=auth.uid() and check_date=timezone('America/Chicago',now())::date;

  select equipment_key into v_key
  from public.equipment_master
  where trim(unit_tag)=trim(v_truck.unit_tag)
    and lower(coalesce(workflow_type,canonical_family))=lower(p_equipment_type)
  limit 1;

  if v_key is not null then
    insert into public.unit_registry(unit_key,unit_tag,equipment_type,lifecycle_status,ticket_no,current_holder_id,current_holder_name,last_event,current_site,updated_at)
    values(v_key,v_truck.unit_tag,p_equipment_type,'deployed',trim(p_ticket_no),null,null,'Permanent Service Truck unit used at field job',v_assignment.site,now())
    on conflict(unit_key) do update
    set lifecycle_status='deployed',ticket_no=excluded.ticket_no,current_holder_id=null,current_holder_name=null,
        last_event=excluded.last_event,current_site=excluded.current_site,updated_at=now();
  end if;

  insert into public.reports(kind,actor_id,actor_name,ticket_no,text)
  values('SERVICE TRUCK UNIT USED',auth.uid(),v_name,trim(p_ticket_no),
    p_equipment_type||' '||v_truck.unit_tag||' was used from permanent truck inventory. Old unit '||trim(p_old_unit_tag)||' must return through IT Intake. Replacement is required before the truck is ready again.');

  return jsonb_build_object('request_id',v_request_id,'used_unit_tag',v_truck.unit_tag,'old_unit_tag',trim(p_old_unit_tag),'status','awaiting_return');
end;
$function$

CREATE OR REPLACE FUNCTION public.service_use_truck_sim_v1(p_ticket_no text, p_slot_no integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_profile public.profiles%rowtype;
  v_sim public.service_truck_sims%rowtype;
  v_name text;
begin
  perform public.require_role(array['service'::public.app_role]);
  if p_slot_no not between 1 and 3 then raise exception 'Choose one of the three truck SIM cards.'; end if;
  if not exists(
    select 1 from public.job_assignments
    where assignee_user_id=auth.uid() and assigned_role='service' and status='started'
      and trim(ticket_no)=trim(p_ticket_no)
  ) then raise exception 'Open and start this Service job before recording a truck SIM used.'; end if;

  select * into v_profile from public.profiles where user_id=auth.uid() and active=true;
  v_name:=coalesce(v_profile.full_name,v_profile.username,'Service Tech');
  perform public.ensure_service_truck_baseline_v1(auth.uid());

  select * into v_sim
  from public.service_truck_sims
  where service_tech_id=auth.uid() and slot_no=p_slot_no
  for update;

  if not found or v_sim.status<>'assigned' or nullif(btrim(coalesce(v_sim.sim_number,'')),'') is null then
    raise exception 'That truck SIM slot is not currently assigned and ready.';
  end if;

  update public.service_truck_sims
  set status='used_restock_due',
      last_used_ticket_no=trim(p_ticket_no),
      last_used_at=now(),
      updated_at=now()
  where service_tech_id=auth.uid() and slot_no=p_slot_no;

  if exists(
    select 1 from public.service_truck_restock_requests
    where service_tech_id=auth.uid() and item_kind='sim' and sim_slot_no=p_slot_no
      and status not in ('issued','cancelled')
  ) then
    update public.service_truck_restock_requests
    set qty_needed=1,
        used_sim_number=v_sim.sim_number,
        original_ticket_no=trim(p_ticket_no),
        status='requested',
        replacement_sim_number=null,
        reason='Permanent truck SIM used at field job and requires replacement.',
        updated_at=now()
    where service_tech_id=auth.uid() and item_kind='sim' and sim_slot_no=p_slot_no
      and status not in ('issued','cancelled');
  else
    insert into public.service_truck_restock_requests(
      service_tech_id,service_tech_name,item_kind,item_type,qty_needed,sim_slot_no,
      used_sim_number,original_ticket_no,status,reason
    ) values(
      auth.uid(),v_name,'sim','SIM Card',1,p_slot_no,
      v_sim.sim_number,trim(p_ticket_no),'requested',
      'Permanent truck SIM used at field job and requires replacement.'
    );
  end if;

  update public.service_truck_inventory_checks
  set ready=false,
      missing_items=coalesce(missing_items,'[]'::jsonb)||jsonb_build_array(jsonb_build_object(
        'kind','sim','item_type','SIM Card','slot_no',p_slot_no,'sim_number',v_sim.sim_number,
        'status','used_restock_due','last_used_ticket_no',trim(p_ticket_no),'message','SIM used at field job and requires IT replacement.'
      )),
      updated_at=now()
  where service_tech_id=auth.uid() and check_date=timezone('America/Chicago',now())::date;

  insert into public.service_truck_sim_history(
    service_tech_id,slot_no,sim_number,event,ticket_no,actor_id,actor_name
  ) values(
    auth.uid(),p_slot_no,v_sim.sim_number,'SIM USED FROM TRUCK',trim(p_ticket_no),auth.uid(),v_name
  );

  insert into public.reports(kind,actor_id,actor_name,ticket_no,text)
  values(
    'SERVICE TRUCK SIM USED',auth.uid(),v_name,trim(p_ticket_no),
    'Truck SIM slot '||p_slot_no||' · SIM '||v_sim.sim_number||' was used at the field job. IT replacement is required.'
  );

  return public.service_departure_readiness_v1(auth.uid());
end;
$function$

CREATE OR REPLACE FUNCTION public.set_my_job_assignment_status(p_assignment_id uuid, p_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_assignment public.job_assignments%rowtype;
  v_departure jsonb;
begin
  if p_status not in ('started','completed') then
    raise exception 'Invalid assignment status.';
  end if;

  select * into v_assignment
  from public.job_assignments
  where id=p_assignment_id
    and assignee_user_id=auth.uid()
  for update;

  if not found then
    raise exception 'Assignment not found or not assigned to you.';
  end if;

  if p_status='started' then
    if v_assignment.status='started' then
      return;
    end if;
    if v_assignment.status<>'assigned' then
      raise exception 'Assignment is no longer available to start.';
    end if;

    if v_assignment.assigned_role='it'
       and lower(coalesce(v_assignment.work_type,''))='pickup'
       and not exists(
         select 1 from public.unit_returns r
         where trim(r.ticket_no)=trim(v_assignment.ticket_no)
           and r.status='waiting_it'
       ) then
      raise exception 'WAITING FOR SERVICE RETURN. IT cannot start this pickup until Service checks returned equipment into IT Intake.';
    end if;

    if v_assignment.assigned_role='service'
       and coalesce(v_assignment.requires_it_handoff,false)
       and not exists(
         select 1 from public.prep_tickets p
         where trim(p.ticket_no)=trim(v_assignment.ticket_no)
           and p.status in ('released','closed')
       ) then
      raise exception 'WAITING FOR IT HANDOFF. Service cannot start until IT completes the required handoff.';
    end if;

    if v_assignment.assigned_role='service' then
      v_departure:=public.service_departure_readiness_v1(auth.uid());
      if coalesce((v_departure->>'departure_ready')::boolean,false) is not true then
        raise exception 'NOT READY TO LEAVE SHOP. Complete the daily Truck / Trailer Inspection and required permanent truck inventory check/restock before starting a new Service job.';
      end if;
    end if;

    update public.job_assignments
    set status='started',
        started_at=coalesce(started_at,now()),
        updated_at=now()
    where id=p_assignment_id;
    return;
  end if;

  -- completed
  if v_assignment.status='completed' then
    return;
  end if;
  if v_assignment.status<>'started' then
    raise exception 'Start this Tech Check job before completing it.';
  end if;

  if lower(coalesce(v_assignment.work_type,''))='pickup' then
    raise exception 'PICKUP completion is controlled by Service Return and IT Intake. Finish the required return/intake steps instead of manually completing the assignment.';
  end if;

  if v_assignment.assigned_role='service' then
    if exists(
      select 1
      from public.field_escalations f
      where trim(f.ticket_no)=trim(v_assignment.ticket_no)
        and f.resolved_at is null
    ) then
      raise exception 'This Service job has an unresolved field escalation. Resolve it before completing Tech Check.';
    end if;

    if coalesce(v_assignment.requires_it_handoff,false)
       or v_assignment.prep_ticket_id is not null then
      if not exists(
        select 1
        from public.prep_tickets p
        where (
          p.id=v_assignment.prep_ticket_id
          or trim(p.ticket_no)=trim(v_assignment.ticket_no)
        )
        and p.status='closed'
      ) then
        raise exception 'This Service job must finish through the authoritative equipment/field closeout before the assignment can be completed.';
      end if;
    end if;
  end if;

  update public.job_assignments
  set status='completed',
      completed_at=coalesce(completed_at,now()),
      updated_at=now()
  where id=p_assignment_id
    and status='started';
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_my_service_truck_inventory_check_v3(p_unit_confirmations jsonb, p_sim_confirmations jsonb, p_recon_battery_qty integer, p_agm_12v_110ah_qty integer, p_litime_12v_100ah_qty integer, p_battery_12v_35ah_qty integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_profile public.profiles%rowtype;v_today date:=timezone('America/Chicago',now())::date;v_type text;v_row public.service_truck_units%rowtype;v_sim public.service_truck_sims%rowtype;v_slot integer;v_confirm jsonb;v_missing jsonb:='[]'::jsonb;v_ready boolean:=true;v_name text;
begin
 perform public.require_role(array['service'::public.app_role]);
 select * into v_profile from public.profiles where user_id=auth.uid() and active=true;
 v_name:=coalesce(v_profile.full_name,v_profile.username,'Service Tech');
 perform public.ensure_service_truck_baseline_v1(auth.uid());
 if not (public.service_departure_readiness_v1(auth.uid())->>'inspection_ready')::boolean then raise exception 'Complete and pass the Truck / Trailer Inspection first.'; end if;
 if coalesce(p_recon_battery_qty,-1)<0 or coalesce(p_agm_12v_110ah_qty,-1)<0 or coalesce(p_litime_12v_100ah_qty,-1)<0 or coalesce(p_battery_12v_35ah_qty,-1)<0 then raise exception 'Enter the actual battery quantities physically on the truck.'; end if;
 update public.service_truck_stock set recon_battery_qty=p_recon_battery_qty,agm_12v_110ah_qty=p_agm_12v_110ah_qty,litime_12v_100ah_qty=p_litime_12v_100ah_qty,battery_12v_35ah_qty=p_battery_12v_35ah_qty,updated_by=auth.uid(),updated_by_name=v_name,updated_at=now() where service_tech_id=auth.uid();
 foreach v_type in array array['Sniper','Ranger','Spotter','Solar Spotter'] loop
   select * into v_row from public.service_truck_units where service_tech_id=auth.uid() and equipment_type=v_type for update;
   v_confirm:=coalesce(p_unit_confirmations->v_type,'{}'::jsonb);
   if v_row.unit_tag is null or v_row.status<>'assigned' or coalesce((v_confirm->>'confirmed')::boolean,false) is not true or lower(regexp_replace(coalesce(v_confirm->>'unit_tag',''),'[^a-zA-Z0-9]','','g'))<>lower(regexp_replace(coalesce(v_row.unit_tag,''),'[^a-zA-Z0-9]','','g')) then
     v_ready:=false;v_missing:=v_missing||jsonb_build_array(jsonb_build_object('kind','unit','item_type',v_type,'assigned_unit_tag',v_row.unit_tag,'status',v_row.status,'message','Enter and physically verify the permanent truck unit number.'));
   end if;
 end loop;
 for v_slot in 1..3 loop
   select * into v_sim from public.service_truck_sims where service_tech_id=auth.uid() and slot_no=v_slot for update;
   v_confirm:=coalesce(p_sim_confirmations->(v_slot::text),'{}'::jsonb);
   if v_sim.sim_number is null or btrim(v_sim.sim_number)='' or v_sim.status<>'assigned' or coalesce((v_confirm->>'confirmed')::boolean,false) is not true or lower(regexp_replace(coalesce(v_confirm->>'sim_number',''),'[^a-zA-Z0-9]','','g'))<>lower(regexp_replace(coalesce(v_sim.sim_number,''),'[^a-zA-Z0-9]','','g')) then
     v_ready:=false;v_missing:=v_missing||jsonb_build_array(jsonb_build_object('kind','sim','item_type','SIM Card','slot_no',v_slot,'sim_number',v_sim.sim_number,'status',v_sim.status,'message','Enter and physically verify the exact SIM number.'));
   end if;
 end loop;
 if p_recon_battery_qty<25 then v_ready:=false;v_missing:=v_missing||jsonb_build_array(jsonb_build_object('kind','battery','item_type','Recon Battery','have',p_recon_battery_qty,'required',25,'need',25-p_recon_battery_qty));end if;
 if p_agm_12v_110ah_qty<4 then v_ready:=false;v_missing:=v_missing||jsonb_build_array(jsonb_build_object('kind','battery','item_type','AGM 12V 110Ah','have',p_agm_12v_110ah_qty,'required',4,'need',4-p_agm_12v_110ah_qty));end if;
 if p_litime_12v_100ah_qty<2 then v_ready:=false;v_missing:=v_missing||jsonb_build_array(jsonb_build_object('kind','battery','item_type','LiTime 12V 100Ah','have',p_litime_12v_100ah_qty,'required',2,'need',2-p_litime_12v_100ah_qty));end if;
 if p_battery_12v_35ah_qty<4 then v_ready:=false;v_missing:=v_missing||jsonb_build_array(jsonb_build_object('kind','battery','item_type','12V 35Ah','have',p_battery_12v_35ah_qty,'required',4,'need',4-p_battery_12v_35ah_qty));end if;
 insert into public.service_truck_inventory_checks(service_tech_id,check_date,unit_confirmations,sim_confirmations,recon_battery_qty,agm_12v_110ah_qty,litime_12v_100ah_qty,battery_12v_35ah_qty,ready,missing_items,submitted_at,updated_at)
 values(auth.uid(),v_today,coalesce(p_unit_confirmations,'{}'::jsonb),coalesce(p_sim_confirmations,'{}'::jsonb),p_recon_battery_qty,p_agm_12v_110ah_qty,p_litime_12v_100ah_qty,p_battery_12v_35ah_qty,v_ready,v_missing,now(),now())
 on conflict(service_tech_id,check_date) do update set unit_confirmations=excluded.unit_confirmations,sim_confirmations=excluded.sim_confirmations,recon_battery_qty=excluded.recon_battery_qty,agm_12v_110ah_qty=excluded.agm_12v_110ah_qty,litime_12v_100ah_qty=excluded.litime_12v_100ah_qty,battery_12v_35ah_qty=excluded.battery_12v_35ah_qty,ready=excluded.ready,missing_items=excluded.missing_items,submitted_at=now(),updated_at=now();
 perform public.close_stale_service_truck_restock_requests_v1();
 insert into public.reports(kind,actor_id,actor_name,text) values(case when v_ready then 'SERVICE TRUCK INVENTORY - READY' else 'SERVICE TRUCK INVENTORY - SHORT' end,auth.uid(),v_name,case when v_ready then 'Permanent truck inventory physically verified, including 4 × 12V 35Ah batteries.' else 'Truck inventory is short or not verified. No restock request was sent; the live count remains visible until corrected.' end);
 return public.service_departure_readiness_v1(auth.uid());
end
$function$

CREATE OR REPLACE FUNCTION public.sync_pickup_assignment_completion_from_return_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_ticket text:=btrim(coalesce(new.ticket_no,''));
  v_assignment public.job_assignments%rowtype;
  v_manifest_required integer;
  v_required integer;
  v_recorded integer;
  v_processed integer;
  v_waiting integer;
  v_qty integer;
  v_actor_name text;
begin
  if v_ticket='' then
    return new;
  end if;

  v_actor_name:=public.actor_display_name();

  for v_assignment in
    select a.*
    from public.job_assignments a
    where btrim(a.ticket_no)=v_ticket
      and a.status in ('assigned','started')
      and lower(coalesce(a.work_type,''))='pickup'
      and a.assigned_role in ('service','it')
    order by a.assigned_at
    for update
  loop
    select coalesce(sum(
      case
        when lower(coalesce(x.item->>'category','')) in ('device','stand')
          or coalesce(x.item->>'label','') in ('Sniper','Ranger','Helios','Solar Spotter','Spotter','Recon 2','Recon II','110V Stand','Solar Stand','Pole','Solar Pole')
          or coalesce(x.item->>'equipment_type','') in ('Sniper','Ranger','Helios','Solar Spotter','Spotter','Recon 2','Recon II','110V Stand','Solar Stand','Pole','Solar Pole')
        then case
          when coalesce(x.item->>'qty','') ~ '^[0-9]+$' then greatest(0,(x.item->>'qty')::integer)
          when coalesce(x.item->>'quantity','') ~ '^[0-9]+$' then greatest(0,(x.item->>'quantity')::integer)
          else 1
        end
        else 0
      end
    ),0)::integer
    into v_manifest_required
    from jsonb_array_elements(coalesce(v_assignment.equipment_manifest,'[]'::jsonb)) as x(item);

    v_required:=case
      when v_manifest_required>0 then v_manifest_required
      else greatest(0,coalesce(v_assignment.requested_unit_count,0))
    end;

    -- No guessed completion. If the assignment does not contain an authoritative
    -- equipment quantity, leave it active for Owner review/correction.
    if v_required<=0 then
      continue;
    end if;

    if v_assignment.assigned_role='service' then
      select count(*)::integer
      into v_recorded
      from public.unit_returns r
      where btrim(r.ticket_no)=v_ticket;

      if v_recorded>=v_required then
        update public.job_assignments
        set status='completed',completed_at=coalesce(completed_at,now()),updated_at=now()
        where id=v_assignment.id
          and status in ('assigned','started');

        if found then
          insert into public.reports(kind,actor_id,actor_name,ticket_no,text)
          values(
            'JOB ASSIGNMENT COMPLETED',
            auth.uid(),
            v_actor_name,
            v_ticket,
            'Service pickup assignment completed after all '||v_required||' authoritative equipment return record'||case when v_required=1 then '' else 's' end||' were saved.'
          );
        end if;
      end if;
    else
      select
        count(*) filter(where r.status in ('pending_mhelp_inventory','needs_replacement','completed'))::integer,
        count(*) filter(where r.status='waiting_it')::integer
      into v_processed,v_waiting
      from public.unit_returns r
      where btrim(r.ticket_no)=v_ticket;

      if v_processed>=v_required and v_waiting=0 then
        update public.job_assignments
        set status='completed',completed_at=coalesce(completed_at,now()),updated_at=now()
        where id=v_assignment.id
          and status in ('assigned','started');

        if found then
          insert into public.reports(kind,actor_id,actor_name,ticket_no,text)
          values(
            'JOB ASSIGNMENT COMPLETED',
            auth.uid(),
            v_actor_name,
            v_ticket,
            'IT pickup/intake assignment completed after all '||v_required||' authoritative equipment return record'||case when v_required=1 then '' else 's' end||' finished IT Intake.'
          );
        end if;
      end if;
    end if;
  end loop;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_unit_registry_from_prep_item()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_key text;
  v_old_key text;
  v_ticket record;
  v_existing public.unit_registry%rowtype;
  v_status text;
  v_event text;
  v_unlinked boolean := false;
begin
  if tg_op='UPDATE' then
    v_old_key := public.normalize_unit_key(old.unit_tag);
    v_key := public.normalize_unit_key(new.unit_tag);
    if v_old_key<>'' and v_old_key is distinct from v_key then
      delete from public.unit_registry
      where unit_key=v_old_key
        and prep_item_id=old.id
        and lifecycle_status='it_prep';
    end if;
  else
    v_key := public.normalize_unit_key(new.unit_tag);
  end if;

  if v_key='' then return new; end if;

  select id,ticket_no,status,closed_by,closed_by_name
  into v_ticket
  from public.prep_tickets
  where id=new.prep_ticket_id;

  if not found then return new; end if;

  v_status := case v_ticket.status::text
    when 'draft' then 'it_prep'
    when 'released' then 'ready_for_service'
    else 'deployed'
  end;

  v_event := case v_status
    when 'it_prep' then 'IT prep assigned'
    when 'ready_for_service' then 'IT released to Service'
    else 'Service deployed to field'
  end;

  select * into v_existing
  from public.unit_registry
  where unit_key=v_key
  for update;

  if found and v_existing.prep_item_id is distinct from new.id then
    v_unlinked :=
      v_existing.prep_item_id is null
      and v_existing.prep_ticket_id is null
      and v_existing.ticket_no is null
      and v_existing.current_holder_id is null
      and nullif(btrim(coalesce(v_existing.current_site,'')),'') is null;

    if not v_unlinked then
      if v_existing.lifecycle_status='assigned_to_tech'
         and v_existing.current_holder_id is distinct from auth.uid() then
        raise exception 'That unit is already checked out to another technician. Use a different available unit.';
      end if;

      if v_existing.lifecycle_status not in ('shop_inventory','assigned_to_tech') then
        raise exception 'That unit is already being used on another active job. Use a different available unit.';
      end if;
    end if;
  end if;

  insert into public.unit_registry(
    unit_key,unit_tag,equipment_type,lifecycle_status,ticket_no,
    prep_ticket_id,prep_item_id,current_holder_id,current_holder_name,last_event,updated_at
  )
  values(
    v_key,btrim(new.unit_tag),new.equipment_type,v_status,v_ticket.ticket_no,
    new.prep_ticket_id,new.id,
    case when v_status='deployed' then v_ticket.closed_by else null end,
    case when v_status='deployed' then v_ticket.closed_by_name else null end,
    v_event,now()
  )
  on conflict (unit_key) do update set
    unit_tag=excluded.unit_tag,
    equipment_type=excluded.equipment_type,
    lifecycle_status=excluded.lifecycle_status,
    ticket_no=excluded.ticket_no,
    prep_ticket_id=excluded.prep_ticket_id,
    prep_item_id=excluded.prep_item_id,
    current_holder_id=excluded.current_holder_id,
    current_holder_name=excluded.current_holder_name,
    last_event=excluded.last_event,
    updated_at=now();

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_it_prep_item_definition(p_item_id uuid, p_equipment_type text, p_purpose text, p_recon_battery_count integer DEFAULT NULL::integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_status public.prep_status;
  v_required integer;
  v_purpose public.prep_purpose;
begin
  perform public.require_role(array['it'::public.app_role,'owner'::public.app_role]);
  select t.status into v_status from public.prep_items i join public.prep_tickets t on t.id=i.prep_ticket_id where i.id=p_item_id for update of i,t;
  if not found then raise exception 'Prep item not found'; end if;
  if v_status<>'draft'::public.prep_status then raise exception 'Only draft equipment prep can be changed'; end if;
  if p_equipment_type not in ('Sniper','Ranger','Helios','Solar Spotter','Spotter','Recon 2','110V Stand','Solar Stand') then raise exception 'Invalid equipment type'; end if;
  if p_purpose not in ('BACKUP','SWAP','DELIVERY') then raise exception 'Invalid purpose'; end if;
  v_purpose := p_purpose::public.prep_purpose;
  if p_equipment_type='110V Stand' and v_purpose<>'SWAP'::public.prep_purpose then raise exception '110V Stand is available for SWAP only'; end if;
  if p_equipment_type='Solar Stand' and v_purpose not in ('SWAP'::public.prep_purpose,'DELIVERY'::public.prep_purpose) then raise exception 'Solar Stand is available for SWAP or DELIVERY only'; end if;
  v_required := case p_equipment_type
    when 'Sniper' then 2
    when 'Ranger' then 1
    when 'Solar Spotter' then 4
    when 'Helios' then 1
    when 'Recon 2' then greatest(1,coalesce(p_recon_battery_count,1))
    else 0 end;
  update public.prep_items set equipment_type=p_equipment_type,purpose=v_purpose,required_battery_count=v_required,
    unit_tag=null,battery_count=null,power_ok=null,functions_ok=null,safe_ok=null,verified_by=null,verified_at=null,
    delivery_sim_ok=false,delivery_camera_app_ok=false,delivery_batteries_charged_ok=false,delivery_monitoring_ok=false,
    delivery_ticket_count_ok=false,delivery_sd_formatted_ok=false,delivery_recording_ok=false
  where id=p_item_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_it_prep_structure(p_prep_id uuid, p_ticket_no text, p_site text, p_items jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_status public.prep_status;
  v_old_no text;
  v_row jsonb;
  v_id uuid;
  v_type text;
  v_purpose public.prep_purpose;
  v_required int;
  v_order int := 0;
  v_old record;
begin
  perform public.require_role(array['it'::public.app_role,'owner'::public.app_role]);
  select status,ticket_no into v_status,v_old_no from public.prep_tickets where id=p_prep_id for update;
  if not found then raise exception 'Equipment prep not found'; end if;
  if v_status<>'draft'::public.prep_status then raise exception 'Return the Service handoff to IT before editing. Completed Service verification is locked.'; end if;
  if nullif(trim(p_ticket_no),'') is null then raise exception 'MHelpDesk ticket number is required'; end if;
  if jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 then raise exception 'At least one equipment item is required'; end if;

  if exists(
    select 1 from jsonb_array_elements(p_items) x
    where nullif(x->>'id','') is not null
      and not exists(select 1 from public.prep_items i where i.id=(x->>'id')::uuid and i.prep_ticket_id=p_prep_id)
  ) then raise exception 'One or more equipment items do not belong to this prep'; end if;

  if exists(
    select 1 from (
      select x->>'id' as id,count(*) c
      from jsonb_array_elements(p_items) x
      where nullif(x->>'id','') is not null
      group by x->>'id'
      having count(*)>1
    ) d
  ) then raise exception 'Duplicate equipment item in edit request'; end if;

  delete from public.prep_items i
  where i.prep_ticket_id=p_prep_id
    and not exists(
      select 1 from jsonb_array_elements(p_items) x
      where nullif(x->>'id','') is not null and (x->>'id')::uuid=i.id
    );

  update public.prep_items set item_order=item_order+10000 where prep_ticket_id=p_prep_id;

  for v_row in select value from jsonb_array_elements(p_items)
  loop
    v_order := v_order+1;
    v_type := v_row->>'equipment_type';
    if v_type not in ('Sniper','Ranger','Helios','Solar Spotter','Spotter','Recon 2','110V Stand','Solar Stand') then raise exception 'Invalid equipment type'; end if;
    if (v_row->>'purpose') not in ('BACKUP','SWAP','DELIVERY') then raise exception 'Invalid purpose'; end if;
    v_purpose := (v_row->>'purpose')::public.prep_purpose;
    if v_type='110V Stand' and v_purpose<>'SWAP'::public.prep_purpose then raise exception '110V Stand is available for SWAP only'; end if;
    if v_type='Solar Stand' and v_purpose not in ('SWAP'::public.prep_purpose,'DELIVERY'::public.prep_purpose) then raise exception 'Solar Stand is available for SWAP or DELIVERY only'; end if;
    v_required := case v_type
      when 'Sniper' then 2
      when 'Ranger' then 1
      when 'Solar Spotter' then 4
      when 'Helios' then 1
      when 'Recon 2' then greatest(1,coalesce((v_row->>'required_battery_count')::int,1))
      else 0 end;
    v_id := nullif(v_row->>'id','')::uuid;

    if v_id is null then
      insert into public.prep_items(prep_ticket_id,item_order,equipment_type,purpose,required_battery_count)
      values(p_prep_id,v_order,v_type,v_purpose,v_required);
    else
      select * into v_old from public.prep_items where id=v_id and prep_ticket_id=p_prep_id;
      if v_old.equipment_type is distinct from v_type
         or v_old.purpose is distinct from v_purpose
         or v_old.required_battery_count is distinct from v_required then
        update public.prep_items set
          item_order=v_order,equipment_type=v_type,purpose=v_purpose,required_battery_count=v_required,
          unit_tag=null,battery_count=null,power_ok=null,functions_ok=null,safe_ok=null,verified_by=null,verified_at=null,
          service_battery_count=null,service_unit_confirmed=null,service_verified_by=null,service_verified_at=null,
          delivery_sim_ok=false,delivery_camera_app_ok=false,delivery_batteries_charged_ok=false,
          delivery_monitoring_ok=false,delivery_ticket_count_ok=false,delivery_sd_formatted_ok=false,delivery_recording_ok=false
        where id=v_id;
      else
        update public.prep_items set item_order=v_order where id=v_id;
      end if;
    end if;
  end loop;

  update public.prep_tickets set ticket_no=trim(p_ticket_no),site=nullif(trim(p_site),'') where id=p_prep_id;
  insert into public.reports(kind,actor_id,actor_name,ticket_no,text)
  values('IT EQUIPMENT PREP EDITED',auth.uid(),public.actor_display_name(),trim(p_ticket_no),'IT corrected MHelpDesk ticket details and/or equipment requirements before Service checkout verification.');
end;
$function$

CREATE OR REPLACE FUNCTION public.verify_delivery_item_checks(p_item_id uuid, p_sim_ok boolean, p_camera_app_ok boolean, p_batteries_charged_ok boolean, p_monitoring_ok boolean, p_ticket_count_ok boolean, p_sd_formatted_ok boolean, p_recording_ok boolean, p_customer_email_app_ok boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_status public.prep_status;
  v_purpose public.prep_purpose;
  v_type text;
  v_customer_deploy boolean;
  v_hardware_deploy boolean;
begin
  perform public.require_role(array['it'::public.app_role,'owner'::public.app_role]);
  select t.status,i.purpose,i.equipment_type
  into v_status,v_purpose,v_type
  from public.prep_items i
  join public.prep_tickets t on t.id=i.prep_ticket_id
  where i.id=p_item_id;
  if not found then raise exception 'Deployable prep item not found'; end if;
  if v_status <> 'draft' then raise exception 'Only draft equipment prep can be verified'; end if;

  v_customer_deploy := v_purpose='DELIVERY'::public.prep_purpose
    or (v_type in ('Sniper','Spotter','Recon 2','Ranger') and v_purpose='SWAP'::public.prep_purpose);
  v_hardware_deploy := v_purpose='BACKUP'::public.prep_purpose or v_customer_deploy;

  if not v_hardware_deploy then
    raise exception 'Deploy-ready checks apply only to DELIVERY, BACKUP, or supported camera-unit SWAP items';
  end if;

  if v_customer_deploy then
    if not coalesce(p_sim_ok,false)
       or not coalesce(p_camera_app_ok,false)
       or not coalesce(p_customer_email_app_ok,false)
       or (v_type<>'Spotter' and not coalesce(p_batteries_charged_ok,false))
       or not coalesce(p_monitoring_ok,false)
       or not coalesce(p_ticket_count_ok,false)
       or not coalesce(p_sd_formatted_ok,false)
       or not coalesce(p_recording_ok,false)
    then raise exception 'All customer deployment readiness checks are required'; end if;
  else
    if not coalesce(p_sim_ok,false)
       or not coalesce(p_camera_app_ok,false)
       or (v_type<>'Spotter' and not coalesce(p_batteries_charged_ok,false))
       or not coalesce(p_sd_formatted_ok,false)
       or not coalesce(p_recording_ok,false)
    then raise exception 'BACKUP units must be hardware-ready before leaving in the Service truck'; end if;
  end if;

  update public.prep_items set
    delivery_sim_ok=coalesce(p_sim_ok,false),
    delivery_camera_app_ok=coalesce(p_camera_app_ok,false),
    delivery_customer_email_app_ok=case when v_customer_deploy then coalesce(p_customer_email_app_ok,false) else false end,
    delivery_batteries_charged_ok=case when v_type='Spotter' then true else coalesce(p_batteries_charged_ok,false) end,
    delivery_monitoring_ok=case when v_customer_deploy then coalesce(p_monitoring_ok,false) else false end,
    delivery_ticket_count_ok=case when v_customer_deploy then coalesce(p_ticket_count_ok,false) else false end,
    delivery_sd_formatted_ok=coalesce(p_sd_formatted_ok,false),
    delivery_recording_ok=coalesce(p_recording_ok,false)
  where id=p_item_id;
end;
$function$

